(3,	'{\"en\":\"\\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ru\":\"\\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ua\":\"\\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\"}'),
(4,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\"}'),
(5,	'{\"en\":\"\\u041c\\u043e\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u041c\\u043e\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u041c\\u043e\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0448\\u0438\\u043d\\u0438\"}'),
(6,	'{\"en\":\"\\u0412\\u0430\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0412\\u0430\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0412\\u0430\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0412\\u0430\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0412\\u0430\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0412\\u0430\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0438\\u043d\\u0438\"}'),
(7,	'{\"en\":\"\\u041a\\u043e\\u043b\\u0456\\u0441\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ru\":\"\\u041a\\u043e\\u043b\\u0456\\u0441\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ua\":\"\\u041a\\u043e\\u043b\\u0456\\u0441\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041a\\u043e\\u043b\\u0456\\u0441\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041a\\u043e\\u043b\\u0456\\u0441\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041a\\u043e\\u043b\\u0456\\u0441\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\"}'),
(8,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043d\\u0430\\u0441\\u043e\\u0441\\u0438, \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043d\\u0430\\u0441\\u043e\\u0441\\u0438, \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043d\\u0430\\u0441\\u043e\\u0441\\u0438, \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043d\\u0430\\u0441\\u043e\\u0441\\u0438, \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043d\\u0430\\u0441\\u043e\\u0441\\u0438, \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043d\\u0430\\u0441\\u043e\\u0441\\u0438, \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\"}'),
(9,	'{\"en\":\"\\u0414\\u043e\\u043c\\u043a\\u0440\\u0430\\u0442\\u0438\",\"ru\":\"\\u0414\\u043e\\u043c\\u043a\\u0440\\u0430\\u0442\\u0438\",\"ua\":\"\\u0414\\u043e\\u043c\\u043a\\u0440\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0414\\u043e\\u043c\\u043a\\u0440\\u0430\\u0442\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0414\\u043e\\u043c\\u043a\\u0440\\u0430\\u0442\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u0414\\u043e\\u043c\\u043a\\u0440\\u0430\\u0442\\u0438\"}'),
(10,	'{\"en\":\"\\u041a\\u043e\\u0432\\u043f\\u0430\\u043a\\u0438\",\"ru\":\"\\u041a\\u043e\\u0432\\u043f\\u0430\\u043a\\u0438\",\"ua\":\"\\u041a\\u043e\\u0432\\u043f\\u0430\\u043a\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041a\\u043e\\u0432\\u043f\\u0430\\u043a\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041a\\u043e\\u0432\\u043f\\u0430\\u043a\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041a\\u043e\\u0432\\u043f\\u0430\\u043a\\u0438\"}'),
(11,	'{\"en\":\"\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0442\\u0438\\u0441\\u043a\\u0443 \\u0432 \\u0448\\u0438\\u043d\\u0430\\u0445\",\"ru\":\"\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0442\\u0438\\u0441\\u043a\\u0443 \\u0432 \\u0448\\u0438\\u043d\\u0430\\u0445\",\"ua\":\"\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0442\\u0438\\u0441\\u043a\\u0443 \\u0432 \\u0448\\u0438\\u043d\\u0430\\u0445\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0442\\u0438\\u0441\\u043a\\u0443 \\u0432 \\u0448\\u0438\\u043d\\u0430\\u0445\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0442\\u0438\\u0441\\u043a\\u0443 \\u0432 \\u0448\\u0438\\u043d\\u0430\\u0445\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0442\\u0438\\u0441\\u043a\\u0443 \\u0432 \\u0448\\u0438\\u043d\\u0430\\u0445\"}'),
(12,	'{\"en\":\"\\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u043f\\u0440\\u043e\\u0442\\u0438\\u043a\\u043e\\u0432\\u0437\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u043f\\u0440\\u043e\\u0442\\u0438\\u043a\\u043e\\u0432\\u0437\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u043f\\u0440\\u043e\\u0442\\u0438\\u043a\\u043e\\u0432\\u0437\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u043f\\u0440\\u043e\\u0442\\u0438\\u043a\\u043e\\u0432\\u0437\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u043f\\u0440\\u043e\\u0442\\u0438\\u043a\\u043e\\u0432\\u0437\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0428\\u0438\\u043d\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 > \\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u043f\\u0440\\u043e\\u0442\\u0438\\u043a\\u043e\\u0432\\u0437\\u0430\\u043d\\u043d\\u044f\"}'),
(13,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430\"}'),
(14,	'{\"en\":\"\\u041c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430, \\u0430\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f\",\"ru\":\"\\u041c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430, \\u0430\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f\",\"ua\":\"\\u041c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430, \\u0430\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430 > \\u041c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430, \\u0430\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430 > \\u041c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430, \\u0430\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430 > \\u041c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430, \\u0430\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f\"}'),
