(29,	'{\"en\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0441\\u0430\\u043b\\u043e\\u043d\\u043e\\u043c \\u0430\\u0432\\u0442\\u043e\",\"ru\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0441\\u0430\\u043b\\u043e\\u043d\\u043e\\u043c \\u0430\\u0432\\u0442\\u043e\",\"ua\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0441\\u0430\\u043b\\u043e\\u043d\\u043e\\u043c \\u0430\\u0432\\u0442\\u043e\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0441\\u0430\\u043b\\u043e\\u043d\\u043e\\u043c \\u0430\\u0432\\u0442\\u043e\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0441\\u0430\\u043b\\u043e\\u043d\\u043e\\u043c \\u0430\\u0432\\u0442\\u043e\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0441\\u0430\\u043b\\u043e\\u043d\\u043e\\u043c \\u0430\\u0432\\u0442\\u043e\"}'),
(30,	'{\"en\":\"\\u041e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447 \\u0434\\u0438\\u0441\\u043a\\u0456\\u0432\",\"ru\":\"\\u041e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447 \\u0434\\u0438\\u0441\\u043a\\u0456\\u0432\",\"ua\":\"\\u041e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447 \\u0434\\u0438\\u0441\\u043a\\u0456\\u0432\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 > \\u041e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447 \\u0434\\u0438\\u0441\\u043a\\u0456\\u0432\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 > \\u041e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447 \\u0434\\u0438\\u0441\\u043a\\u0456\\u0432\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0445\\u0456\\u043c\\u0456\\u044f, \\u043c\\u0430\\u0441\\u0442\\u0438\\u043b\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 > \\u041e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447 \\u0434\\u0438\\u0441\\u043a\\u0456\\u0432\"}'),
(31,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430\"}'),
(32,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\"}'),
(33,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\\u0432\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\\u0432\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\\u0432\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\\u0432\"}'),
(34,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\"}'),
(35,	'{\"en\":\"\\u0410\\u043b\\u043a\\u043e\\u0442\\u0435\\u0441\\u0442\\u0435\\u0440\\u0438\",\"ru\":\"\\u0410\\u043b\\u043a\\u043e\\u0442\\u0435\\u0441\\u0442\\u0435\\u0440\\u0438\",\"ua\":\"\\u0410\\u043b\\u043a\\u043e\\u0442\\u0435\\u0441\\u0442\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043b\\u043a\\u043e\\u0442\\u0435\\u0441\\u0442\\u0435\\u0440\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043b\\u043a\\u043e\\u0442\\u0435\\u0441\\u0442\\u0435\\u0440\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043b\\u043a\\u043e\\u0442\\u0435\\u0441\\u0442\\u0435\\u0440\\u0438\"}'),
(36,	'{\"en\":\"\\u0410\\u043d\\u0442\\u0438\\u0440\\u0430\\u0434\\u0430\\u0440\\u0438 (\\u0440\\u0430\\u0434\\u0430\\u0440-\\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438)\",\"ru\":\"\\u0410\\u043d\\u0442\\u0438\\u0440\\u0430\\u0434\\u0430\\u0440\\u0438 (\\u0440\\u0430\\u0434\\u0430\\u0440-\\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438)\",\"ua\":\"\\u0410\\u043d\\u0442\\u0438\\u0440\\u0430\\u0434\\u0430\\u0440\\u0438 (\\u0440\\u0430\\u0434\\u0430\\u0440-\\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438)\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043d\\u0442\\u0438\\u0440\\u0430\\u0434\\u0430\\u0440\\u0438 (\\u0440\\u0430\\u0434\\u0430\\u0440-\\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438)\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043d\\u0442\\u0438\\u0440\\u0430\\u0434\\u0430\\u0440\\u0438 (\\u0440\\u0430\\u0434\\u0430\\u0440-\\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438)\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043d\\u0442\\u0438\\u0440\\u0430\\u0434\\u0430\\u0440\\u0438 (\\u0440\\u0430\\u0434\\u0430\\u0440-\\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438)\"}'),
(37,	'{\"en\":\"\\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0437\\u0430\\u0434\\u043d\\u044c\\u043e\\u0433\\u043e \\u0432\\u0438\\u0434\\u0443\",\"ru\":\"\\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0437\\u0430\\u0434\\u043d\\u044c\\u043e\\u0433\\u043e \\u0432\\u0438\\u0434\\u0443\",\"ua\":\"\\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0437\\u0430\\u0434\\u043d\\u044c\\u043e\\u0433\\u043e \\u0432\\u0438\\u0434\\u0443\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0437\\u0430\\u0434\\u043d\\u044c\\u043e\\u0433\\u043e \\u0432\\u0438\\u0434\\u0443\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0437\\u0430\\u0434\\u043d\\u044c\\u043e\\u0433\\u043e \\u0432\\u0438\\u0434\\u0443\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0437\\u0430\\u0434\\u043d\\u044c\\u043e\\u0433\\u043e \\u0432\\u0438\\u0434\\u0443\"}'),
(38,	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043a\\u0441\\u0435\\u043d\\u043e\\u043d\\u043e\\u0432\\u043e\\u0433\\u043e \\u0441\\u0432\\u0456\\u0442\\u043b\\u0430\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043a\\u0441\\u0435\\u043d\\u043e\\u043d\\u043e\\u0432\\u043e\\u0433\\u043e \\u0441\\u0432\\u0456\\u0442\\u043b\\u0430\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043a\\u0441\\u0435\\u043d\\u043e\\u043d\\u043e\\u0432\\u043e\\u0433\\u043e \\u0441\\u0432\\u0456\\u0442\\u043b\\u0430\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043a\\u0441\\u0435\\u043d\\u043e\\u043d\\u043e\\u0432\\u043e\\u0433\\u043e \\u0441\\u0432\\u0456\\u0442\\u043b\\u0430\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043a\\u0441\\u0435\\u043d\\u043e\\u043d\\u043e\\u0432\\u043e\\u0433\\u043e \\u0441\\u0432\\u0456\\u0442\\u043b\\u0430\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043a\\u0441\\u0435\\u043d\\u043e\\u043d\\u043e\\u0432\\u043e\\u0433\\u043e \\u0441\\u0432\\u0456\\u0442\\u043b\\u0430\"}'),
(39,	'{\"en\":\"\\u041f\\u0430\\u0440\\u043a\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ru\":\"\\u041f\\u0430\\u0440\\u043a\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ua\":\"\\u041f\\u0430\\u0440\\u043a\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0430\\u0440\\u043a\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0430\\u0440\\u043a\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0430\\u0440\\u043a\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\"}'),
(40,	'{\"en\":\"\\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432 \\u0441\\u0438\\u0434\\u0456\\u043d\\u044c\",\"ru\":\"\\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432 \\u0441\\u0438\\u0434\\u0456\\u043d\\u044c\",\"ua\":\"\\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432 \\u0441\\u0438\\u0434\\u0456\\u043d\\u044c\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432 \\u0441\\u0438\\u0434\\u0456\\u043d\\u044c\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432 \\u0441\\u0438\\u0434\\u0456\\u043d\\u044c\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432 \\u0441\\u0438\\u0434\\u0456\\u043d\\u044c\"}'),
(41,	'{\"en\":\"\\u041f\\u0435\\u0440\\u0435\\u0442\\u0432\\u043e\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438 (\\u0456\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438)\",\"ru\":\"\\u041f\\u0435\\u0440\\u0435\\u0442\\u0432\\u043e\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438 (\\u0456\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438)\",\"ua\":\"\\u041f\\u0435\\u0440\\u0435\\u0442\\u0432\\u043e\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438 (\\u0456\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438)\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0435\\u0442\\u0432\\u043e\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438 (\\u0456\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438)\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0435\\u0442\\u0432\\u043e\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438 (\\u0456\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438)\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0435\\u0442\\u0432\\u043e\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438 (\\u0456\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438)\"}'),
(42,	'{\"en\":\"\\u041f\\u0443\\u0441\\u043a\\u043e-\\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457\",\"ru\":\"\\u041f\\u0443\\u0441\\u043a\\u043e-\\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457\",\"ua\":\"\\u041f\\u0443\\u0441\\u043a\\u043e-\\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0443\\u0441\\u043a\\u043e-\\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0443\\u0441\\u043a\\u043e-\\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0443\\u0441\\u043a\\u043e-\\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457\"}'),
(43,	'{\"en\":\"\\u0421\\u0432\\u0456\\u0447\\u043a\\u0438 \\u0437\\u0430\\u043f\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0421\\u0432\\u0456\\u0447\\u043a\\u0438 \\u0437\\u0430\\u043f\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0421\\u0432\\u0456\\u0447\\u043a\\u0438 \\u0437\\u0430\\u043f\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0432\\u0456\\u0447\\u043a\\u0438 \\u0437\\u0430\\u043f\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0432\\u0456\\u0447\\u043a\\u0438 \\u0437\\u0430\\u043f\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0432\\u0456\\u0447\\u043a\\u0438 \\u0437\\u0430\\u043f\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(44,	'{\"en\":\"\\u0424\\u0430\\u0440\\u0438\",\"ru\":\"\\u0424\\u0430\\u0440\\u0438\",\"ua\":\"\\u0424\\u0430\\u0440\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0424\\u0430\\u0440\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0424\\u0430\\u0440\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0424\\u0430\\u0440\\u0438\"}'),
(45,	'{\"en\":\"\\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e\",\"ru\":\"\\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e\",\"ua\":\"\\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e\"}'),
(46,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0457\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0457\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0457\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0457\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0457\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0457\"}'),
(47,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\"}'),
(48,	'{\"en\":\"\\u0426\\u0435\\u043d\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0437\\u0430\\u043c\\u043a\\u0438\",\"ru\":\"\\u0426\\u0435\\u043d\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0437\\u0430\\u043c\\u043a\\u0438\",\"ua\":\"\\u0426\\u0435\\u043d\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0437\\u0430\\u043c\\u043a\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e > \\u0426\\u0435\\u043d\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0437\\u0430\\u043c\\u043a\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e > \\u0426\\u0435\\u043d\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0437\\u0430\\u043c\\u043a\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 \\u0430\\u0432\\u0442\\u043e > \\u0426\\u0435\\u043d\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0437\\u0430\\u043c\\u043a\\u0438\"}'),
(49,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u0437\\u0432\\u0443\\u043a, \\u0432\\u0456\\u0434\\u0435\\u043e, \\u043d\\u0430\\u0432\\u0456\\u0433\\u0430\\u0446\\u0456\\u044f\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u0437\\u0432\\u0443\\u043a, \\u0432\\u0456\\u0434\\u0435\\u043e, \\u043d\\u0430\\u0432\\u0456\\u0433\\u0430\\u0446\\u0456\\u044f\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u0437\\u0432\\u0443\\u043a, \\u0432\\u0456\\u0434\\u0435\\u043e, \\u043d\\u0430\\u0432\\u0456\\u0433\\u0430\\u0446\\u0456\\u044f\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0437\\u0432\\u0443\\u043a, \\u0432\\u0456\\u0434\\u0435\\u043e, \\u043d\\u0430\\u0432\\u0456\\u0433\\u0430\\u0446\\u0456\\u044f\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0437\\u0432\\u0443\\u043a, \\u0432\\u0456\\u0434\\u0435\\u043e, \\u043d\\u0430\\u0432\\u0456\\u0433\\u0430\\u0446\\u0456\\u044f\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0410\\u0432\\u0442\\u043e\\u0437\\u0432\\u0443\\u043a, \\u0432\\u0456\\u0434\\u0435\\u043e, \\u043d\\u0430\\u0432\\u0456\\u0433\\u0430\\u0446\\u0456\\u044f\"}'),
