(64,	'{\"en\":\"\\u0427\\u043e\\u0445\\u043b\\u0438, \\u043d\\u0430\\u043a\\u0438\\u0434\\u043a\\u0438 \\u043d\\u0430 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\",\"ru\":\"\\u0427\\u043e\\u0445\\u043b\\u0438, \\u043d\\u0430\\u043a\\u0438\\u0434\\u043a\\u0438 \\u043d\\u0430 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\",\"ua\":\"\\u0427\\u043e\\u0445\\u043b\\u0438, \\u043d\\u0430\\u043a\\u0438\\u0434\\u043a\\u0438 \\u043d\\u0430 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0427\\u043e\\u0445\\u043b\\u0438, \\u043d\\u0430\\u043a\\u0438\\u0434\\u043a\\u0438 \\u043d\\u0430 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0427\\u043e\\u0445\\u043b\\u0438, \\u043d\\u0430\\u043a\\u0438\\u0434\\u043a\\u0438 \\u043d\\u0430 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0427\\u043e\\u0445\\u043b\\u0438, \\u043d\\u0430\\u043a\\u0438\\u0434\\u043a\\u0438 \\u043d\\u0430 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\"}'),
(65,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0410\\u0432\\u0442\\u043e\\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0410\\u0432\\u0442\\u043e\\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0410\\u0432\\u0442\\u043e\\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\"}'),
(66,	'{\"en\":\"\\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0437\\u043e\\u0432\\u0430 \\u0430\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044f\",\"ru\":\"\\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0437\\u043e\\u0432\\u0430 \\u0430\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044f\",\"ua\":\"\\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0437\\u043e\\u0432\\u0430 \\u0430\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044f\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0437\\u043e\\u0432\\u0430 \\u0430\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044f\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0437\\u043e\\u0432\\u0430 \\u0430\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044f\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0437\\u043e\\u0432\\u0430 \\u0430\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044f\"}'),
(67,	'{\"en\":\"\\u0412\\u0456\\u0442\\u0440\\u043e\\u0432\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0456\\u0442\\u0440\\u043e\\u0432\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0456\\u0442\\u0440\\u043e\\u0432\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0412\\u0456\\u0442\\u0440\\u043e\\u0432\\u0438\\u043a\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0412\\u0456\\u0442\\u0440\\u043e\\u0432\\u0438\\u043a\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0412\\u0456\\u0442\\u0440\\u043e\\u0432\\u0438\\u043a\\u0438\"}'),
(68,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0441\\u0430\\u043b\\u043e\\u043d\\u0443\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0441\\u0430\\u043b\\u043e\\u043d\\u0443\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0441\\u0430\\u043b\\u043e\\u043d\\u0443\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0441\\u0430\\u043b\\u043e\\u043d\\u0443\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0441\\u0430\\u043b\\u043e\\u043d\\u0443\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0441\\u0430\\u043b\\u043e\\u043d\\u0443\"}'),
(69,	'{\"en\":\"\\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443\",\"ru\":\"\\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443\",\"ua\":\"\\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443\"}'),
(70,	'{\"en\":\"\\u0411\\u0430\\u0433\\u0430\\u0436\\u043d\\u0456 \\u0431\\u043e\\u043a\\u0441\\u0438\",\"ru\":\"\\u0411\\u0430\\u0433\\u0430\\u0436\\u043d\\u0456 \\u0431\\u043e\\u043a\\u0441\\u0438\",\"ua\":\"\\u0411\\u0430\\u0433\\u0430\\u0436\\u043d\\u0456 \\u0431\\u043e\\u043a\\u0441\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443 > \\u0411\\u0430\\u0433\\u0430\\u0436\\u043d\\u0456 \\u0431\\u043e\\u043a\\u0441\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443 > \\u0411\\u0430\\u0433\\u0430\\u0436\\u043d\\u0456 \\u0431\\u043e\\u043a\\u0441\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443 > \\u0411\\u0430\\u0433\\u0430\\u0436\\u043d\\u0456 \\u0431\\u043e\\u043a\\u0441\\u0438\"}'),
(71,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0456\\u0432\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0456\\u0432\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0456\\u0432\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443 > \\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0456\\u0432\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443 > \\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0456\\u0432\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443 > \\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0456\\u0432\"}'),
(72,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043b\\u0438\\u0436 \\u0456 \\u0441\\u043d\\u043e\\u0443\\u0431\\u043e\\u0440\\u0434\\u0456\\u0432\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043b\\u0438\\u0436 \\u0456 \\u0441\\u043d\\u043e\\u0443\\u0431\\u043e\\u0440\\u0434\\u0456\\u0432\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043b\\u0438\\u0436 \\u0456 \\u0441\\u043d\\u043e\\u0443\\u0431\\u043e\\u0440\\u0434\\u0456\\u0432\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443 > \\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043b\\u0438\\u0436 \\u0456 \\u0441\\u043d\\u043e\\u0443\\u0431\\u043e\\u0440\\u0434\\u0456\\u0432\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443 > \\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043b\\u0438\\u0436 \\u0456 \\u0441\\u043d\\u043e\\u0443\\u0431\\u043e\\u0440\\u0434\\u0456\\u0432\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0435\\u0440\\u0435\\u0432\\u0435\\u0437\\u0435\\u043d\\u043d\\u044f \\u0431\\u0430\\u0433\\u0430\\u0436\\u0443 > \\u0410\\u0432\\u0442\\u043e \\u043a\\u0440\\u0456\\u043f\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043b\\u0438\\u0436 \\u0456 \\u0441\\u043d\\u043e\\u0443\\u0431\\u043e\\u0440\\u0434\\u0456\\u0432\"}'),
(73,	'{\"en\":\"\\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f \\u0430\\u0432\\u0442\\u043e\",\"ru\":\"\\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f \\u0430\\u0432\\u0442\\u043e\",\"ua\":\"\\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f \\u0430\\u0432\\u0442\\u043e\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f \\u0430\\u0432\\u0442\\u043e\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f \\u0430\\u0432\\u0442\\u043e\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f \\u0430\\u0432\\u0442\\u043e\"}'),
(74,	'{\"en\":\"\\u0428\\u043a\\u0440\\u0435\\u0431\\u043a\\u0438 \\u0442\\u0430 \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0430\\u0432\\u0442\\u043e\",\"ru\":\"\\u0428\\u043a\\u0440\\u0435\\u0431\\u043a\\u0438 \\u0442\\u0430 \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0430\\u0432\\u0442\\u043e\",\"ua\":\"\\u0428\\u043a\\u0440\\u0435\\u0431\\u043a\\u0438 \\u0442\\u0430 \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0430\\u0432\\u0442\\u043e\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f \\u0430\\u0432\\u0442\\u043e > \\u0428\\u043a\\u0440\\u0435\\u0431\\u043a\\u0438 \\u0442\\u0430 \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0430\\u0432\\u0442\\u043e\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f \\u0430\\u0432\\u0442\\u043e > \\u0428\\u043a\\u0440\\u0435\\u0431\\u043a\\u0438 \\u0442\\u0430 \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0430\\u0432\\u0442\\u043e\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0421\\u0430\\u043b\\u043e\\u043d > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f \\u0430\\u0432\\u0442\\u043e > \\u0428\\u043a\\u0440\\u0435\\u0431\\u043a\\u0438 \\u0442\\u0430 \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0430\\u0432\\u0442\\u043e\"}'),
(75,	'{\"en\":\"\\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438\",\"ru\":\"\\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438\",\"ua\":\"\\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438\"}'),
(76,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\"}'),
