(78,	'{\"en\":\"\\u041c\\u043e\\u0442\\u043e\\u0430\\u043a\\u0441\\u0435\\u0441\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ru\":\"\\u041c\\u043e\\u0442\\u043e\\u0430\\u043a\\u0441\\u0435\\u0441\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ua\":\"\\u041c\\u043e\\u0442\\u043e\\u0430\\u043a\\u0441\\u0435\\u0441\\u0441\\u0443\\u0430\\u0440\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0430\\u043a\\u0441\\u0435\\u0441\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0430\\u043a\\u0441\\u0435\\u0441\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0430\\u043a\\u0441\\u0435\\u0441\\u0441\\u0443\\u0430\\u0440\\u0438\"}'),
(79,	'{\"en\":\"\\u041c\\u043e\\u0442\\u043e\\u0435\\u043a\\u0456\\u043f\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430\",\"ru\":\"\\u041c\\u043e\\u0442\\u043e\\u0435\\u043a\\u0456\\u043f\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430\",\"ua\":\"\\u041c\\u043e\\u0442\\u043e\\u0435\\u043a\\u0456\\u043f\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0435\\u043a\\u0456\\u043f\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0435\\u043a\\u0456\\u043f\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0435\\u043a\\u0456\\u043f\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430\"}'),
(80,	'{\"en\":\"\\u041c\\u043e\\u0442\\u043e\\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\",\"ru\":\"\\u041c\\u043e\\u0442\\u043e\\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\",\"ua\":\"\\u041c\\u043e\\u0442\\u043e\\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u041c\\u043e\\u0442\\u043e\\u0446\\u0438\\u043a\\u043b\\u0438, \\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438 > \\u041c\\u043e\\u0442\\u043e\\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\"}'),
(81,	'{\"en\":\"\\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430\",\"ru\":\"\\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430\",\"ua\":\"\\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430\"}'),
(82,	'{\"en\":\"\\u0414\\u0432\\u0456\\u0440\\u043d\\u0438\\u043a\\u0438 (\\u0441\\u043a\\u043b\\u043e\\u043e\\u0447\\u0438\\u0441\\u043d\\u0438\\u043a\\u0438)\",\"ru\":\"\\u0414\\u0432\\u0456\\u0440\\u043d\\u0438\\u043a\\u0438 (\\u0441\\u043a\\u043b\\u043e\\u043e\\u0447\\u0438\\u0441\\u043d\\u0438\\u043a\\u0438)\",\"ua\":\"\\u0414\\u0432\\u0456\\u0440\\u043d\\u0438\\u043a\\u0438 (\\u0441\\u043a\\u043b\\u043e\\u043e\\u0447\\u0438\\u0441\\u043d\\u0438\\u043a\\u0438)\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430 > \\u0414\\u0432\\u0456\\u0440\\u043d\\u0438\\u043a\\u0438 (\\u0441\\u043a\\u043b\\u043e\\u043e\\u0447\\u0438\\u0441\\u043d\\u0438\\u043a\\u0438)\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430 > \\u0414\\u0432\\u0456\\u0440\\u043d\\u0438\\u043a\\u0438 (\\u0441\\u043a\\u043b\\u043e\\u043e\\u0447\\u0438\\u0441\\u043d\\u0438\\u043a\\u0438)\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430 > \\u0414\\u0432\\u0456\\u0440\\u043d\\u0438\\u043a\\u0438 (\\u0441\\u043a\\u043b\\u043e\\u043e\\u0447\\u0438\\u0441\\u043d\\u0438\\u043a\\u0438)\"}'),
(83,	'{\"en\":\"\\u041a\\u0430\\u043d\\u0456\\u0441\\u0442\\u0440\\u0438, \\u043b\\u0456\\u0439\\u043a\\u0438\",\"ru\":\"\\u041a\\u0430\\u043d\\u0456\\u0441\\u0442\\u0440\\u0438, \\u043b\\u0456\\u0439\\u043a\\u0438\",\"ua\":\"\\u041a\\u0430\\u043d\\u0456\\u0441\\u0442\\u0440\\u0438, \\u043b\\u0456\\u0439\\u043a\\u0438\"}',	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430 > \\u041a\\u0430\\u043d\\u0456\\u0441\\u0442\\u0440\\u0438, \\u043b\\u0456\\u0439\\u043a\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430 > \\u041a\\u0430\\u043d\\u0456\\u0441\\u0442\\u0440\\u0438, \\u043b\\u0456\\u0439\\u043a\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e \\u0456 \\u041c\\u043e\\u0442\\u043e > \\u0422\\u0435\\u0445\\u0434\\u043e\\u043f\\u043e\\u043c\\u043e\\u0433\\u0430 > \\u041a\\u0430\\u043d\\u0456\\u0441\\u0442\\u0440\\u0438, \\u043b\\u0456\\u0439\\u043a\\u0438\"}'),
