(94,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0438\\u0442\\u044f\\u0436\\u043e\\u043a\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0438\\u0442\\u044f\\u0436\\u043e\\u043a\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0438\\u0442\\u044f\\u0436\\u043e\\u043a\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043b\\u0438\\u043a\\u0430 \\u043f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0438\\u0442\\u044f\\u0436\\u043e\\u043a\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043b\\u0438\\u043a\\u0430 \\u043f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0438\\u0442\\u044f\\u0436\\u043e\\u043a\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043b\\u0438\\u043a\\u0430 \\u043f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0438\\u0442\\u044f\\u0436\\u043e\\u043a\"}'),
(95,	'{\"en\":\"\\u041f\\u043e\\u0441\\u0443\\u0434\\u043e\\u043c\\u0438\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u041f\\u043e\\u0441\\u0443\\u0434\\u043e\\u043c\\u0438\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u041f\\u043e\\u0441\\u0443\\u0434\\u043e\\u043c\\u0438\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043b\\u0438\\u043a\\u0430 \\u043f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u043e\\u0441\\u0443\\u0434\\u043e\\u043c\\u0438\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043b\\u0438\\u043a\\u0430 \\u043f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u043e\\u0441\\u0443\\u0434\\u043e\\u043c\\u0438\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043b\\u0438\\u043a\\u0430 \\u043f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u043e\\u0441\\u0443\\u0434\\u043e\\u043c\\u0438\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}'),
(96,	'{\"en\":\"\\u0425\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438-\\u0432\\u0456\\u0442\\u0440\\u0438\\u043d\\u0438\",\"ru\":\"\\u0425\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438-\\u0432\\u0456\\u0442\\u0440\\u0438\\u043d\\u0438\",\"ua\":\"\\u0425\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438-\\u0432\\u0456\\u0442\\u0440\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043b\\u0438\\u043a\\u0430 \\u043f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0425\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438-\\u0432\\u0456\\u0442\\u0440\\u0438\\u043d\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043b\\u0438\\u043a\\u0430 \\u043f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0425\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438-\\u0432\\u0456\\u0442\\u0440\\u0438\\u043d\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043b\\u0438\\u043a\\u0430 \\u043f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0425\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438-\\u0432\\u0456\\u0442\\u0440\\u0438\\u043d\\u0438\"}'),
(97,	'{\"en\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456\",\"ru\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456\",\"ua\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456\"}'),
(98,	'{\"en\":\"\\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(99,	'{\"en\":\"\\u0411\\u0430\\u0440\\u0431\\u0435\\u043a\\u044e, \\u0433\\u0440\\u0438\\u043b\\u0456\",\"ru\":\"\\u0411\\u0430\\u0440\\u0431\\u0435\\u043a\\u044e, \\u0433\\u0440\\u0438\\u043b\\u0456\",\"ua\":\"\\u0411\\u0430\\u0440\\u0431\\u0435\\u043a\\u044e, \\u0433\\u0440\\u0438\\u043b\\u0456\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0430\\u0440\\u0431\\u0435\\u043a\\u044e, \\u0433\\u0440\\u0438\\u043b\\u0456\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0430\\u0440\\u0431\\u0435\\u043a\\u044e, \\u0433\\u0440\\u0438\\u043b\\u0456\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0430\\u0440\\u0431\\u0435\\u043a\\u044e, \\u0433\\u0440\\u0438\\u043b\\u0456\"}'),
(100,	'{\"en\":\"\\u0419\\u043e\\u0433\\u0443\\u0440\\u0442\\u043d\\u0438\\u0446\\u0456, \\u043c\\u043e\\u0440\\u043e\\u0437\\u0438\\u0432\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u0419\\u043e\\u0433\\u0443\\u0440\\u0442\\u043d\\u0438\\u0446\\u0456, \\u043c\\u043e\\u0440\\u043e\\u0437\\u0438\\u0432\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u0419\\u043e\\u0433\\u0443\\u0440\\u0442\\u043d\\u0438\\u0446\\u0456, \\u043c\\u043e\\u0440\\u043e\\u0437\\u0438\\u0432\\u043d\\u0438\\u0446\\u0456\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0419\\u043e\\u0433\\u0443\\u0440\\u0442\\u043d\\u0438\\u0446\\u0456, \\u043c\\u043e\\u0440\\u043e\\u0437\\u0438\\u0432\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0419\\u043e\\u0433\\u0443\\u0440\\u0442\\u043d\\u0438\\u0446\\u0456, \\u043c\\u043e\\u0440\\u043e\\u0437\\u0438\\u0432\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0419\\u043e\\u0433\\u0443\\u0440\\u0442\\u043d\\u0438\\u0446\\u0456, \\u043c\\u043e\\u0440\\u043e\\u0437\\u0438\\u0432\\u043d\\u0438\\u0446\\u0456\"}'),
(101,	'{\"en\":\"\\u041c\\u0456\\u043a\\u0440\\u043e\\u0445\\u0432\\u0438\\u043b\\u044c\\u043e\\u0432\\u0456 \\u043f\\u0435\\u0447\\u0456\",\"ru\":\"\\u041c\\u0456\\u043a\\u0440\\u043e\\u0445\\u0432\\u0438\\u043b\\u044c\\u043e\\u0432\\u0456 \\u043f\\u0435\\u0447\\u0456\",\"ua\":\"\\u041c\\u0456\\u043a\\u0440\\u043e\\u0445\\u0432\\u0438\\u043b\\u044c\\u043e\\u0432\\u0456 \\u043f\\u0435\\u0447\\u0456\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041c\\u0456\\u043a\\u0440\\u043e\\u0445\\u0432\\u0438\\u043b\\u044c\\u043e\\u0432\\u0456 \\u043f\\u0435\\u0447\\u0456\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041c\\u0456\\u043a\\u0440\\u043e\\u0445\\u0432\\u0438\\u043b\\u044c\\u043e\\u0432\\u0456 \\u043f\\u0435\\u0447\\u0456\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041c\\u0456\\u043a\\u0440\\u043e\\u0445\\u0432\\u0438\\u043b\\u044c\\u043e\\u0432\\u0456 \\u043f\\u0435\\u0447\\u0456\"}'),
(102,	'{\"en\":\"\\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ru\":\"\\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ua\":\"\\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0440\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0440\\u043a\\u0438\"}'),
(103,	'{\"en\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043b\\u0438\\u0442\\u0438 \\u0456 \\u0434\\u0443\\u0445\\u043e\\u0432\\u043a\\u0438\",\"ru\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043b\\u0438\\u0442\\u0438 \\u0456 \\u0434\\u0443\\u0445\\u043e\\u0432\\u043a\\u0438\",\"ua\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043b\\u0438\\u0442\\u0438 \\u0456 \\u0434\\u0443\\u0445\\u043e\\u0432\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043b\\u0438\\u0442\\u0438 \\u0456 \\u0434\\u0443\\u0445\\u043e\\u0432\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043b\\u0438\\u0442\\u0438 \\u0456 \\u0434\\u0443\\u0445\\u043e\\u0432\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043b\\u0438\\u0442\\u0438 \\u0456 \\u0434\\u0443\\u0445\\u043e\\u0432\\u043a\\u0438\"}'),
(104,	'{\"en\":\"\\u041f\\u0430\\u0440\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ru\":\"\\u041f\\u0430\\u0440\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ua\":\"\\u041f\\u0430\\u0440\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0430\\u0440\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0430\\u0440\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0430\\u0440\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\"}'),
(105,	'{\"en\":\"\\u0421\\u0443\\u0448\\u0430\\u0440\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0444\\u0440\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ru\":\"\\u0421\\u0443\\u0448\\u0430\\u0440\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0444\\u0440\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ua\":\"\\u0421\\u0443\\u0448\\u0430\\u0440\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0444\\u0440\\u0443\\u043a\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0421\\u0443\\u0448\\u0430\\u0440\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0444\\u0440\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0421\\u0443\\u0448\\u0430\\u0440\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0444\\u0440\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0421\\u0443\\u0448\\u0430\\u0440\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0444\\u0440\\u0443\\u043a\\u0442\\u0456\\u0432\"}'),
(106,	'{\"en\":\"\\u0422\\u043e\\u0441\\u0442\\u0435\\u0440\\u0438, \\u0431\\u0443\\u0442\\u0435\\u0440\\u0431\\u0440\\u043e\\u0434\\u043d\\u0438\\u0446\\u0456, \\u0432\\u0430\\u0444\\u0435\\u043b\\u044c\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u0422\\u043e\\u0441\\u0442\\u0435\\u0440\\u0438, \\u0431\\u0443\\u0442\\u0435\\u0440\\u0431\\u0440\\u043e\\u0434\\u043d\\u0438\\u0446\\u0456, \\u0432\\u0430\\u0444\\u0435\\u043b\\u044c\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u0422\\u043e\\u0441\\u0442\\u0435\\u0440\\u0438, \\u0431\\u0443\\u0442\\u0435\\u0440\\u0431\\u0440\\u043e\\u0434\\u043d\\u0438\\u0446\\u0456, \\u0432\\u0430\\u0444\\u0435\\u043b\\u044c\\u043d\\u0438\\u0446\\u0456\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0422\\u043e\\u0441\\u0442\\u0435\\u0440\\u0438, \\u0431\\u0443\\u0442\\u0435\\u0440\\u0431\\u0440\\u043e\\u0434\\u043d\\u0438\\u0446\\u0456, \\u0432\\u0430\\u0444\\u0435\\u043b\\u044c\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0422\\u043e\\u0441\\u0442\\u0435\\u0440\\u0438, \\u0431\\u0443\\u0442\\u0435\\u0440\\u0431\\u0440\\u043e\\u0434\\u043d\\u0438\\u0446\\u0456, \\u0432\\u0430\\u0444\\u0435\\u043b\\u044c\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0422\\u043e\\u0441\\u0442\\u0435\\u0440\\u0438, \\u0431\\u0443\\u0442\\u0435\\u0440\\u0431\\u0440\\u043e\\u0434\\u043d\\u0438\\u0446\\u0456, \\u0432\\u0430\\u0444\\u0435\\u043b\\u044c\\u043d\\u0438\\u0446\\u0456\"}'),
(107,	'{\"en\":\"\\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043f\\u0435\\u0447\\u0456, \\u0444\\u0440\\u0438\\u0442\\u044e\\u0440\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043f\\u0435\\u0447\\u0456, \\u0444\\u0440\\u0438\\u0442\\u044e\\u0440\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043f\\u0435\\u0447\\u0456, \\u0444\\u0440\\u0438\\u0442\\u044e\\u0440\\u043d\\u0438\\u0446\\u0456\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043f\\u0435\\u0447\\u0456, \\u0444\\u0440\\u0438\\u0442\\u044e\\u0440\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043f\\u0435\\u0447\\u0456, \\u0444\\u0440\\u0438\\u0442\\u044e\\u0440\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043f\\u0435\\u0447\\u0456, \\u0444\\u0440\\u0438\\u0442\\u044e\\u0440\\u043d\\u0438\\u0446\\u0456\"}'),
(108,	'{\"en\":\"\\u0425\\u043b\\u0456\\u0431\\u043e\\u043f\\u0456\\u0447\\u043a\\u0438\",\"ru\":\"\\u0425\\u043b\\u0456\\u0431\\u043e\\u043f\\u0456\\u0447\\u043a\\u0438\",\"ua\":\"\\u0425\\u043b\\u0456\\u0431\\u043e\\u043f\\u0456\\u0447\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0425\\u043b\\u0456\\u0431\\u043e\\u043f\\u0456\\u0447\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0425\\u043b\\u0456\\u0431\\u043e\\u043f\\u0456\\u0447\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0425\\u043b\\u0456\\u0431\\u043e\\u043f\\u0456\\u0447\\u043a\\u0438\"}'),
(109,	'{\"en\":\"\\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(110,	'{\"en\":\"\\u0411\\u043b\\u0435\\u043d\\u0434\\u0435\\u0440\\u0438, \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0438, \\u043c\\u0456\\u043a\\u0441\\u0435\\u0440\\u0438\",\"ru\":\"\\u0411\\u043b\\u0435\\u043d\\u0434\\u0435\\u0440\\u0438, \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0438, \\u043c\\u0456\\u043a\\u0441\\u0435\\u0440\\u0438\",\"ua\":\"\\u0411\\u043b\\u0435\\u043d\\u0434\\u0435\\u0440\\u0438, \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0438, \\u043c\\u0456\\u043a\\u0441\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0411\\u043b\\u0435\\u043d\\u0434\\u0435\\u0440\\u0438, \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0438, \\u043c\\u0456\\u043a\\u0441\\u0435\\u0440\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0411\\u043b\\u0435\\u043d\\u0434\\u0435\\u0440\\u0438, \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0438, \\u043c\\u0456\\u043a\\u0441\\u0435\\u0440\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0411\\u043b\\u0435\\u043d\\u0434\\u0435\\u0440\\u0438, \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0438, \\u043c\\u0456\\u043a\\u0441\\u0435\\u0440\\u0438\"}'),
(111,	'{\"en\":\"\\u041d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0438\\u0445 \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0456\\u0432\",\"ru\":\"\\u041d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0438\\u0445 \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0456\\u0432\",\"ua\":\"\\u041d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0438\\u0445 \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0456\\u0432\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0438\\u0445 \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0456\\u0432\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0438\\u0445 \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0456\\u0432\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0438\\u0445 \\u043a\\u043e\\u043c\\u0431\\u0430\\u0439\\u043d\\u0456\\u0432\"}'),
(112,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\'\\u044f\\u0441\\u043e\\u0440\\u0443\\u0431\\u043a\\u0438\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\'\\u044f\\u0441\\u043e\\u0440\\u0443\\u0431\\u043a\\u0438\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\'\\u044f\\u0441\\u043e\\u0440\\u0443\\u0431\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\'\\u044f\\u0441\\u043e\\u0440\\u0443\\u0431\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\'\\u044f\\u0441\\u043e\\u0440\\u0443\\u0431\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\'\\u044f\\u0441\\u043e\\u0440\\u0443\\u0431\\u043a\\u0438\"}'),
(113,	'{\"en\":\"\\u041d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\'\\u044f\\u0441\\u043e\\u0440\\u0443\\u0431\\u043e\\u043a\",\"ru\":\"\\u041d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\'\\u044f\\u0441\\u043e\\u0440\\u0443\\u0431\\u043e\\u043a\",\"ua\":\"\\u041d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\'\\u044f\\u0441\\u043e\\u0440\\u0443\\u0431\\u043e\\u043a\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\'\\u044f\\u0441\\u043e\\u0440\\u0443\\u0431\\u043e\\u043a\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043c\'\\u044f\\u0441\\u043e\\u0440\\u0443\\u0431\\u043e\\u043a\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u043