(114,	'{\"en\":\"\\u0421\\u043a\\u0438\\u0431\\u043e\\u0440\\u0456\\u0437\\u043a\\u0438\",\"ru\":\"\\u0421\\u043a\\u0438\\u0431\\u043e\\u0440\\u0456\\u0437\\u043a\\u0438\",\"ua\":\"\\u0421\\u043a\\u0438\\u0431\\u043e\\u0440\\u0456\\u0437\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0421\\u043a\\u0438\\u0431\\u043e\\u0440\\u0456\\u0437\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0421\\u043a\\u0438\\u0431\\u043e\\u0440\\u0456\\u0437\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u0435\\u043d\\u043d\\u044f, \\u0437\\u0431\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0421\\u043a\\u0438\\u0431\\u043e\\u0440\\u0456\\u0437\\u043a\\u0438\"}'),
