(119,	'{\"en\":\"\\u0421\\u0438\\u0444\\u043e\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0430\\u0437\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ru\":\"\\u0421\\u0438\\u0444\\u043e\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0430\\u0437\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ua\":\"\\u0421\\u0438\\u0444\\u043e\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0430\\u0437\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0432\\u043e\\u0434\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0421\\u0438\\u0444\\u043e\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0430\\u0437\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0421\\u0438\\u0444\\u043e\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0430\\u0437\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0421\\u0438\\u0444\\u043e\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0430\\u0437\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0432\\u043e\\u0434\\u0438\"}'),
(120,	'{\"en\":\"\\u0421\\u043e\\u043a\\u043e\\u0432\\u0438\\u0442\\u0438\\u0441\\u043a\\u0430\\u0447\\u0456\",\"ru\":\"\\u0421\\u043e\\u043a\\u043e\\u0432\\u0438\\u0442\\u0438\\u0441\\u043a\\u0430\\u0447\\u0456\",\"ua\":\"\\u0421\\u043e\\u043a\\u043e\\u0432\\u0438\\u0442\\u0438\\u0441\\u043a\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0421\\u043e\\u043a\\u043e\\u0432\\u0438\\u0442\\u0438\\u0441\\u043a\\u0430\\u0447\\u0456\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0421\\u043e\\u043a\\u043e\\u0432\\u0438\\u0442\\u0438\\u0441\\u043a\\u0430\\u0447\\u0456\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0421\\u043e\\u043a\\u043e\\u0432\\u0438\\u0442\\u0438\\u0441\\u043a\\u0430\\u0447\\u0456\"}'),
(121,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\"}'),
(122,	'{\"en\":\"\\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ru\":\"\\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ua\":\"\\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u0434\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u0434\\u0438\"}'),
(123,	'{\"en\":\"\\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043e \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0456\\u0432-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0456\\u0432\",\"ru\":\"\\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043e \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0456\\u0432-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0456\\u0432\",\"ua\":\"\\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043e \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0456\\u0432-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0456\\u0432\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043e \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0456\\u0432-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0456\\u0432\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043e \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0456\\u0432-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0456\\u0432\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043e \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0456\\u0432-\\u0433\\u043b\\u0435\\u0447\\u0438\\u043a\\u0456\\u0432\"}'),
(124,	'{\"en\":\"\\u041f\\u0438\\u0432\\u043e\\u0432\\u0430\\u0440\\u043d\\u0456, \\u0434\\u0438\\u0441\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041f\\u0438\\u0432\\u043e\\u0432\\u0430\\u0440\\u043d\\u0456, \\u0434\\u0438\\u0441\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041f\\u0438\\u0432\\u043e\\u0432\\u0430\\u0440\\u043d\\u0456, \\u0434\\u0438\\u0441\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u041f\\u0438\\u0432\\u043e\\u0432\\u0430\\u0440\\u043d\\u0456, \\u0434\\u0438\\u0441\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u041f\\u0438\\u0432\\u043e\\u0432\\u0430\\u0440\\u043d\\u0456, \\u0434\\u0438\\u0441\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u041d\\u0430\\u043f\\u043e\\u0457 > \\u041f\\u0438\\u0432\\u043e\\u0432\\u0430\\u0440\\u043d\\u0456, \\u0434\\u0438\\u0441\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\"}'),
(125,	'{\"en\":\"\\u0406\\u043d\\u0448\\u0435\",\"ru\":\"\\u0406\\u043d\\u0448\\u0435\",\"ua\":\"\\u0406\\u043d\\u0448\\u0435\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435\"}'),
(126,	'{\"en\":\"\\u0412\\u0430\\u0433\\u0438 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\",\"ru\":\"\\u0412\\u0430\\u0433\\u0438 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\",\"ua\":\"\\u0412\\u0430\\u0433\\u0438 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u0412\\u0430\\u0433\\u0438 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u0412\\u0430\\u0433\\u0438 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u0412\\u0430\\u0433\\u0438 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\"}'),
(127,	'{\"en\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ru\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ua\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 (\\u0440\\u0456\\u0437\\u043d\\u0435)\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 (\\u0440\\u0456\\u0437\\u043d\\u0435)\"}'),
(128,	'{\"en\":\"\\u041f\\u043e\\u0440\\u0442\\u0430\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0445\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0440\\u0442\\u0430\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0445\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0440\\u0442\\u0430\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0445\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u041f\\u043e\\u0440\\u0442\\u0430\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0445\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u041f\\u043e\\u0440\\u0442\\u0430\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0445\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u041f\\u043e\\u0440\\u0442\\u0430\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0445\\u043e\\u043b\\u043e\\u0434\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\"}'),
(129,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043d\\u0456 > \\u0406\\u043d\\u0448\\u0435 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\"}'),
(130,	'{\"en\":\"\\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ru\":\"\\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ua\":\"\\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\"}'),
(131,	'{\"en\":\"\\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ru\":\"\\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ua\":\"\\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\"}'),
(132,	'{\"en\":\"\\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0441\\u0443\\u0434\\u0443\",\"ru\":\"\\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0441\\u0443\\u0434\\u0443\",\"ua\":\"\\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0441\\u0443\\u0434\\u0443\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0441\\u0443\\u0434\\u0443\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0441\\u0443\\u0434\\u0443\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0431\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0441\\u0443\\u0434\\u0443\"}'),
(133,	'{\"en\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ru\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ua\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\"}'),
(134,	'{\"en\":\"\\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f\"}'),
(135,	'{\"en\":\"\\u041f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ru\":\"\\u041f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ua\":\"\\u041f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\"}'),
(136,	'{\"en\":\"\\u0420\\u043e\\u0431\\u043e\\u0442\\u0438-\\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ru\":\"\\u0420\\u043e\\u0431\\u043e\\u0442\\u0438-\\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ua\":\"\\u0420\\u043e\\u0431\\u043e\\u0442\\u0438-\\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u0420\\u043e\\u0431\\u043e\\u0442\\u0438-\\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u0420\\u043e\\u0431\\u043e\\u0442\\u0438-\\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u0420\\u043e\\u0431\\u043e\\u0442\\u0438-\\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438\"}'),
(137,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0456\\u0432 \\u0456 \\u043f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0456\\u0432 \\u0456 \\u043f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0456\\u0432 \\u0456 \\u043f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0456\\u0432 \\u0456 \\u043f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0456\\u0432 \\u0456 \\u043f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0456\\u0432 \\u0456 \\u043f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432\"}'),
(138,	'{\"en\":\"\\u041f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0430\\u0440\\u043e\\u0432\\u0456 \\u0448\\u0432\\u0430\\u0431\\u0440\\u0438\",\"ru\":\"\\u041f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0430\\u0440\\u043e\\u0432\\u0456 \\u0448\\u0432\\u0430\\u0431\\u0440\\u0438\",\"ua\":\"\\u041f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0430\\u0440\\u043e\\u0432\\u0456 \\u0448\\u0432\\u0430\\u0431\\u0440\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0430\\u0440\\u043e\\u0432\\u0456 \\u0448\\u0432\\u0430\\u0431\\u0440\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0430\\u0440\\u043e\\u0432\\u0456 \\u0448\\u0432\\u0430\\u0431\\u0440\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0430\\u0440\\u043e\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0430\\u0440\\u043e\\u0432\\u0456 \\u0448\\u0432\\u0430\\u0431\\u0440\\u0438\"}'),
(139,	'{\"en\":\"\\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(140,	'{\"en\":\"\\u041f\\u0440\\u0430\\u0441\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043f\\u0430\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u041f\\u0440\\u0430\\u0441\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043f\\u0430\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u041f\\u0440\\u0430\\u0441\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043f\\u0430\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0430\\u0441\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043f\\u0430\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0430\\u0441\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043f\\u0430\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0430\\u0441\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043f\\u0430\\u0440\\u044e\\u0432\\u0430\\u0447\\u0456\"}'),
(141,	'{\"en\":\"\\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\",\"ru\":\"\\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\",\"ua\":\"\\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\"}'),
(142,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0430\\u0441\\u043e\\u043a \\u0456 \\u043f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0434\\u043e\\u0449\\u043e\\u043a\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0430\\u0441\\u043e\\u043a \\u0456 \\u043f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0434\\u043e\\u0449\\u043e\\u043a\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0430\\u0441\\u043e\\u043a \\u0456 \\u043f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0434\\u043e\\u0449\\u043e\\u043a\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0430\\u0441\\u043e\\u043a \\u0456 \\u043f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0434\\u043e\\u0449\\u043e\\u043a\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0430\\u0441\\u043e\\u043a \\u0456 \\u043f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0434\\u043e\\u0449\\u043e\\u043a\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0430\\u0441\\u043e\\u043a \\u0456 \\u043f\\u0440\\u0430\\u0441\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0434\\u043e\\u0449\\u043e\\u043a\"}'),
(143,	'{\"en\":\"\\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f\"}'),
(144,	'{\"en\":\"\\u0428\\u0432\\u0435\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0456 \\u043e\\u0432\\u0435\\u0440\\u043b\\u043e\\u043a\\u0438\",\"ru\":\"\\u0428\\u0432\\u0435\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0456 \\u043e\\u0432\\u0435\\u0440\\u043b\\u043e\\u043a\\u0438\",\"ua\":\"\\u0428\\u0432\\u0435\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0456 \\u043e\\u0432\\u0435\\u0440\\u043b\\u043e\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f > \\u0428\\u0432\\u0435\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0456 \\u043e\\u0432\\u0435\\u0440\\u043b\\u043e\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f > \\u0428\\u0432\\u0435\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0456 \\u043e\\u0432\\u0435\\u0440\\u043b\\u043e\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f > \\u0428\\u0432\\u0435\\u0439\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0456 \\u043e\\u0432\\u0435\\u0440\\u043b\\u043e\\u043a\\u0438\"}'),
(145,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u0432\\u0435\\u0439\\u043d\\u0438\\u0445 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043e\\u043a\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u0432\\u0435\\u0439\\u043d\\u0438\\u0445 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043e\\u043a\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u0432\\u0435\\u0439\\u043d\\u0438\\u0445 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043e\\u043a\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u0432\\u0435\\u0439\\u043d\\u0438\\u0445 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043e\\u043a\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u0432\\u0435\\u0439\\u043d\\u0438\\u0445 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043e\\u043a\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u0432\\u0435\\u0439\\u043d\\u0438\\u0445 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043e\\u043a\"}'),
(146,	'{\"en\":\"\\u0412\'\\u044f\\u0437\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0412\'\\u044f\\u0437\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0412\'\\u044f\\u0437\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f > \\u0412\'\\u044f\\u0437\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f > \\u0412\'\\u044f\\u0437\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0428\\u0438\\u0442\\u0442\\u044f, \\u0432\'\\u044f\\u0437\\u0430\\u043d\\u043d\\u044f > \\u0412\'\\u044f\\u0437\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}'),
(147,	'{\"en\":\"\\u0406\\u043d\\u0448\\u0435\",\"ru\":\"\\u0406\\u043d\\u0448\\u0435\",\"ua\":\"\\u0406\\u043d\\u0448\\u0435\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0448\\u0435\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0448\\u0435\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0448\\u0435\"}'),
(148,	'{\"en\":\"\\u0414\\u0440\\u0456\\u0431\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ru\":\"\\u0414\\u0440\\u0456\\u0431\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ua\":\"\\u0414\\u0440\\u0456\\u0431\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0448\\u0435 > \\u0414\\u0440\\u0456\\u0431\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0448\\u0435 > \\u0414\\u0440\\u0456\\u0431\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0448\\u0435 > \\u0414\\u0440\\u0456\\u0431\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\"}'),
(149,	'{\"en\":\"\\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ru\":\"\\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ua\":\"\\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\"}'),
(150,	'{\"en\":\"\\u041a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0438\",\"ru\":\"\\u041a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0438\",\"ua\":\"\\u041a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0438\"}'),
(151,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0456\\u0432\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0456\\u0432\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0456\\u0432\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0434\\u0438\\u0446\\u0456\\u043e\\u043d\\u0435\\u0440\\u0456\\u0432\"}'),
(152,	'{\"en\":\"\\u041e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u041e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u041e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\"}'),
(153,	'{\"en\":\"\\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\\u0432\",\"ru\":\"\\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\\u0432\",\"ua\":\"\\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\\u0432\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\\u0432\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\\u0432\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\\u0432\"}'),
(154,	'{\"en\":\"\\u0417\\u0432\\u043e\\u043b\\u043e\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\",\"ru\":\"\\u0417\\u0432\\u043e\\u043b\\u043e\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\",\"ua\":\"\\u0417\\u0432\\u043e\\u043b\\u043e\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0417\\u0432\\u043e\\u043b\\u043e\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0417\\u0432\\u043e\\u043b\\u043e\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0417\\u0432\\u043e\\u043b\\u043e\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\"}'),
(155,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0432\\u043e\\u043b\\u043e\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432 \\u0456 \\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0432\\u043e\\u043b\\u043e\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432 \\u0456 \\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0432\\u043e\\u043b\\u043e\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432 \\u0456 \\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0432\\u043e\\u043b\\u043e\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432 \\u0456 \\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0432\\u043e\\u043b\\u043e\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432 \\u0456 \\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\\u0432 \\u043f\\u043e\\u043