(156,	'{\"en\":\"\\u041c\\u0435\\u0442\\u0435\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457, \\u0442\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0433\\u0456\\u0433\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0431\\u0430\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ru\":\"\\u041c\\u0435\\u0442\\u0435\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457, \\u0442\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0433\\u0456\\u0433\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0431\\u0430\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ua\":\"\\u041c\\u0435\\u0442\\u0435\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457, \\u0442\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0433\\u0456\\u0433\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0431\\u0430\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041c\\u0435\\u0442\\u0435\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457, \\u0442\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0433\\u0456\\u0433\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0431\\u0430\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041c\\u0435\\u0442\\u0435\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457, \\u0442\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0433\\u0456\\u0433\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0431\\u0430\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041c\\u0435\\u0442\\u0435\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457, \\u0442\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0433\\u0456\\u0433\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438, \\u0431\\u0430\\u0440\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\"}'),
(157,	'{\"en\":\"\\u041e\\u0441\\u0443\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\",\"ru\":\"\\u041e\\u0441\\u0443\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\",\"ua\":\"\\u041e\\u0441\\u0443\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041e\\u0441\\u0443\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041e\\u0441\\u0443\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041e\\u0441\\u0443\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456 \\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u044f\"}'),
(158,	'{\"en\":\"\\u041f\\u0440\\u0438\\u043f\\u043b\\u0438\\u0432\\u043d\\u043e-\\u0432\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0438\",\"ru\":\"\\u041f\\u0440\\u0438\\u043f\\u043b\\u0438\\u0432\\u043d\\u043e-\\u0432\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0438\",\"ua\":\"\\u041f\\u0440\\u0438\\u043f\\u043b\\u0438\\u0432\\u043d\\u043e-\\u0432\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0440\\u0438\\u043f\\u043b\\u0438\\u0432\\u043d\\u043e-\\u0432\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0440\\u0438\\u043f\\u043b\\u0438\\u0432\\u043d\\u043e-\\u0432\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0440\\u0438\\u043f\\u043b\\u0438\\u0432\\u043d\\u043e-\\u0432\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0443\\u044