(159,	'{\"en\":\"\\u041a\\u0430\\u043c\\u0456\\u043d\\u0438\",\"ru\":\"\\u041a\\u0430\\u043c\\u0456\\u043d\\u0438\",\"ua\":\"\\u041a\\u0430\\u043c\\u0456\\u043d\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0430\\u043c\\u0456\\u043d\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0430\\u043c\\u0456\\u043d\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0430\\u043c\\u0456\\u043d\\u0438\"}'),
(160,	'{\"en\":\"\\u0413\\u0430\\u0437\\u043e\\u0432\\u0456 \\u0432\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0413\\u0430\\u0437\\u043e\\u0432\\u0456 \\u0432\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0413\\u0430\\u0437\\u043e\\u0432\\u0456 \\u0432\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0413\\u0430\\u0437\\u043e\\u0432\\u0456 \\u0432\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0413\\u0430\\u0437\\u043e\\u0432\\u0456 \\u0432\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0413\\u0430\\u0437\\u043e\\u0432\\u0456 \\u0432\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u043e\\u0431\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456\"}'),
(161,	'{\"en\":\"\\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0437\\u0430\\u0432\\u0456\\u0441\\u0438\",\"ru\":\"\\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0437\\u0430\\u0432\\u0456\\u0441\\u0438\",\"ua\":\"\\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0437\\u0430\\u0432\\u0456\\u0441\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0437\\u0430\\u0432\\u0456\\u0441\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0437\\u0430\\u0432\\u0456\\u0441\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0437\\u0430\\u0432\\u0456\\u0441\\u0438\"}'),
(162,	'{\"en\":\"\\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0433\\u0430\\u0440\\u043c\\u0430\\u0442\\u0438\",\"ru\":\"\\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0433\\u0430\\u0440\\u043c\\u0430\\u0442\\u0438\",\"ua\":\"\\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0433\\u0430\\u0440\\u043c\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0433\\u0430\\u0440\\u043c\\u0430\\u0442\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0433\\u0430\\u0440\\u043c\\u0430\\u0442\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0422\\u0435\\u043f\\u043b\\u043e\\u0432\\u0456 \\u0433\\u0430\\u0440\\u043c\\u0430\\u0442\\u0438\"}'),
(163,	'{\"en\":\"\\u0412\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0412\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0412\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u043b\\u0456\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0412\\u0435\\u043d\\u0442\\u0438\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438\"}'),
(164,	'{\"en\":\"\\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\",\"ru\":\"\\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\",\"ua\":\"\\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\"}'),
(165,	'{\"en\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ru\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ua\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\"}'),
(166,	'{\"en\":\"\\u0424\\u0435\\u043d\\u0438, \\u043f\\u043b\\u043e\\u0439\\u043a\\u0438, \\u0441\\u0442\\u0430\\u0439\\u043b\\u0435\\u0440\\u0438\",\"ru\":\"\\u0424\\u0435\\u043d\\u0438, \\u043f\\u043b\\u043e\\u0439\\u043a\\u0438, \\u0441\\u0442\\u0430\\u0439\\u043b\\u0435\\u0440\\u0438\",\"ua\":\"\\u0424\\u0435\\u043d\\u0438, \\u043f\\u043b\\u043e\\u0439\\u043a\\u0438, \\u0441\\u0442\\u0430\\u0439\\u043b\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0424\\u0435\\u043d\\u0438, \\u043f\\u043b\\u043e\\u0439\\u043a\\u0438, \\u0441\\u0442\\u0430\\u0439\\u043b\\u0435\\u0440\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0424\\u0435\\u043d\\u0438, \\u043f\\u043b\\u043e\\u0439\\u043a\\u0438, \\u0441\\u0442\\u0430\\u0439\\u043b\\u0435\\u0440\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0424\\u0435\\u043d\\u0438, \\u043f\\u043b\\u043e\\u0439\\u043a\\u0438, \\u0441\\u0442\\u0430\\u0439\\u043b\\u0435\\u0440\\u0438\"}'),
(167,	'{\"en\":\"\\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438 (\\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438)\",\"ru\":\"\\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438 (\\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438)\",\"ua\":\"\\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438 (\\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438)\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438 (\\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438)\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438 (\\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438)\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438 (\\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438)\"}'),
(168,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043c\\u0430\\u0448\\u0438\\u043d\\u043e\\u043a \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043c\\u0430\\u0448\\u0438\\u043d\\u043e\\u043a \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043c\\u0430\\u0448\\u0438\\u043d\\u043e\\u043a \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043c\\u0430\\u0448\\u0438\\u043d\\u043e\\u043a \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043c\\u0430\\u0448\\u0438\\u043d\\u043e\\u043a \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u04