(169,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0431\\u0440\\u0438\\u0442\\u0432\\u0438\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0431\\u0440\\u0438\\u0442\\u0432\\u0438\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0431\\u0440\\u0438\\u0442\\u0432\\u0438\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0431\\u0440\\u0438\\u0442\\u0432\\u0438\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0431\\u0440\\u0438\\u0442\\u0432\\u0438\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0431\\u0440\\u0438\\u0442\\u0432\\u0438\"}'),
(170,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0431\\u0440\\u0438\\u0442\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0431\\u0440\\u0438\\u0442\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0431\\u0440\\u0438\\u0442\\u0432\"}',	'{\"en\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0431\\u0440\\u0438\\u0442\\u0432\",\"ru\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0431\\u0440\\u0438\\u0442\\u0432\",\"ua\":\"\\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434 > \\u0422\\u0435\