(179,	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\"}'),
(180,	'{\"en\":\"\\u041c\\u0435\\u0431\\u043b\\u0456\",\"ru\":\"\\u041c\\u0435\\u0431\\u043b\\u0456\",\"ua\":\"\\u041c\\u0435\\u0431\\u043b\\u0456\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456\"}'),
(181,	'{\"en\":\"\\u0411\\u0430\\u0440\\u043d\\u0456 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\",\"ru\":\"\\u0411\\u0430\\u0440\\u043d\\u0456 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\",\"ua\":\"\\u0411\\u0430\\u0440\\u043d\\u0456 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0411\\u0430\\u0440\\u043d\\u0456 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0411\\u0430\\u0440\\u043d\\u0456 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0411\\u0430\\u0440\\u043d\\u0456 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\"}'),
(182,	'{\"en\":\"\\u0412\\u0456\\u0448\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0412\\u0456\\u0448\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0412\\u0456\\u0448\\u0430\\u043b\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0412\\u0456\\u0448\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0412\\u0456\\u0448\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0412\\u0456\\u0448\\u0430\\u043b\\u043a\\u0438\"}'),
