(184,	'{\"en\":\"\\u041c\\u0430\\u0441\\u0430\\u0436\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\",\"ru\":\"\\u041c\\u0430\\u0441\\u0430\\u0436\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\",\"ua\":\"\\u041c\\u0430\\u0441\\u0430\\u0436\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041c\\u0430\\u0441\\u0430\\u0436\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041c\\u0430\\u0441\\u0430\\u0436\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041c\\u0430\\u0441\\u0430\\u0436\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\"}'),
(185,	'{\"en\":\"\\u0414\\u0438\\u0432\\u0430\\u043d\\u0438\",\"ru\":\"\\u0414\\u0438\\u0432\\u0430\\u043d\\u0438\",\"ua\":\"\\u0414\\u0438\\u0432\\u0430\\u043d\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0432\\u0430\\u043d\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0432\\u0430\\u043d\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0432\\u0430\\u043d\\u0438\"}'),
(186,	'{\"en\":\"\\u0416\\u0443\\u0440\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0430 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438\",\"ru\":\"\\u0416\\u0443\\u0440\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0430 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438\",\"ua\":\"\\u0416\\u0443\\u0440\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0430 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0416\\u0443\\u0440\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0430 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0416\\u0443\\u0440\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0430 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0416\\u0443\\u0440\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0430 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438\"}'),
(187,	'{\"en\":\"\\u041a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u0442\\u0440\\u044e\\u043c\\u043e\",\"ru\":\"\\u041a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u0442\\u0440\\u044e\\u043c\\u043e\",\"ua\":\"\\u041a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u0442\\u0440\\u044e\\u043c\\u043e\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u0442\\u0440\\u044e\\u043c\\u043e\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u0442\\u0440\\u044e\\u043c\\u043e\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u0442\\u0440\\u044e\\u043c\\u043e\"}'),
(188,	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u043d\\u0456 \\u0442\\u0430 \\u043e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u043d\\u0456 \\u0442\\u0430 \\u043e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u043d\\u0456 \\u0442\\u0430 \\u043e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u043d\\u0456 \\u0442\\u0430 \\u043e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u043d\\u0456 \\u0442\\u0430 \\u043e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u043d\\u0456 \\u0442\\u0430 \\u043e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\"}'),
(189,	'{\"en\":\"\\u041a\\u0440\\u0456\\u0441\\u043b\\u0430, \\u043f\\u0443\\u0444\\u0438\\u043a\\u0438\",\"ru\":\"\\u041a\\u0440\\u0456\\u0441\\u043b\\u0430, \\u043f\\u0443\\u0444\\u0438\\u043a\\u0438\",\"ua\":\"\\u041a\\u0440\\u0456\\u0441\\u043b\\u0430, \\u043f\\u0443\\u0444\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u0440\\u0456\\u0441\\u043b\\u0430, \\u043f\\u0443\\u0444\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u0440\\u0456\\u0441\\u043b\\u0430, \\u043f\\u0443\\u0444\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u0440\\u0456\\u0441\\u043b\\u0430, \\u043f\\u0443\\u0444\\u0438\\u043a\\u0438\"}'),
(190,	'{\"en\":\"\\u041b\\u0456\\u0436\\u043a\\u0430\",\"ru\":\"\\u041b\\u0456\\u0436\\u043a\\u0430\",\"ua\":\"\\u041b\\u0456\\u0436\\u043a\\u0430\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041b\\u0456\\u0436\\u043a\\u0430\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041b\\u0456\\u0436\\u043a\\u0430\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041b\\u0456\\u0436\\u043a\\u0430\"}'),
