(192,	'{\"en\":\"\\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456 \\u043a\\u0443\\u0442\\u043e\\u0447\\u043a\\u0438\",\"ru\":\"\\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456 \\u043a\\u0443\\u0442\\u043e\\u0447\\u043a\\u0438\",\"ua\":\"\\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456 \\u043a\\u0443\\u0442\\u043e\\u0447\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456 \\u043a\\u0443\\u0442\\u043e\\u0447\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456 \\u043a\\u0443\\u0442\\u043e\\u0447\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456 \\u043a\\u0443\\u0442\\u043e\\u0447\\u043a\\u0438\"}'),
(193,	'{\"en\":\"\\u041e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\",\"ru\":\"\\u041e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\",\"ua\":\"\\u041e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041e\\u0444\\u0456\\u0441\\u043d\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430\"}'),
(194,	'{\"en\":\"\\u041f\\u043b\\u0435\\u0442\\u0435\\u043d\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ru\":\"\\u041f\\u043b\\u0435\\u0442\\u0435\\u043d\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ua\":\"\\u041f\\u043b\\u0435\\u0442\\u0435\\u043d\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041f\\u043b\\u0435\\u0442\\u0435\\u043d\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041f\\u043b\\u0435\\u0442\\u0435\\u043d\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u041f\\u043b\\u0435\\u0442\\u0435\\u043d\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\"}'),
(195,	'{\"en\":\"\\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ru\":\"\\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ua\":\"\\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456\"}'),
(196,	'{\"en\":\"\\u0421\\u0442\\u043e\\u043b\\u0438\",\"ru\":\"\\u0421\\u0442\\u043e\\u043b\\u0438\",\"ua\":\"\\u0421\\u0442\\u043e\\u043b\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u0442\\u043e\\u043b\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u0442\\u043e\\u043b\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u0442\\u043e\\u043b\\u0438\"}'),
(197,	'{\"en\":\"\\u0421\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456, \\u0442\\u0430\\u0431\\u0443\\u0440\\u0435\\u0442\\u0438\",\"ru\":\"\\u0421\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456, \\u0442\\u0430\\u0431\\u0443\\u0440\\u0435\\u0442\\u0438\",\"ua\":\"\\u0421\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456, \\u0442\\u0430\\u0431\\u0443\\u0440\\u0435\\u0442\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456, \\u0442\\u0430\\u0431\\u0443\\u0440\\u0435\\u0442\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456, \\u0442\\u0430\\u0431\\u0443\\u0440\\u0435\\u0442\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456, \\u0442\\u0430\\u0431\\u0443\\u0440\\u0435\\u0442\\u0438\"}'),
(198,	'{\"en\":\"\\u0428\\u0430\\u0444\\u0438, \\u0432\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456, \\u0441\\u0442\\u0456\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\",\"ru\":\"\\u0428\\u0430\\u0444\\u0438, \\u0432\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456, \\u0441\\u0442\\u0456\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\",\"ua\":\"\\u0428\\u0430\\u0444\\u0438, \\u0432\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456, \\u0441\\u0442\\u0456\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0428\\u0430\\u0444\\u0438, \\u0432\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456, \\u0441\\u0442\\u0456\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0428\\u0430\\u0444\\u0438, \\u0432\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456, \\u0441\\u0442\\u0456\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0428\\u0430\\u0444\\u0438, \\u0432\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456, \\u0441\\u0442\\u0456\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\"}'),
(199,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\"}'),
(200,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0444\\u0456\\u0441\\u043d\\u0438\\u0445 \\u043a\\u0440\\u0456\\u0441\\u0435\\u043b\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0444\\u0456\\u0441\\u043d\\u0438\\u0445 \\u043a\\u0440\\u0456\\u0441\\u0435\\u043b\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0444\\u0456\\u0441\\u043d\\u0438\\u0445 \\u043a\\u0440\\u0456\\u0441\\u0435\\u043b\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0444\\u0456\\u0441\\u043d\\u0438\\u0445 \\u043a\\u0440\\u0456\\u0441\\u0435\\u043b\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0444\\u0456\\u0441\\u043d\\u0438\\u0445 \\u043a\\u0440\\u0456\\u0441\\u0435\\u043b\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0444\\u0456\\u0441\\u043d\\u0438\\u0445 \\u043a\\u0440\\u0456\\u0441\\u0435\\u043b\"}'),
(201,	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 \\u0434\\u043b\\u044f \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 \\u0434\\u043b\\u044f \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 \\u0434\\u043b\\u044f \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 \\u0434\\u043b\\u044f \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 \\u0434\\u043b\\u044f \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 \\u0434\\u043b\\u044f \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\"}'),
(202,	'{\"en\":\"\\u041c\\u0435\\u0431\\u043b\\u0435\\u0432\\u0430 \\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\",\"ru\":\"\\u041c\\u0435\\u0431\\u043b\\u0435\\u0432\\u0430 \\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\",\"ua\":\"\\u041c\\u0435\\u0431\\u043b\\u0435\\u0432\\u0430 \\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 > \\u041c\\u0435\\u0431\\u043b\\u0435\\u0432\\u0430 \\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 > \\u041c\\u0435\\u0431\\u043b\\u0435\\u0432\\u0430 \\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 > \\u041c\\u0435\\u0431\\u043b\\u0435\\u0432\\u0430 \\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\"}'),
(203,	'{\"en\":\"\\u041f\\u043e\\u0441\\u0443\\u0434\",\"ru\":\"\\u041f\\u043e\\u0441\\u0443\\u0434\",\"ua\":\"\\u041f\\u043e\\u0441\\u0443\\u0434\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434\"}'),
(204,	'{\"en\":\"\\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456\",\"ru\":\"\\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456\",\"ua\":\"\\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456\"}'),
(205,	'{\"en\":\"\\u0421\\u043a\\u043e\\u0432\\u043e\\u0440\\u043e\\u0434\\u0438\",\"ru\":\"\\u0421\\u043a\\u043e\\u0432\\u043e\\u0440\\u043e\\u0434\\u0438\",\"ua\":\"\\u0421\\u043a\\u043e\\u0432\\u043e\\u0440\\u043e\\u0434\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0421\\u043a\\u043e\\u0432\\u043e\\u0440\\u043e\\u0434\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0421\\u043a\\u043e\\u0432\\u043e\\u0440\\u043e\\u0434\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0421\\u043a\\u043e\\u0432\\u043e\\u0440\\u043e\\u0434\\u0438\"}'),
(206,	'{\"en\":\"\\u041a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u0456, \\u043a\\u043e\\u0432\\u0448\\u0456, \\u0441\\u043e\\u0442\\u0435\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u041a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u0456, \\u043a\\u043e\\u0432\\u0448\\u0456, \\u0441\\u043e\\u0442\\u0435\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u041a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u0456, \\u043a\\u043e\\u0432\\u0448\\u0456, \\u0441\\u043e\\u0442\\u0435\\u0439\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u0456, \\u043a\\u043e\\u0432\\u0448\\u0456, \\u0441\\u043e\\u0442\\u0435\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u0456, \\u043a\\u043e\\u0432\\u0448\\u0456, \\u0441\\u043e\\u0442\\u0435\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u0456, \\u043a\\u043e\\u0432\\u0448\\u0456, \\u0441\\u043e\\u0442\\u0435\\u0439\\u043d\\u0438\\u043a\\u0438\"}'),
(207,	'{\"en\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\",\"ru\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\",\"ua\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\"}'),
(208,	'{\"en\":\"\\u041a\\u0440\\u0438\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\",\"ru\":\"\\u041a\\u0440\\u0438\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\",\"ua\":\"\\u041a\\u0440\\u0438\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041a\\u0440\\u0438\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041a\\u0440\\u0438\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041a\\u0440\\u0438\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0430\\u0441\\u0442\\u0440\\u0443\\u043b\\u044c, \\u0441\\u043a\\u043e\\u0432\\u043e\\u0440\\u0456\\u0434\"}'),
(209,	'{\"en\":\"\\u0424\\u043e\\u0440\\u043c\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u043f\\u0456\\u043a\\u0430\\u043d\\u043d\\u044f, \\u0434\\u0435\\u043a\\u0430, \\u0433\\u0443\\u0441\\u044f\\u0442\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u0424\\u043e\\u0440\\u043c\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u043f\\u0456\\u043a\\u0430\\u043d\\u043d\\u044f, \\u0434\\u0435\\u043a\\u0430, \\u0433\\u0443\\u0441\\u044f\\u0442\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u0424\\u043e\\u0440\\u043c\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u043f\\u0456\\u043a\\u0430\\u043d\\u043d\\u044f, \\u0434\\u0435\\u043a\\u0430, \\u0433\\u0443\\u0441\\u044f\\u0442\\u043d\\u0438\\u0446\\u0456\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0424\\u043e\\u0440\\u043c\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u043f\\u0456\\u043a\\u0430\\u043d\\u043d\\u044f, \\u0434\\u0435\\u043a\\u0430, \\u0433\\u0443\\u0441\\u044f\\u0442\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0424\\u043e\\u0440\\u043c\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u043f\\u0456\\u043a\\u0430\\u043d\\u043d\\u044f, \\u0434\\u0435\\u043a\\u0430, \\u0433\\u0443\\u0441\\u044f\\u0442\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0424\\u043e\\u0440\\u043c\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u043f\\u0456\\u043a\\u0430\\u043d\\u043d\\u044f, \\u0434\\u0435\\u043a\\u0430, \\u0433\\u0443\\u0441\\u044f\\u0442\\u043d\\u0438\\u0446\\u0456\"}'),
(210,	'{\"en\":\"\\u041d\\u043e\\u0436\\u0456 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\",\"ru\":\"\\u041d\\u043e\\u0436\\u0456 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\",\"ua\":\"\\u041d\\u043e\\u0436\\u0456 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041d\\u043e\\u0436\\u0456 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041d\\u043e\\u0436\\u0456 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041d\\u043e\\u0436\\u0456 \\u043a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0456\"}'),
(211,	'{\"en\":\"\\u0422\\u043e\\u0447\\u0438\\u043b\\u0430 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0436\\u0456\\u0432\",\"ru\":\"\\u0422\\u043e\\u0447\\u0438\\u043b\\u0430 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0436\\u0456\\u0432\",\"ua\":\"\\u0422\\u043e\\u0447\\u0438\\u043b\\u0430 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0436\\u0456\\u0432\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0422\\u043e\\u0447\\u0438\\u043b\\u0430 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0436\\u0456\\u0432\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0422\\u043e\\u0447\\u0438\\u043b\\u0430 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0436\\u0456\\u0432\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0422\\u043e\\u0447\\u0438\\u043b\\u0430 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0436\\u0456\\u0432\"}'),
(212,	'{\"en\":\"\\u0422\\u0435\\u0440\\u0442\\u043a\\u0438, \\u0448\\u0438\\u043d\\u043a\\u043e\\u0432\\u043a\\u0438, \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0422\\u0435\\u0440\\u0442\\u043a\\u0438, \\u0448\\u0438\\u043d\\u043a\\u043e\\u0432\\u043a\\u0438, \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0422\\u0435\\u0440\\u0442\\u043a\\u0438, \\u0448\\u0438\\u043d\\u043a\\u043e\\u0432\\u043a\\u0438, \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0422\\u0435\\u0440\\u0442\\u043a\\u0438, \\u0448\\u0438\\u043d\\u043a\\u043e\\u0432\\u043a\\u0438, \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0422\\u0435\\u0440\\u0442\\u043a\\u0438, \\u0448\\u0438\\u043d\\u043a\\u043e\\u0432\\u043a\\u0438, \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u0422\\u0435\\u0440\\u0442\\u043a\\u0438, \\u0448\\u0438\\u043d\\u043a\\u043e\\u0432\\u043a\\u0438, \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\"}'),
(213,	'{\"en\":\"\\u041e\\u0431\\u0440\\u043e\\u0431\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\",\"ru\":\"\\u041e\\u0431\\u0440\\u043e\\u0431\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\",\"ua\":\"\\u041e\\u0431\\u0440\\u043e\\u0431\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041e\\u0431\\u0440\\u043e\\u0431\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041e\\u0431\\u0440\\u043e\\u0431\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041e\\u0431\\u0440\\u043e\\u0431\\u043d\\u0456 \\u0434\\u043e\\u0448\\u043a\\u0438\"}'),
(214,	'{\"en\":\"\\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\",\"ru\":\"\\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\",\"ua\":\"\\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041a\\u0443\\u0445\\u043e\\u043d\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\"}'),
(215,	'{\"en\":\"\\u041c\\u0438\\u0441\\u043a\\u0438, \\u0434\\u0440\\u0443\\u0448\\u043b\\u044f\\u043a\\u0438\",\"ru\":\"\\u041c\\u0438\\u0441\\u043a\\u0438, \\u0434\\u0440\\u0443\\u0448\\u043b\\u044f\\u043a\\u0438\",\"ua\":\"\\u041c\\u0438\\u0441\\u043a\\u0438, \\u0434\\u0440\\u0443\\u0448\\u043b\\u044f\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041c\\u0438\\u0441\\u043a\\u0438, \\u0434\\u0440\\u0443\\u0448\\u043b\\u044f\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041c\\u0438\\u0441\\u043a\\u0438, \\u0434\\u0440\\u0443\\u0448\\u043b\\u044f\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041c\\u0438\\u0441\\u043a\\u0438, \\u0434\\u0440\\u0443\\u0448\\u043b\\u044f\\u043a\\u0438\"}'),
(216,	'{\"en\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0444\\u043e\\u043d\\u0434\\u044e, \\u043c\\u0430\\u0440\\u043c\\u0456\\u0442\\u0438\",\"ru\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0444\\u043e\\u043d\\u0434\\u044e, \\u043c\\u0430\\u0440\\u043c\\u0456\\u0442\\u0438\",\"ua\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0444\\u043e\\u043d\\u0434\\u044e, \\u043c\\u0430\\u0440\\u043c\\u0456\\u0442\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0444\\u043e\\u043d\\u0434\\u044e, \\u043c\\u0430\\u0440\\u043c\\u0456\\u0442\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0444\\u043e\\u043d\\u0434\\u044e, \\u043c\\u0430\\u0440\\u043c\\u0456\\u0442\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041f\\u0440\\u0438\\u0433\\u043e\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0457\\u0436\\u0456 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0444\\u043e\\u043d\\u0434\\u044e, \\u043c\\u0430\\u0440\\u043c\\u0456\\u0442\\u0438\"}'),
(217,	'{\"en\":\"\\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ru\":\"\\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ua\":\"\\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\"}'),
(218,	'{\"en\":\"\\u0425\\u043b\\u0456\\u0431\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u0425\\u043b\\u0456\\u0431\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u0425\\u043b\\u0456\\u0431\\u043d\\u0438\\u0446\\u0456\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432 > \\u0425\\u043b\\u0456\\u0431\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432 > \\u0425\\u043b\\u0456\\u0431\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432 > \\u0425\\u043b\\u0456\\u0431\\u043d\\u0438\\u0446\\u0456\"}'),
(219,	'{\"en\":\"\\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0438\\u043f\\u0443\\u0447\\u0438\\u0445 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ru\":\"\\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0438\\u043f\\u0443\\u0447\\u0438\\u0445 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ua\":\"\\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0438\\u043f\\u0443\\u0447\\u0438\\u0445 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432 > \\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0438\\u043f\\u0443\\u0447\\u0438\\u0445 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432 > \\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0438\\u043f\\u0443\\u0447\\u0438\\u0445 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432 > \\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0438\\u043f\\u0443\\u0447\\u0438\\u0445 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432\"}'),
(220,	'{\"en\":\"\\u0425\\u0430\\u0440\\u0447\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0435\\u0439\\u043d\\u0435\\u0440\\u0438\",\"ru\":\"\\u0425\\u0430\\u0440\\u0447\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0435\\u0439\\u043d\\u0435\\u0440\\u0438\",\"ua\":\"\\u0425\\u0430\\u0440\\u0447\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0435\\u0439\\u043d\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432 > \\u0425\\u0430\\u0440\\u0447\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0435\\u0439\\u043d\\u0435\\u0440\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432 > \\u0425\\u0430\\u0440\\u0447\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0435\\u0439\\u043d\\u0435\\u0440\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0417\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u043d\\u043d\\u044f \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442\\u0456\\u0432 > \\u0425\\u0430\\u0440\\u0447\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0435\\u0439\\u043d\\u0435\\u0440\\u0438\"}'),
(221,	'{\"en\":\"\\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443\",\"ru\":\"\\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443\",\"ua\":\"\\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443\"}'),
(222,	'{\"en\":\"\\u0421\\u0435\\u0440\\u0432\\u0456\\u0437\\u0438\",\"ru\":\"\\u0421\\u0435\\u0440\\u0432\\u0456\\u0437\\u0438\",\"ua\":\"\\u0421\\u0435\\u0440\\u0432\\u0456\\u0437\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0437\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0437\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0437\\u0438\"}'),
(223,	'{\"en\":\"\\u0422\\u0430\\u0440\\u0456\\u043b\\u043a\\u0438\",\"ru\":\"\\u0422\\u0430\\u0440\\u0456\\u043b\\u043a\\u0438\",\"ua\":\"\\u0422\\u0430\\u0440\\u0456\\u043b\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0422\\u0430\\u0440\\u0456\\u043b\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0422\\u0430\\u0440\\u0456\\u043b\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0422\\u0430\\u0440\\u0456\\u043b\\u043a\\u0438\"}'),
(224,	'{\"en\":\"\\u0421\\u0442\\u043e\\u043b\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0431\\u043e\\u0440\\u0438\",\"ru\":\"\\u0421\\u0442\\u043e\\u043b\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0431\\u043e\\u0440\\u0438\",\"ua\":\"\\u0421\\u0442\\u043e\\u043b\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0431\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0421\\u0442\\u043e\\u043b\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0431\\u043e\\u0440\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0421\\u0442\\u043e\\u043b\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0431\\u043e\\u0440\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0421\\u0442\\u043e\\u043b\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0431\\u043e\\u0440\\u0438\"}'),
(225,	'{\"en\":\"\\u041a\\u0435\\u043b\\u0438\\u0445\\u0438, \\u0441\\u043a\\u043b\\u044f\\u043d\\u043a\\u0438, \\u0447\\u0430\\u0440\\u043a\\u0438\",\"ru\":\"\\u041a\\u0435\\u043b\\u0438\\u0445\\u0438, \\u0441\\u043a\\u043b\\u044f\\u043d\\u043a\\u0438, \\u0447\\u0430\\u0440\\u043a\\u0438\",\"ua\":\"\\u041a\\u0435\\u043b\\u0438\\u0445\\u0438, \\u0441\\u043a\\u043b\\u044f\\u043d\\u043a\\u0438, \\u0447\\u0430\\u0440\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u041a\\u0435\\u043b\\u0438\\u0445\\u0438, \\u0441\\u043a\\u043b\\u044f\\u043d\\u043a\\u0438, \\u0447\\u0430\\u0440\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u041a\\u0435\\u043b\\u0438\\u0445\\u0438, \\u0441\\u043a\\u043b\\u044f\\u043d\\u043a\\u0438, \\u0447\\u0430\\u0440\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u041a\\u0435\\u043b\\u0438\\u0445\\u0438, \\u0441\\u043a\\u043b\\u044f\\u043d\\u043a\\u0438, \\u0447\\u0430\\u0440\\u043a\\u0438\"}'),
(226,	'{\"en\":\"\\u0413\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438, \\u0433\\u0440\\u0430\\u0444\\u0456\\u043d\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0430\\u043f\\u043e\\u0457\\u0432\",\"ru\":\"\\u0413\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438, \\u0433\\u0440\\u0430\\u0444\\u0456\\u043d\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0430\\u043f\\u043e\\u0457\\u0432\",\"ua\":\"\\u0413\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438, \\u0433\\u0440\\u0430\\u0444\\u0456\\u043d\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0430\\u043f\\u043e\\u0457\\u0432\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0413\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438, \\u0433\\u0440\\u0430\\u0444\\u0456\\u043d\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0430\\u043f\\u043e\\u0457\\u0432\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0413\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438, \\u0433\\u0440\\u0430\\u0444\\u0456\\u043d\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0430\\u043f\\u043e\\u0457\\u0432\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0413\\u043b\\u0435\\u0447\\u0438\\u043a\\u0438, \\u0433\\u0440\\u0430\\u0444\\u0456\\u043d\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0430\\u043f\\u043e\\u0457\\u0432\"}'),
(227,	'{\"en\":\"\\u041f\\u0440\\u0435\\u0434\\u043c\\u0435\\u0442\\u0438 \\u0441\\u0435\\u0440\\u0432\\u0456\\u0440\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u0440\\u0435\\u0434\\u043c\\u0435\\u0442\\u0438 \\u0441\\u0435\\u0440\\u0432\\u0456\\u0440\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u0440\\u0435\\u0434\\u043c\\u0435\\u0442\\u0438 \\u0441\\u0435\\u0440\\u0432\\u0456\\u0440\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u041f\\u0440\\u0435\\u0434\\u043c\\u0435\\u0442\\u0438 \\u0441\\u0435\\u0440\\u0432\\u0456\\u0440\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u041f\\u0440\\u0435\\u0434\\u043c\\u0435\\u0442\\u0438 \\u0441\\u0435\\u0440\\u0432\\u0456\\u0440\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u041f\\u0440\\u0435\\u0434\\u043c\\u0435\\u0442\\u0438 \\u0441\\u0435\\u0440\\u0432\\u0456\\u0440\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(228,	'{\"en\":\"\\u0427\\u0430\\u0448\\u043a\\u0438\",\"ru\":\"\\u0427\\u0430\\u0448\\u043a\\u0438\",\"ua\":\"\\u0427\\u0430\\u0448\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0427\\u0430\\u0448\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0427\\u0430\\u0448\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u0427\\u0430\\u0448\\u043a\\u0438\"}'),
(229,	'{\"en\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043f\\u0435\\u0446\\u0456\\u0439 \\u0456 \\u0441\\u043e\\u0443\\u0441\\u0456\\u0432\",\"ru\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043f\\u0435\\u0446\\u0456\\u0439 \\u0456 \\u0441\\u043e\\u0443\\u0441\\u0456\\u0432\",\"ua\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043f\\u0435\\u0446\\u0456\\u0439 \\u0456 \\u0441\\u043e\\u0443\\u0441\\u0456\\u0432\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043f\\u0435\\u0446\\u0456\\u0439 \\u0456 \\u0441\\u043e\\u0443\\u0441\\u0456\\u0432\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043f\\u0435\\u0446\\u0456\\u0439 \\u0456 \\u0441\\u043e\\u0443\\u0441\\u0456\\u0432\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u0421\\u0435\\u0440\\u0432\\u0456\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u043e\\u043b\\u0443 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043f\\u0435\\u0446\\u0456\\u0439 \\u0456 \\u0441\\u043e\\u0443\\u0441\\u0456\\u0432\"}'),
(230,	'{\"en\":\"\\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439\",\"ru\":\"\\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439\",\"ua\":\"\\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439\"}'),
(231,	'{\"en\":\"\\u0427\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0427\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0427\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0427\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0427\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0427\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\"}'),
(232,	'{\"en\":\"\\u0417\\u0430\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0417\\u0430\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0417\\u0430\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0417\\u0430\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0417\\u0430\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0417\\u0430\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0447\\u0430\\u0439\\u043d\\u0438\\u043a\\u0438\"}'),
(233,	'{\"en\":\"\\u0422\\u0443\\u0440\\u043a\\u0438, \\u0433\\u0435\\u0439\\u0437\\u0435\\u0440\\u043d\\u0456 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ru\":\"\\u0422\\u0443\\u0440\\u043a\\u0438, \\u0433\\u0435\\u0439\\u0437\\u0435\\u0440\\u043d\\u0456 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ua\":\"\\u0422\\u0443\\u0440\\u043a\\u0438, \\u0433\\u0435\\u0439\\u0437\\u0435\\u0440\\u043d\\u0456 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0422\\u0443\\u0440\\u043a\\u0438, \\u0433\\u0435\\u0439\\u0437\\u0435\\u0440\\u043d\\u0456 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0422\\u0443\\u0440\\u043a\\u0438, \\u0433\\u0435\\u0439\\u0437\\u0435\\u0440\\u043d\\u0456 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0422\\u0443\\u0440\\u043a\\u0438, \\u0433\\u0435\\u0439\\u0437\\u0435\\u0440\\u043d\\u0456 \\u043a\\u0430\\u0432\\u043e\\u0432\\u0430\\u0440\\u043a\\u0438\"}'),
(234,	'{\"en\":\"\\u0422\\u0435\\u0440\\u043c\\u043e\\u0441\\u0438\",\"ru\":\"\\u0422\\u0435\\u0440\\u043c\\u043e\\u0441\\u0438\",\"ua\":\"\\u0422\\u0435\\u0440\\u043c\\u043e\\u0441\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0422\\u0435\\u0440\\u043c\\u043e\\u0441\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0422\\u0435\\u0440\\u043c\\u043e\\u0441\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0441\\u0443\\u0434 > \\u041a\\u0430\\u0432\\u0430, \\u0447\\u0430\\u0439 > \\u0422\\u0435\\u0440\\u043c\\u043e\\u0441\\u0438\"}'),
(235,	'{\"en\":\"\\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430\",\"ru\":\"\\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430\",\"ua\":\"\\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430\"}'),
(236,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\"}'),
(237,	'{\"en\":\"\\u0420\\u0435\\u043b\\u0435 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438, \\u0441\\u0442\\u0440\\u0443\\u043c\\u0443\",\"ru\":\"\\u0420\\u0435\\u043b\\u0435 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438, \\u0441\\u0442\\u0440\\u0443\\u043c\\u0443\",\"ua\":\"\\u0420\\u0435\\u043b\\u0435 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438, \\u0441\\u0442\\u0440\\u0443\\u043c\\u0443\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0420\\u0435\\u043b\\u0435 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438, \\u0441\\u0442\\u0440\\u0443\\u043c\\u0443\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0420\\u0435\\u043b\\u0435 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438, \\u0441\\u0442\\u0440\\u0443\\u043c\\u0443\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0420\\u0435\\u043b\\u0435 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438, \\u0441\\u0442\\u0440\\u0