(238,	'{\"en\":\"\\u0420\\u0435\\u043b\\u0435 \\u0447\\u0430\\u0441\\u0443 (\\u0442\\u0430\\u0439\\u043c\\u0435\\u0440\\u0438)\",\"ru\":\"\\u0420\\u0435\\u043b\\u0435 \\u0447\\u0430\\u0441\\u0443 (\\u0442\\u0430\\u0439\\u043c\\u0435\\u0440\\u0438)\",\"ua\":\"\\u0420\\u0435\\u043b\\u0435 \\u0447\\u0430\\u0441\\u0443 (\\u0442\\u0430\\u0439\\u043c\\u0435\\u0440\\u0438)\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0420\\u0435\\u043b\\u0435 \\u0447\\u0430\\u0441\\u0443 (\\u0442\\u0430\\u0439\\u043c\\u0435\\u0440\\u0438)\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0420\\u0435\\u043b\\u0435 \\u0447\\u0430\\u0441\\u0443 (\\u0442\\u0430\\u0439\\u043c\\u0435\\u0440\\u0438)\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0420\\u0435\\u043b\\u0435 \\u0447\\u0430\\u0441\\u0443 (\\u0442\\u0430\\u0439\\u043c\\u0435\\u0440\\u0438)\"}'),
(239,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\"}'),
(240,	'{\"en\":\"\\u0417\\u0430\\u0445\\u0438\\u0441\\u043d\\u0456 \\u0440\\u0435\\u043b\\u0435 (\\u0456\\u043d\\u0448\\u0456)\",\"ru\":\"\\u0417\\u0430\\u0445\\u0438\\u0441\\u043d\\u0456 \\u0440\\u0435\\u043b\\u0435 (\\u0456\\u043d\\u0448\\u0456)\",\"ua\":\"\\u0417\\u0430\\u0445\\u0438\\u0441\\u043d\\u0456 \\u0440\\u0435\\u043b\\u0435 (\\u0456\\u043d\\u0448\\u0456)\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0417\\u0430\\u0445\\u0438\\u0441\\u043d\\u0456 \\u0440\\u0435\\u043b\\u0435 (\\u0456\\u043d\\u0448\\u0456)\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0417\\u0430\\u0445\\u0438\\u0441\\u043d\\u0456 \\u0440\\u0435\\u043b\\u0435 (\\u0456\\u043d\\u0448\\u0456)\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456 \\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 > \\u0417\\u0430\\u0445\\u0438\\u0441\\u043d\\u0456 \\u0440\\u0435\\u043b\\u0435 (\\u0456\\u043d\\u0448\\u0456)\"}'),
(241,	'{\"en\":\"\\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f\"}'),
(242,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0430\\u043c\\u043f\\u0438\"}'),
