(248,	'{\"en\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\"}'),
(249,	'{\"en\":\"\\u041d\\u0438\\u0437\\u044c\\u043a\\u043e\\u0432\\u043e\\u043b\\u044c\\u0442\\u043d\\u0456 \\u0431\\u043b\\u043e\\u043a\\u0438 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041d\\u0438\\u0437\\u044c\\u043a\\u043e\\u0432\\u043e\\u043b\\u044c\\u0442\\u043d\\u0456 \\u0431\\u043b\\u043e\\u043a\\u0438 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041d\\u0438\\u0437\\u044c\\u043a\\u043e\\u0432\\u043e\\u043b\\u044c\\u0442\\u043d\\u0456 \\u0431\\u043b\\u043e\\u043a\\u0438 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u041d\\u0438\\u0437\\u044c\\u043a\\u043e\\u0432\\u043e\\u043b\\u044c\\u0442\\u043d\\u0456 \\u0431\\u043b\\u043e\\u043a\\u0438 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u041d\\u0438\\u0437\\u044c\\u043a\\u043e\\u0432\\u043e\\u043b\\u044c\\u0442\\u043d\\u0456 \\u0431\\u043b\\u043e\\u043a\\u0438 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u041d\\u0438\\u0437\\u044c\\u043a\\u043e\\u0432\\u043e\\u043b\\u044c\\u0442\\u043d\\u0456 \\u0431\\u043b\\u043e\\u043a\\u0438 \\u0436\\u04