(250,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0440\\u043b\\u044f\\u043d\\u0434\\u0438\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0440\\u043b\\u044f\\u043d\\u0434\\u0438\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0440\\u043b\\u044f\\u043d\\u0434\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0440\\u043b\\u044f\\u043d\\u0434\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0440\\u043b\\u044f\\u043d\\u0434\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0440\\u043b\\u044f\\u043d\\u0434\\u0438\"}'),
(251,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430\"}'),
(252,	'{\"en\":\"\\u0412\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456, \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\",\"ru\":\"\\u0412\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456, \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\",\"ua\":\"\\u0412\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456, \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0412\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456, \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0412\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456, \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0412\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456, \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\"}'),
(253,	'{\"en\":\"\\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0456 \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\",\"ru\":\"\\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0456 \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\",\"ua\":\"\\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0456 \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0456 \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0456 \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0456 \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438\"}'),
(254,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\"}'),
(255,	'{\"en\":\"\\u0429\\u0438\\u0442\\u0438 (\\u043a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438) \\u0434\\u043b\\u044f \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\\u0432 \\u0456 \\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0456\\u0432\",\"ru\":\"\\u0429\\u0438\\u0442\\u0438 (\\u043a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438) \\u0434\\u043b\\u044f \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\\u0432 \\u0456 \\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0456\\u0432\",\"ua\":\"\\u0429\\u0438\\u0442\\u0438 (\\u043a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438) \\u0434\\u043b\\u044f \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\\u0432 \\u0456 \\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0456\\u0432\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0429\\u0438\\u0442\\u0438 (\\u043a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438) \\u0434\\u043b\\u044f \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\\u0432 \\u0456 \\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0456\\u0432\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0429\\u0438\\u0442\\u0438 (\\u043a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438) \\u0434\\u043b\\u044f \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\\u0432 \\u0456 \\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0456\\u0432\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0429\\u0438\\u0442\\u0438 (\\u043a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438) \\u0434\\u043b\\u044f \\u0432\\u0438\\u043c\\u0438\\u043a\\u0430\\u0447\\u0456\\u0432 \\u0456 \\u043b\\u0456\\u0447\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0456\\u0432\"}'),
(256,	'{\"en\":\"\\u0421\\u0438\\u043b\\u043e\\u0432\\u0456 \\u043a\\u0430\\u0431\\u0435\\u043b\\u0456, \\u0434\\u0440\\u043e\\u0442\\u0438\",\"ru\":\"\\u0421\\u0438\\u043b\\u043e\\u0432\\u0456 \\u043a\\u0430\\u0431\\u0435\\u043b\\u0456, \\u0434\\u0440\\u043e\\u0442\\u0438\",\"ua\":\"\\u0421\\u0438\\u043b\\u043e\\u0432\\u0456 \\u043a\\u0430\\u0431\\u0435\\u043b\\u0456, \\u0434\\u0440\\u043e\\u0442\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0421\\u0438\\u043b\\u043e\\u0432\\u0456 \\u043a\\u0430\\u0431\\u0435\\u043b\\u0456, \\u0434\\u0440\\u043e\\u0442\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0421\\u0438\\u043b\\u043e\\u0432\\u0456 \\u043a\\u0430\\u0431\\u0435\\u043b\\u0456, \\u0434\\u0440\\u043e\\u0442\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u0438\\u043a\\u0430 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0444\\u0443\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430 > \\u0421\\u0438\\u043b\\u043e\\u0432\\u0456 \\u043a\\u0430\\u0431\\u0435\\u043b\\u0456, \\u0434\\u0440\\u043e\\u0442\\u0438\"}'),
(257,	'{\"en\":\"\\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c\",\"ru\":\"\\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c\",\"ua\":\"\\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c\"}'),
(258,	'{\"en\":\"\\u041c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438\",\"ru\":\"\\u041c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438\",\"ua\":\"\\u041c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438\"}'),
(259,	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043f\\u043e\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u043e\\u0457 \\u0431\\u0456\\u043b\\u0438\\u0437\\u043d\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043f\\u043e\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u043e\\u0457 \\u0431\\u0456\\u043b\\u0438\\u0437\\u043d\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043f\\u043e\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u043e\\u0457 \\u0431\\u0456\\u043b\\u0438\\u0437\\u043d\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043f\\u043e\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u043e\\u0457 \\u0431\\u0456\\u043b\\u0438\\u0437\\u043d\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043f\\u043e\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u043e\\u0457 \\u0431\\u0456\\u043b\\u0438\\u0437\\u043d\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u043f\\u043e\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u043e\\u0457 \\u0431\\u0456\\u043b\\u0438\\u0437\\u043d\\u0438\"}'),
(260,	'{\"en\":\"\\u041f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430, \\u043f\\u0456\\u0434\\u043a\\u043e\\u0432\\u0434\\u0440\\u0438, \\u043d\\u0430\\u0432\\u043e\\u043b\\u043e\\u0447\\u043a\\u0438\",\"ru\":\"\\u041f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430, \\u043f\\u0456\\u0434\\u043a\\u043e\\u0432\\u0434\\u0440\\u0438, \\u043d\\u0430\\u0432\\u043e\\u043b\\u043e\\u0447\\u043a\\u0438\",\"ua\":\"\\u041f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430, \\u043f\\u0456\\u0434\\u043a\\u043e\\u0432\\u0434\\u0440\\u0438, \\u043d\\u0430\\u0432\\u043e\\u043b\\u043e\\u0447\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430, \\u043f\\u0456\\u0434\\u043a\\u043e\\u0432\\u0434\\u0440\\u0438, \\u043d\\u0430\\u0432\\u043e\\u043b\\u043e\\u0447\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430, \\u043f\\u0456\\u0434\\u043a\\u043e\\u0432\\u0434\\u0440\\u0438, \\u043d\\u0430\\u0432\\u043e\\u043b\\u043e\\u0447\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430, \\u043f\\u0456\\u0434\\u043a\\u043e\\u0432\\u0434\\u0440\\u0438, \\u043d\\u0430\\u0432\\u043e\\u043b\\u043e\\u0447\\u043a\\u0438\"}'),
(261,	'{\"en\":\"\\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\",\"ru\":\"\\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\",\"ua\":\"\\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\"}'),
(262,	'{\"en\":\"\\u041a\\u043e\\u0432\\u0434\\u0440\\u0438\",\"ru\":\"\\u041a\\u043e\\u0432\\u0434\\u0440\\u0438\",\"ua\":\"\\u041a\\u043e\\u0432\\u0434\\u0440\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041a\\u043e\\u0432\\u0434\\u0440\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041a\\u043e\\u0432\\u0434\\u0440\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041a\\u043e\\u0432\\u0434\\u0440\\u0438\"}'),
(263,	'{\"en\":\"\\u041f\\u043b\\u0435\\u0434\\u0438\",\"ru\":\"\\u041f\\u043b\\u0435\\u0434\\u0438\",\"ua\":\"\\u041f\\u043b\\u0435\\u0434\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u043b\\u0435\\u0434\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u043b\\u0435\\u0434\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u043b\\u0435\\u0434\\u0438\"}'),
(264,	'{\"en\":\"\\u041d\\u0430\\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u041d\\u0430\\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u041d\\u0430\\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041d\\u0430\\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041d\\u0430\\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041d\\u0430\\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u043d\\u0438\\u043a\\u0438\"}'),
(265,	'{\"en\":\"\\u041f\\u043e\\u043a\\u0440\\u0438\\u0432\\u0430\\u043b\\u0430\",\"ru\":\"\\u041f\\u043e\\u043a\\u0440\\u0438\\u0432\\u0430\\u043b\\u0430\",\"ua\":\"\\u041f\\u043e\\u043a\\u0440\\u0438\\u0432\\u0430\\u043b\\u0430\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u043e\\u043a\\u0440\\u0438\\u0432\\u0430\\u043b\\u0430\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u043e\\u043a\\u0440\\u0438\\u0432\\u0430\\u043b\\u0430\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u041f\\u043e\\u043a\\u0440\\u0438\\u0432\\u0430\\u043b\\u0430\"}'),
(266,	'{\"en\":\"\\u0421\\u043a\\u0430\\u0442\\u0435\\u0440\\u0442\\u0438\\u043d\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\",\"ru\":\"\\u0421\\u043a\\u0430\\u0442\\u0435\\u0440\\u0442\\u0438\\u043d\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\",\"ua\":\"\\u0421\\u043a\\u0430\\u0442\\u0435\\u0440\\u0442\\u0438\\u043d\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u0421\\u043a\\u0430\\u0442\\u0435\\u0440\\u0442\\u0438\\u043d\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u0421\\u043a\\u0430\\u0442\\u0435\\u0440\\u0442\\u0438\\u043d\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u0421\\u043a\\u0430\\u0442\\u0435\\u0440\\u0442\\u0438\\u043d\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\"}'),
(267,	'{\"en\":\"\\u0420\\u0443\\u0448\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0420\\u0443\\u0448\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0420\\u0443\\u0448\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u0420\\u0443\\u0448\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u0420\\u0443\\u0448\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u043c\\u0430\\u0448\\u043d\\u0456\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0438\\u043b\\u044c > \\u0420\\u0443\\u0448\\u043d\\u0438\\u043a\\u0438\"}'),
(268,	'{\"en\":\"\\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440\",\"ru\":\"\\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440\",\"ua\":\"\\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440\"}'),
(269,	'{\"en\":\"\\u041f\\u043e\\u0434\\u0430\\u0440\\u0443\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0441\\u0435\\u0440\\u0442\\u0438\\u0444\\u0456\\u043a\\u0430\\u0442\\u0438\",\"ru\":\"\\u041f\\u043e\\u0434\\u0430\\u0440\\u0443\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0441\\u0435\\u0440\\u0442\\u0438\\u0444\\u0456\\u043a\\u0430\\u0442\\u0438\",\"ua\":\"\\u041f\\u043e\\u0434\\u0430\\u0440\\u0443\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0441\\u0435\\u0440\\u0442\\u0438\\u0444\\u0456\\u043a\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u041f\\u043e\\u0434\\u0430\\u0440\\u0443\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0441\\u0435\\u0440\\u0442\\u0438\\u0444\\u0456\\u043a\\u0430\\u0442\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u041f\\u043e\\u0434\\u0430\\u0440\\u0443\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0441\\u0435\\u0440\\u0442\\u0438\\u0444\\u0456\\u043a\\u0430\\u0442\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u041f\\u043e\\u0434\\u0430\\u0440\\u0443\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0441\\u0435\\u0440\\u0442\\u0438\\u0444\\u0456\\u043a\\u0430\\u0442\\u0438\"}'),
(270,	'{\"en\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\"}'),
(271,	'{\"en\":\"\\u0412\\u0430\\u0437\\u0438\",\"ru\":\"\\u0412\\u0430\\u0437\\u0438\",\"ua\":\"\\u0412\\u0430\\u0437\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u0412\\u0430\\u0437\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u0412\\u0430\\u0437\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u0412\\u0430\\u0437\\u0438\"}'),
(272,	'{\"en\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043d\\u043d\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u0434\\u043b\\u043e\\u0433\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043d\\u043d\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u0434\\u043b\\u043e\\u0433\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043d\\u043d\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u0434\\u043b\\u043e\\u0433\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043d\\u043d\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u0434\\u043b\\u043e\\u0433\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043d\\u043d\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u0434\\u043b\\u043e\\u0433\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043d\\u043d\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u0434\\u043b\\u043e\\u0433\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0434\\u0438\\u043d\\u043d\\u0438\\u043a\\u0438\"}'),
(273,	'{\"en\":\"\\u0413\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u043a\\u0430\\u0448\\u043f\\u043e \\u0434\\u043b\\u044f \\u0440\\u043e\\u0441\\u043b\\u0438\\u043d\",\"ru\":\"\\u0413\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u043a\\u0430\\u0448\\u043f\\u043e \\u0434\\u043b\\u044f \\u0440\\u043e\\u0441\\u043b\\u0438\\u043d\",\"ua\":\"\\u0413\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u043a\\u0430\\u0448\\u043f\\u043e \\u0434\\u043b\\u044f \\u0440\\u043e\\u0441\\u043b\\u0438\\u043d\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u0413\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u043a\\u0430\\u0448\\u043f\\u043e \\u0434\\u043b\\u044f \\u0440\\u043e\\u0441\\u043b\\u0438\\u043d\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u0413\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u043a\\u0430\\u0448\\u043f\\u043e \\u0434\\u043b\\u044f \\u0440\\u043e\\u0441\\u043b\\u0438\\u043d\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u0413\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u043a\\u0430\\u0448\\u043f\\u043e \\u0434\\u043b\\u044f \\u0440\\u043e\\u0441\\u043b\\u0438\\u043d\"}'),
(274,	'{\"en\":\"\\u0416\\u0430\\u043b\\u044e\\u0437\\u0456, \\u0440\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0442\\u0430 \\u0440\\u0443\\u043b\\u043e\\u043d\\u043d\\u0456 \\u0448\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0416\\u0430\\u043b\\u044e\\u0437\\u0456, \\u0440\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0442\\u0430 \\u0440\\u0443\\u043b\\u043e\\u043d\\u043d\\u0456 \\u0448\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0416\\u0430\\u043b\\u044e\\u0437\\u0456, \\u0440\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0442\\u0430 \\u0440\\u0443\\u043b\\u043e\\u043d\\u043d\\u0456 \\u0448\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u0416\\u0430\\u043b\\u044e\\u0437\\u0456, \\u0440\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0442\\u0430 \\u0440\\u0443\\u043b\\u043e\\u043d\\u043d\\u0456 \\u0448\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u0416\\u0430\\u043b\\u044e\\u0437\\u0456, \\u0440\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0442\\u0430 \\u0440\\u0443\\u043b\\u043e\\u043d\\u043d\\u0456 \\u0448\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0442\\u0435\\u0440\'\\u0454\\u0440 > \\u0416\\u0430\\u043b\\u044e\\u0437\\u0456, \\u0440\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0442\\u0430 \\u0440\\u0443\\u043b\\u043e\\u043d\\u043d\\u0456 \\u0448\\u0442\\u043e\\u0440\\u0438\"}'),
