(305,	'{\"en\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0432\\u0456\\u0434 \\u043a\\u043e\\u043c\\u0430\\u0445\",\"ru\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0432\\u0456\\u0434 \\u043a\\u043e\\u043c\\u0430\\u0445\",\"ua\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0432\\u0456\\u0434 \\u043a\\u043e\\u043c\\u0430\\u0445\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0445\\u0456\\u043c\\u0456\\u044f, \\u0433\\u043e\\u0441\\u043f\\u043e\\u0434\\u0430\\u0440\\u0441\\u044c\\u043a\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0445\\u0456\\u043c\\u0456\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0432\\u0456\\u0434 \\u043a\\u043e\\u043c\\u0430\\u0445\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0445\\u0456\\u043c\\u0456\\u044f, \\u0433\\u043e\\u0441\\u043f\\u043e\\u0434\\u0430\\u0440\\u0441\\u044c\\u043a\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0445\\u0456\\u043c\\u0456\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0432\\u0456\\u0434 \\u043a\\u043e\\u043c\\u0430\\u0445\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0445\\u0456\\u043c\\u0456\\u044f, \\u0433\\u043e\\u0441\\u043f\\u043e\\u0434\\u0430\\u0440\\u0441\\u044c\\u043a\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u043e\\u0431\\u0443\\u0442\\u043e\\u0432\\u0430 \\u0445\\u0456\\u043c\\u0456\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0432\\u0456\\u0434 \\u043a\\u043e\\u043c\\u0430\\u0445\"}'),
(306,	'{\"en\":\"\\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a\",\"ru\":\"\\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a\",\"ua\":\"\\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a\"}'),
(307,	'{\"en\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043f\\u0456\\u0434\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043d\\u044f \\u0440\\u043e\\u0437\\u0443\\u043c\\u043d\\u043e\\u0433\\u043e \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\",\"ru\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043f\\u0456\\u0434\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043d\\u044f \\u0440\\u043e\\u0437\\u0443\\u043c\\u043d\\u043e\\u0433\\u043e \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\",\"ua\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043f\\u0456\\u0434\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043d\\u044f \\u0440\\u043e\\u0437\\u0443\\u043c\\u043d\\u043e\\u0433\\u043e \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043f\\u0456\\u0434\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043d\\u044f \\u0440\\u043e\\u0437\\u0443\\u043c\\u043d\\u043e\\u0433\\u043e \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043f\\u0456\\u0434\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043d\\u044f \\u0440\\u043e\\u0437\\u0443\\u043c\\u043d\\u043e\\u0433\\u043e \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043f\\u0456\\u0434\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043d\\u044f \\u0440\\u043e\\u0437\\u0443\\u043c\\u043d\\u043e\\u0433\\u043e \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\"}'),
(308,	'{\"en\":\"\\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0434\\u0456\\u043c, \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438\",\"ru\":\"\\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0434\\u0456\\u043c, \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438\",\"ua\":\"\\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0434\\u0456\\u043c, \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043f\\u0456\\u0434\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043d\\u044f \\u0440\\u043e\\u0437\\u0443\\u043c\\u043d\\u043e\\u0433\\u043e \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0434\\u0456\\u043c, \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043f\\u0456\\u0434\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043d\\u044f \\u0440\\u043e\\u0437\\u0443\\u043c\\u043d\\u043e\\u0433\\u043e \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0434\\u0456\\u043c, \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043f\\u0456\\u0434\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043d\\u044f \\u0440\\u043e\\u0437\\u0443\\u043c\\u043d\\u043e\\u0433\\u043e \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0434\\u0456\\u043c, \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438\"}'),
(309,	'{\"en\":\"\\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\",\"ru\":\"\\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\",\"ua\":\"\\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\"}'),
(310,	'{\"en\":\"\\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0432\\u0456\\u0434\\u0435\\u043e\\u0441\\u043f\\u043e\\u0441\\u0442\\u0435\\u0440\\u0435\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0432\\u0456\\u0434\\u0435\\u043e\\u0441\\u043f\\u043e\\u0441\\u0442\\u0435\\u0440\\u0435\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0432\\u0456\\u0434\\u0435\\u043e\\u0441\\u043f\\u043e\\u0441\\u0442\\u0435\\u0440\\u0435\\u0436\\u0435\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0432\\u0456\\u0434\\u0435\\u043e\\u0441\\u043f\\u043e\\u0441\\u0442\\u0435\\u0440\\u0435\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0432\\u0456\\u0434\\u0435\\u043e\\u0441\\u043f\\u043e\\u0441\\u0442\\u0435\\u0440\\u0435\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u041a\\u0430\\u043c\\u0435\\u0440\\u0438 \\u0432\\u0456\\u0434\\u0435\\u043e\\u0441\\u043f\\u043e\\u0441\\u0442\\u0435\\u0440\\u0435\\u0436\\u0435\\u043d\\u043d\\u044f\"}'),
(311,	'{\"en\":\"\\u0412\\u0456\\u0434\\u0435\\u043e\\u0440\\u0435\\u0454\\u0441\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0438\\u0445 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\",\"ru\":\"\\u0412\\u0456\\u0434\\u0435\\u043e\\u0440\\u0435\\u0454\\u0441\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0438\\u0445 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\",\"ua\":\"\\u0412\\u0456\\u0434\\u0435\\u043e\\u0440\\u0435\\u0454\\u0441\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0438\\u0445 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0412\\u0456\\u0434\\u0435\\u043e\\u0440\\u0435\\u0454\\u0441\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0438\\u0445 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0412\\u0456\\u0434\\u0435\\u043e\\u0440\\u0435\\u0454\\u0441\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0438\\u0445 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0412\\u0456\\u0434\\u0435\\u043e\\u0440\\u0435\\u0454\\u0441\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0438\\u0445 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\"}'),
(312,	'{\"en\":\"\\u0414\\u043e\\u043c\\u043e\\u0444\\u043e\\u043d\\u0438\",\"ru\":\"\\u0414\\u043e\\u043c\\u043e\\u0444\\u043e\\u043d\\u0438\",\"ua\":\"\\u0414\\u043e\\u043c\\u043e\\u0444\\u043e\\u043d\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0414\\u043e\\u043c\\u043e\\u0444\\u043e\\u043d\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0414\\u043e\\u043c\\u043e\\u0444\\u043e\\u043d\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0414\\u043e\\u043c\\u043e\\u0444\\u043e\\u043d\\u0438\"}'),
(313,	'{\"en\":\"\\u0421\\u0435\\u0439\\u0444\\u0438\",\"ru\":\"\\u0421\\u0435\\u0439\\u0444\\u0438\",\"ua\":\"\\u0421\\u0435\\u0439\\u0444\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0421\\u0435\\u0439\\u0444\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0421\\u0435\\u0439\\u0444\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0421\\u0435\\u0439\\u0444\\u0438\"}'),
(314,	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0456\\u0437\\u0430\\u0446\\u0456\\u0439\"}'),
(315,	'{\"en\":\"\\u0414\\u0430\\u0442\\u0447\\u0438\\u043a\\u0438, \\u0441\\u043f\\u043e\\u0432\\u0456\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0414\\u0430\\u0442\\u0447\\u0438\\u043a\\u0438, \\u0441\\u043f\\u043e\\u0432\\u0456\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0414\\u0430\\u0442\\u0447\\u0438\\u043a\\u0438, \\u0441\\u043f\\u043e\\u0432\\u0456\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0414\\u0430\\u0442\\u0447\\u0438\\u043a\\u0438, \\u0441\\u043f\\u043e\\u0432\\u0456\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0414\\u0430\\u0442\\u0447\\u0438\\u043a\\u0438, \\u0441\\u043f\\u043e\\u0432\\u0456\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u0414\\u0430\\u0442\\u0447\\u0438\\u043a\\u0438, \\u0441\\u043f\\u043e\\u0432\\u0456\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456\"}'),
(316,	'{\"en\":\"\\u041e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ru\":\"\\u041e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ua\":\"\\u041e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u041e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u041e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u043e\\u0437\\u0443\\u043c\\u043d\\u0438\\u0439 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430 > \\u041e\\u0445\\u043e\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\"}'),
(317,	'{\"en\":\"\\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ru\":\"\\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ua\":\"\\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\"}'),
(318,	'{\"en\":\"\\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u044f\\u043b\\u0438\\u043d\\u043a\\u0438\",\"ru\":\"\\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u044f\\u043b\\u0438\\u043d\\u043a\\u0438\",\"ua\":\"\\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u044f\\u043b\\u0438\\u043d\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u044f\\u043b\\u0438\\u043d\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u044f\\u043b\\u0438\\u043d\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u044f\\u043b\\u0438\\u043d\\u043a\\u0438\"}'),
(319,	'{\"en\":\"\\u042f\\u043b\\u0438\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ru\":\"\\u042f\\u043b\\u0438\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ua\":\"\\u042f\\u043b\\u0438\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u042f\\u043b\\u0438\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u042f\\u043b\\u0438\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u042f\\u043b\\u0438\\u043d\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\"}'),
(320,	'{\"en\":\"\\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\",\"ru\":\"\\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\",\"ua\":\"\\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\"}',	'{\"en\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\",\"ru\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\",\"ua\":\"\\u0412\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041d\\u043e\\u0432\\u043e\\u0440\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\"}'),
(321,	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434\"}'),
(322,	'{\"en\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ru\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ua\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\"}'),
(323,	'{\"en\":\"\\u0411\\u0435\\u043d\\u0437\\u043e\\u043f\\u0438\\u043b\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043f\\u0438\\u043b\\u0438\",\"ru\":\"\\u0411\\u0435\\u043d\\u0437\\u043e\\u043f\\u0438\\u043b\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043f\\u0438\\u043b\\u0438\",\"ua\":\"\\u0411\\u0435\\u043d\\u0437\\u043e\\u043f\\u0438\\u043b\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043f\\u0438\\u043b\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u043d\\u0437\\u043e\\u043f\\u0438\\u043b\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043f\\u0438\\u043b\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u043d\\u0437\\u043e\\u043f\\u0438\\u043b\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043f\\u0438\\u043b\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0411\\u0435\\u043d\\u0437\\u043e\\u043f\\u0438\\u043b\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043f\\u0438\\u043b\\u0438\"}'),
(324,	'{\"en\":\"\\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u0442\\u0430 \\u0448\\u0438\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\",\"ru\":\"\\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u0442\\u0430 \\u0448\\u0438\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\",\"ua\":\"\\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u0442\\u0430 \\u0448\\u0438\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u0442\\u0430 \\u0448\\u0438\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u0442\\u0430 \\u0448\\u0438\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041b\\u0430\\u043d\\u0446\\u044e\\u0433\\u0438 \\u0442\\u0430 \\u0448\\u0438\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0438\\u043b\"}'),
(325,	'{\"en\":\"\\u041a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0438\",\"ru\":\"\\u041a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0438\",\"ua\":\"\\u041a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0438\"}'),
(326,	'{\"en\":\"\\u041d\\u0430\\u0432\\u0456\\u0441\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043e \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0456\\u0432, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0456\\u0432 \\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\",\"ru\":\"\\u041d\\u0430\\u0432\\u0456\\u0441\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043e \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0456\\u0432, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0456\\u0432 \\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\",\"ua\":\"\\u041d\\u0430\\u0432\\u0456\\u0441\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043e \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0456\\u0432, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0456\\u0432 \\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041d\\u0430\\u0432\\u0456\\u0441\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043e \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0456\\u0432, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0456\\u0432 \\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041d\\u0430\\u0432\\u0456\\u0441\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043e \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0456\\u0432, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0456\\u0432 \\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041d\\u0430\\u0432\\u0456\\u0441\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043e \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0456\\u0432, \\u043c\\u043e\\u0442\\u043e\\u0431\\u043b\\u043e\\u043a\\u0456\\u0432 \\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\"}'),
(327,	'{\"en\":\"\\u041c\\u043e\\u0442\\u043e\\u043a\\u043e\\u0441\\u0438, \\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438\",\"ru\":\"\\u041c\\u043e\\u0442\\u043e\\u043a\\u043e\\u0441\\u0438, \\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438\",\"ua\":\"\\u041c\\u043e\\u0442\\u043e\\u043a\\u043e\\u0441\\u0438, \\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041c\\u043e\\u0442\\u043e\\u043a\\u043e\\u0441\\u0438, \\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041c\\u043e\\u0442\\u043e\\u043a\\u043e\\u0441\\u0438, \\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041c\\u043e\\u0442\\u043e\\u043a\\u043e\\u0441\\u0438, \\u0442\\u0440\\u0438\\u043c\\u0435\\u0440\\u0438\"}'),
(328,	'{\"en\":\"\\u0413\\u0430\\u0437\\u043e\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438, \\u0441\\u0456\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438\",\"ru\":\"\\u0413\\u0430\\u0437\\u043e\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438, \\u0441\\u0456\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438\",\"ua\":\"\\u0413\\u0430\\u0437\\u043e\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438, \\u0441\\u0456\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0413\\u0430\\u0437\\u043e\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438, \\u0441\\u0456\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0413\\u0430\\u0437\\u043e\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438, \\u0441\\u0456\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0413\\u0430\\u0437\\u043e\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438, \\u0441\\u0456\\u043d\\u043e\\u043a\\u043e\\u0441\\u0430\\u0440\\u043a\\u0438\"}'),
(329,	'{\"en\":\"\\u041a\\u0443\\u0449\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0432\\u0438\\u0441\\u043e\\u0442\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u041a\\u0443\\u0449\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0432\\u0438\\u0441\\u043e\\u0442\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u041a\\u0443\\u0449\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0432\\u0438\\u0441\\u043e\\u0442\\u043e\\u0440\\u0456\\u0437\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0443\\u0449\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0432\\u0438\\u0441\\u043e\\u0442\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0443\\u0449\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0432\\u0438\\u0441\\u043e\\u0442\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041a\\u0443\\u0449\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0432\\u0438\\u0441\\u043e\\u0442\\u043e\\u0440\\u0456\\u0437\\u0438\"}'),
(330,	'{\"en\":\"\\u041c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043a\\u0438\",\"ru\":\"\\u041c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043a\\u0438\",\"ua\":\"\\u041c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043a\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043a\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043a\\u0438\"}'),
(331,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043e\\u043a\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043e\\u043a\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043e\\u043a\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043e\\u043a\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043e\\u043a\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0456\\u043d\\u0456\\u043c\\u0438\\u0439\\u043e\\u043a\"}'),
(332,	'{\"en\":\"\\u0414\\u0432\\u0438\\u0433\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ru\":\"\\u0414\\u0432\\u0438\\u0433\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ua\":\"\\u0414\\u0432\\u0438\\u0433\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0414\\u0432\\u0438\\u0433\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0414\\u0432\\u0438\\u0433\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0414\\u0432\\u0438\\u0433\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\"}'),
(333,	'{\"en\":\"\\u0414\\u0440\\u043e\\u0432\\u043e\\u0440\\u0443\\u0431\\u0438\",\"ru\":\"\\u0414\\u0440\\u043e\\u0432\\u043e\\u0440\\u0443\\u0431\\u0438\",\"ua\":\"\\u0414\\u0440\\u043e\\u0432\\u043e\\u0440\\u0443\\u0431\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0414\\u0440\\u043e\\u0432\\u043e\\u0440\\u0443\\u0431\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0414\\u0440\\u043e\\u0432\\u043e\\u0440\\u0443\\u0431\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0414\\u0440\\u043e\\u0432\\u043e\\u0440\\u0443\\u0431\\u0438\"}'),
(334,	'{\"en\":\"\\u0410\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0410\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0410\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}'),
(335,	'{\"en\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0440\\u0430\\u0439\\u0434\\u0435\\u0440\\u0438\",\"ru\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0440\\u0430\\u0439\\u0434\\u0435\\u0440\\u0438\",\"ua\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0440\\u0430\\u0439\\u0434\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0440\\u0430\\u0439\\u0434\\u0435\\u0440\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0440\\u0430\\u0439\\u0434\\u0435\\u0440\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0440\\u0430\\u0439\\u0434\\u0435\\u0440\\u0438\"}'),
(336,	'{\"en\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438 (\\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u043e\\u0434\\u0443\\u0432\\u043a\\u0438)\",\"ru\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438 (\\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u043e\\u0434\\u0443\\u0432\\u043a\\u0438)\",\"ua\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438 (\\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u043e\\u0434\\u0443\\u0432\\u043a\\u0438)\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438 (\\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u043e\\u0434\\u0443\\u0432\\u043a\\u0438)\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438 (\\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u043e\\u0434\\u0443\\u0432\\u043a\\u0438)\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438 (\\u043f\\u043e\\u0432\\u0456\\u0442\\u0440\\u043e\\u0434\\u0443\\u0432\\u043a\\u0438)\"}'),
(337,	'{\"en\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u043e\\u0434\\u0440\\u0456\\u0431\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456\"}'),
(338,	'{\"en\":\"\\u0421\\u043d\\u0456\\u0433\\u043e\\u043f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u0447\\u0456\",\"ru\":\"\\u0421\\u043d\\u0456\\u0433\\u043e\\u043f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u0447\\u0456\",\"ua\":\"\\u0421\\u043d\\u0456\\u0433\\u043e\\u043f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u043d\\u0456\\u0433\\u043e\\u043f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u0447\\u0456\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u043d\\u0456\\u0433\\u043e\\u043f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u0447\\u0456\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0421\\u043d\\u0456\\u0433\\u043e\\u043f\\u0440\\u0438\\u0431\\u0438\\u0440\\u0430\\u0447\\u0456\"}'),
(339,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0430\\u0434\\u043e\\u0432\\u043e\\u0457 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\"}'),
(340,	'{\"en\":\"\\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}'),
(341,	'{\"en\":\"\\u0421\\u0435\\u043a\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0443\\u0447\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0441\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\",\"ru\":\"\\u0421\\u0435\\u043a\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0443\\u0447\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0441\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\",\"ua\":\"\\u0421\\u0435\\u043a\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0443\\u0447\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0441\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0435\\u043a\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0443\\u0447\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0441\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0435\\u043a\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0443\\u0447\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0441\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0435\\u043a\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0443\\u0447\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438, \\u0441\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\"}'),
(342,	'{\"en\":\"\\u0413\\u0440\\u0430\\u0431\\u043b\\u0456, \\u043b\\u043e\\u043f\\u0430\\u0442\\u0438, \\u0432\\u0438\\u043b\\u0430\",\"ru\":\"\\u0413\\u0440\\u0430\\u0431\\u043b\\u0456, \\u043b\\u043e\\u043f\\u0430\\u0442\\u0438, \\u0432\\u0438\\u043b\\u0430\",\"ua\":\"\\u0413\\u0440\\u0430\\u0431\\u043b\\u0456, \\u043b\\u043e\\u043f\\u0430\\u0442\\u0438, \\u0432\\u0438\\u043b\\u0430\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0413\\u0440\\u0430\\u0431\\u043b\\u0456, \\u043b\\u043e\\u043f\\u0430\\u0442\\u0438, \\u0432\\u0438\\u043b\\u0430\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0413\\u0440\\u0430\\u0431\\u043b\\u0456, \\u043b\\u043e\\u043f\\u0430\\u0442\\u0438, \\u0432\\u0438\\u043b\\u0430\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0413\\u0440\\u0430\\u0431\\u043b\\u0456, \\u043b\\u043e\\u043f\\u0430\\u0442\\u0438, \\u0432\\u0438\\u043b\\u0430\"}'),
(343,	'{\"en\":\"\\u0421\\u0430\\u043f\\u0438, \\u0440\\u0443\\u0447\\u043d\\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0456\\u0432\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0421\\u0430\\u043f\\u0438, \\u0440\\u0443\\u0447\\u043d\\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0456\\u0432\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0421\\u0430\\u043f\\u0438, \\u0440\\u0443\\u0447\\u043d\\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0456\\u0432\\u0430\\u043b\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0430\\u043f\\u0438, \\u0440\\u0443\\u0447\\u043d\\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0456\\u0432\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0430\\u043f\\u0438, \\u0440\\u0443\\u0447\\u043d\\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0456\\u0432\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0430\\u043f\\u0438, \\u0440\\u0443\\u0447\\u043d\\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0438\\u0432\\u0430\\u0442\\u043e\\u0440\\u0438, \\u0441\\u0456\\u0432\\u0430\\u043b\\u043a\\u0438\"}'),
(344,	'{\"en\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u0438, \\u043d\\u043e\\u0436\\u0456, \\u043a\\u043e\\u0441\\u0438\",\"ru\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u0438, \\u043d\\u043e\\u0436\\u0456, \\u043a\\u043e\\u0441\\u0438\",\"ua\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u0438, \\u043d\\u043e\\u0436\\u0456, \\u043a\\u043e\\u0441\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u0438, \\u043d\\u043e\\u0436\\u0456, \\u043a\\u043e\\u0441\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u0438, \\u043d\\u043e\\u0436\\u0456, \\u043a\\u043e\\u0441\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0441\\u0430\\u0434\\u043e\\u0432\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043f\\u0438\\u043b\\u0438, \\u043d\\u043e\\u0436\\u0456, \\u043a\\u043e\\u0441\\u0438\"}'),
