(358,	'{\"en\":\"\\u041d\\u0430\\u0441\\u0456\\u043d\\u043d\\u044f \\u043e\\u0432\\u043e\\u0447\\u0456\\u0432 \\u0456 \\u0442\\u0440\\u0430\\u0432\",\"ru\":\"\\u041d\\u0430\\u0441\\u0456\\u043d\\u043d\\u044f \\u043e\\u0432\\u043e\\u0447\\u0456\\u0432 \\u0456 \\u0442\\u0440\\u0430\\u0432\",\"ua\":\"\\u041d\\u0430\\u0441\\u0456\\u043d\\u043d\\u044f \\u043e\\u0432\\u043e\\u0447\\u0456\\u0432 \\u0456 \\u0442\\u0440\\u0430\\u0432\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u0456\\u0432\\u043d\\u0438\\u0446\\u0442\\u0432\\u043e, \\u0444\\u0435\\u0440\\u043c\\u0435\\u0440\\u0441\\u0442\\u0432\\u043e > \\u041d\\u0430\\u0441\\u0456\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0441\\u0456\\u043d\\u043d\\u044f \\u043e\\u0432\\u043e\\u0447\\u0456\\u0432 \\u0456 \\u0442\\u0440\\u0430\\u0432\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u0456\\u0432\\u043d\\u0438\\u0446\\u0442\\u0432\\u043e, \\u0444\\u0435\\u0440\\u043c\\u0435\\u0440\\u0441\\u0442\\u0432\\u043e > \\u041d\\u0430\\u0441\\u0456\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0441\\u0456\\u043d\\u043d\\u044f \\u043e\\u0432\\u043e\\u0447\\u0456\\u0432 \\u0456 \\u0442\\u0440\\u0430\\u0432\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u0456\\u0432\\u043d\\u0438\\u0446\\u0442\\u0432\\u043e, \\u0444\\u0435\\u0440\\u043c\\u0435\\u0440\\u0441\\u0442\\u0432\\u043e > \\u041d\\u0430\\u0441\\u0456\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0441\\u0456\\u043d\\u043d\\u044f \\u043e\\u0432\\u043e\\u0447\\u0456\\u0432 \\u0456 \\u0442\\u0440\\u0430\\u0432\"}'),
