(375,	'{\"en\":\"\\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\"}'),
(376,	'{\"en\":\"\\u0413\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0413\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0413\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0413\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0413\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0413\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}'),
(377,	'{\"en\":\"\\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f\",\"ru\":\"\\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f\",\"ua\":\"\\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f\"}'),
(378,	'{\"en\":\"\\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u043d\\u0430 \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u044f\\u0445\",\"ru\":\"\\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u043d\\u0430 \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u044f\\u0445\",\"ua\":\"\\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u043d\\u0430 \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u044f\\u0445\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u043d\\u0430 \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u044f\\u0445\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u043d\\u0430 \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u044f\\u0445\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u043d\\u0430 \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u044f\\u0445\"}'),
(379,	'{\"en\":\"\\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043b\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0433\\u0435\\u043b\\u0456\\u043e\\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ru\":\"\\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043b\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0433\\u0435\\u043b\\u0456\\u043e\\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ua\":\"\\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043b\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0433\\u0435\\u043b\\u0456\\u043e\\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043b\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0433\\u0435\\u043b\\u0456\\u043e\\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043b\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0433\\u0435\\u043b\\u0456\\u043e\\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043b\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438, \\u0433\\u0435\\u043b\\u0456\\u043e\\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438\"}'),
(380,	'{\"en\":\"\\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043f\\u0430\\u043d\\u0435\\u043b\\u0456 (\\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0457), \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457\",\"ru\":\"\\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043f\\u0430\\u043d\\u0435\\u043b\\u0456 (\\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0457), \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457\",\"ua\":\"\\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043f\\u0430\\u043d\\u0435\\u043b\\u0456 (\\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0457), \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043f\\u0430\\u043d\\u0435\\u043b\\u0456 (\\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0457), \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043f\\u0430\\u043d\\u0435\\u043b\\u0456 (\\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0457), \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0421\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043f\\u0430\\u043d\\u0435\\u043b\\u0456 (\\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0457), \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u0457\"}'),
(381,	'{\"en\":\"\\u0406\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\",\"ru\":\"\\u0406\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\",\"ua\":\"\\u0406\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0406\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0406\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0406\\u043d\\u0432\\u0435\\u0440\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0438\\u0445 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\"}'),
(382,	'{\"en\":\"\\u0412\\u0456\\u0442\\u0440\\u043e-\\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438\",\"ru\":\"\\u0412\\u0456\\u0442\\u0440\\u043e-\\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438\",\"ua\":\"\\u0412\\u0456\\u0442\\u0440\\u043e-\\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0412\\u0456\\u0442\\u0440\\u043e-\\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0412\\u0456\\u0442\\u0440\\u043e-\\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0412\\u0456\\u0442\\u0440\\u043e-\\u0441\\u043e\\u043d\\u044f\\u0447\\u043d\\u0456 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438\"}'),
(383,	'{\"en\":\"\\u0412\\u0456\\u0442\\u0440\\u043e\\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0412\\u0456\\u0442\\u0440\\u043e\\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0412\\u0456\\u0442\\u0440\\u043e\\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0412\\u0456\\u0442\\u0440\\u043e\\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0412\\u0456\\u0442\\u0440\\u043e\\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0414\\u0430\\u0447\\u043d\\u0435 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430 \\u0435\\u043d\\u0435\\u0440\\u0433\\u0456\\u044f > \\u0412\\u0456\\u0442\\u0440\\u043e\\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}'),
(384,	'{\"en\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440\",\"ru\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440\",\"ua\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440\"}'),
(385,	'{\"en\":\"\\u0411\\u0430\\u0441\\u0435\\u0439\\u043d\\u0438 \\u043d\\u0430\\u0434\\u0443\\u0432\\u043d\\u0456, \\u043a\\u0430\\u0440\\u043a\\u0430\\u0441\\u043d\\u0456\",\"ru\":\"\\u0411\\u0430\\u0441\\u0435\\u0439\\u043d\\u0438 \\u043d\\u0430\\u0434\\u0443\\u0432\\u043d\\u0456, \\u043a\\u0430\\u0440\\u043a\\u0430\\u0441\\u043d\\u0456\",\"ua\":\"\\u0411\\u0430\\u0441\\u0435\\u0439\\u043d\\u0438 \\u043d\\u0430\\u0434\\u0443\\u0432\\u043d\\u0456, \\u043a\\u0430\\u0440\\u043a\\u0430\\u0441\\u043d\\u0456\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0411\\u0430\\u0441\\u0435\\u0439\\u043d\\u0438 \\u043d\\u0430\\u0434\\u0443\\u0432\\u043d\\u0456, \\u043a\\u0430\\u0440\\u043a\\u0430\\u0441\\u043d\\u0456\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0411\\u0430\\u0441\\u0435\\u0439\\u043d\\u0438 \\u043d\\u0430\\u0434\\u0443\\u0432\\u043d\\u0456, \\u043a\\u0430\\u0440\\u043a\\u0430\\u0441\\u043d\\u0456\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0411\\u0430\\u0441\\u0435\\u0439\\u043d\\u0438 \\u043d\\u0430\\u0434\\u0443\\u0432\\u043d\\u0456, \\u043a\\u0430\\u0440\\u043a\\u0430\\u0441\\u043d\\u0456\"}'),
(386,	'{\"en\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ru\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ua\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\"}'),
(387,	'{\"en\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\"}'),
