(389,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0441\\u0435\\u0439\\u043d\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0441\\u0435\\u0439\\u043d\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0441\\u0435\\u0439\\u043d\\u0456\\u0432\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0441\\u0435\\u0439\\u043d\\u0456\\u0432\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0441\\u0435\\u0439\\u043d\\u0456\\u0432\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0441\\u0435\\u0439\\u043d\\u0456\\u0432\"}'),
(390,	'{\"en\":\"\\u0414\\u0435\\u0437\\u0456\\u043d\\u0444\\u0456\\u043a\\u0443\\u044e\\u0447\\u0456 \\u0456 \\u043e\\u0447\\u0438\\u0441\\u043d\\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0441\\u0435\\u0439\\u043d\\u0456\\u0432\",\"ru\":\"\\u0414\\u0435\\u0437\\u0456\\u043d\\u0444\\u0456\\u043a\\u0443\\u044e\\u0447\\u0456 \\u0456 \\u043e\\u0447\\u0438\\u0441\\u043d\\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0441\\u0435\\u0439\\u043d\\u0456\\u0432\",\"ua\":\"\\u0414\\u0435\\u0437\\u0456\\u043d\\u0444\\u0456\\u043a\\u0443\\u044e\\u0447\\u0456 \\u0456 \\u043e\\u0447\\u0438\\u0441\\u043d\\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0441\\u0435\\u0439\\u043d\\u0456\\u0432\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0414\\u0435\\u0437\\u0456\\u043d\\u0444\\u0456\\u043a\\u0443\\u044e\\u0447\\u0456 \\u0456 \\u043e\\u0447\\u0438\\u0441\\u043d\\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0441\\u0435\\u0439\\u043d\\u0456\\u0432\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0414\\u0435\\u0437\\u0456\\u043d\\u0444\\u0456\\u043a\\u0443\\u044e\\u0447\\u0456 \\u0456 \\u043e\\u0447\\u0438\\u0441\\u043d\\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0441\\u0435\\u0439\\u043d\\u0456\\u0432\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0414\\u0435\\u0437\\u0456\\u043d\\u0444\\u0456\\u043a\\u0443\\u044e\\u0447\\u0456 \\u0456 \\u043e\\u0447\\u0438\\u