(391,	'{\"en\":\"\\u0412\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0412\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0412\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u0412\\u0443\\u043b\\u0438\\u0447\\u043d\\u0456 \\u0441\\u0432\\u0456\\u0442\\u0438\\u043b\\u044c\\u043d\\u0438\\u043a\\u0438\"}'),
(392,	'{\"en\":\"\\u041f\\u0430\\u0441\\u0442\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043b\\u044f\\u043a\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u041f\\u0430\\u0441\\u0442\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043b\\u044f\\u043a\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u041f\\u0430\\u0441\\u0442\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043b\\u044f\\u043a\\u0443\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u041f\\u0430\\u0441\\u0442\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043b\\u044f\\u043a\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u041f\\u0430\\u0441\\u0442\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043b\\u044f\\u043a\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0414\\u0430\\u0447\\u0430, \\u0441\\u0430\\u0434 > \\u0421\\u0430\\u0434\\u043e\\u0432\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456, \\u0434\\u0435\\u043a\\u043e\\u0440 > \\u041f\\u0430\\u0441\\u0442\\u043a\\u0438, \\u0432\\u0456\\u0434\\u043b\\u044f\\u043a\\u0443\\u0432\\u0430\\u0447\\u0456\"}'),
(393,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\"}'),
(394,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u043a\\u0440\\u0456\\u0441\\u043b\\u0430 \\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u043a\\u0440\\u0456\\u0441\\u043b\\u0430 \\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u043a\\u0440\\u0456\\u0441\\u043b\\u0430 \\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u0440\\u0456\\u0441\\u043b\\u0430 \\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u0440\\u0456\\u0441\\u043b\\u0430 \\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u0440\\u0456\\u0441\\u043b\\u0430 \\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\"}'),
