(402,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043b\\u044f\\u0441\\u043e\\u043a\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043b\\u044f\\u0441\\u043e\\u043a\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043b\\u044f\\u0441\\u043e\\u043a\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u0440\\u0456\\u0441\\u043b\\u0430 \\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043b\\u044f\\u0441\\u043e\\u043a > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043b\\u044f\\u0441\\u043e\\u043a\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u0440\\u0456\\u0441\\u043b\\u0430 \\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043b\\u044f\\u0441\\u043e\\u043a > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043b\\u044f\\u0441\\u043e\\u043a\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043a\\u0440\\u0456\\u0441\\u043b\\u0430 \\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043b\\u044f\\u0441\\u043e\\u043a > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043b\\u044f\\u0441\\u043e\\u043a\"}'),
(403,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\"}'),
(404,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u043e\\u0440\\u0438\"}'),
(405,	'{\"en\":\"\\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u0436\\u0456 \\u043c\\u0443\\u043b\\u044c\\u0442\\u0444\\u0456\\u043b\\u044c\\u043c\\u0456\\u0432, \\u0456\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\",\"ru\":\"\\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u0436\\u0456 \\u043c\\u0443\\u043b\\u044c\\u0442\\u0444\\u0456\\u043b\\u044c\\u043c\\u0456\\u0432, \\u0456\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\",\"ua\":\"\\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u0436\\u0456 \\u043c\\u0443\\u043b\\u044c\\u0442\\u0444\\u0456\\u043b\\u044c\\u043c\\u0456\\u0432, \\u0456\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u0436\\u0456 \\u043c\\u0443\\u043b\\u044c\\u0442\\u0444\\u0456\\u043b\\u044c\\u043c\\u0456\\u0432, \\u0456\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u0436\\u0456 \\u043c\\u0443\\u043b\\u044c\\u0442\\u0444\\u0456\\u043b\\u044c\\u043c\\u0456\\u0432, \\u0456\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u0436\\u0456 \\u043c\\u0443\\u043b\\u044c\\u0442\\u0444\\u0456\\u043b\\u044c\\u043c\\u0456\\u0432, \\u0456\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0444\\u0456\\u0433\\u0443\\u0440\\u043a\\u0438\"}'),
(406,	'{\"en\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ru\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ua\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\"}'),
(407,	'{\"en\":\"\\u0406\\u043d\\u0442\\u0435\\u0440\\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438, \\u0440\\u043e\\u0431\\u043e\\u0442\\u0438\",\"ru\":\"\\u0406\\u043d\\u0442\\u0435\\u0440\\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438, \\u0440\\u043e\\u0431\\u043e\\u0442\\u0438\",\"ua\":\"\\u0406\\u043d\\u0442\\u0435\\u0440\\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438, \\u0440\\u043e\\u0431\\u043e\\u0442\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u043d\\u0442\\u0435\\u0440\\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438, \\u0440\\u043e\\u0431\\u043e\\u0442\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u043d\\u0442\\u0435\\u0440\\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438, \\u0440\\u043e\\u0431\\u043e\\u0442\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u043d\\u0442\\u0435\\u0440\\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438, \\u0440\\u043e\\u0431\\u043e\\u0442\\u0438\"}'),
(408,	'{\"en\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ru\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ua\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\"}'),
(409,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u043f\\u043e\\u0440\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u043f\\u043e\\u0440\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u043f\\u043e\\u0440\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u043f\\u043e\\u0440\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u043f\\u043e\\u0440\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u043f\\u043e\\u0440\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\"}'),
(410,	'{\"en\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438-\\u0430\\u043d\\u0442\\u0438\\u0441\\u0442\\u0440\\u0435\\u0441, \\u0441\\u043f\\u0456\\u043d\\u043d\\u0435\\u0440\\u0438\",\"ru\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438-\\u0430\\u043d\\u0442\\u0438\\u0441\\u0442\\u0440\\u0435\\u0441, \\u0441\\u043f\\u0456\\u043d\\u043d\\u0435\\u0440\\u0438\",\"ua\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438-\\u0430\\u043d\\u0442\\u0438\\u0441\\u0442\\u0440\\u0435\\u0441, \\u0441\\u043f\\u0456\\u043d\\u043d\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438-\\u0430\\u043d\\u0442\\u0438\\u0441\\u0442\\u0440\\u0435\\u0441, \\u0441\\u043f\\u0456\\u043d\\u043d\\u0435\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438-\\u0430\\u043d\\u0442\\u0438\\u0441\\u0442\\u0440\\u0435\\u0441, \\u0441\\u043f\\u0456\\u043d\\u043d\\u0435\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438-\\u0430\\u043d\\u0442\\u0438\\u0441\\u0442\\u0440\\u0435\\u0441, \\u0441\\u043f\\u0456\\u043d\\u043d\\u0435\\u0440\\u0438\"}'),
(411,	'{\"en\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c\",\"ru\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c\",\"ua\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c\"}'),
(412,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u0456\\u0433\\u0440\\u0438\"}'),
(413,	'{\"en\":\"\\u041f\\u0430\\u0437\\u043b\\u0438\",\"ru\":\"\\u041f\\u0430\\u0437\\u043b\\u0438\",\"ua\":\"\\u041f\\u0430\\u0437\\u043b\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u041f\\u0430\\u0437\\u043b\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u041f\\u0430\\u0437\\u043b\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u041f\\u0430\\u0437\\u043b\\u0438\"}'),
(414,	'{\"en\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u043e\\u0440\\u0447\\u043e\\u0441\\u0442\\u0456 \\u0456 \\u0440\\u0443\\u043a\\u043e\\u0434\\u0456\\u043b\\u043b\\u044f\",\"ru\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u043e\\u0440\\u0447\\u043e\\u0441\\u0442\\u0456 \\u0456 \\u0440\\u0443\\u043a\\u043e\\u0434\\u0456\\u043b\\u043b\\u044f\",\"ua\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u043e\\u0440\\u0447\\u043e\\u0441\\u0442\\u0456 \\u0456 \\u0440\\u0443\\u043a\\u043e\\u0434\\u0456\\u043b\\u043b\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u043e\\u0440\\u0447\\u043e\\u0441\\u0442\\u0456 \\u0456 \\u0440\\u0443\\u043a\\u043e\\u0434\\u0456\\u043b\\u043b\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u043e\\u0440\\u0447\\u043e\\u0441\\u0442\\u0456 \\u0456 \\u0440\\u0443\\u043a\\u043e\\u0434\\u0456\\u043b\\u043b\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u043e\\u0440\\u0447\\u043e\\u0441\\u0442\\u0456 \\u0456 \\u0440\\u0443\\u043a\\u043e\\u0434\\u0456\\u043b\\u043b\\u044f\"}'),
(415,	'{\"en\":\"\\u041d\\u0430\\u0443\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0438, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0438\",\"ru\":\"\\u041d\\u0430\\u0443\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0438, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0438\",\"ua\":\"\\u041d\\u0430\\u0443\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0438, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u041d\\u0430\\u0443\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0438, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u041d\\u0430\\u0443\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0438, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u041d\\u0430\\u0443\\u043a\\u043e\\u0432\\u0456 \\u0456\\u0433\\u0440\\u0438, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u0438\"}'),
(416,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a, \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\"}'),
(417,	'{\"en\":\"\\u041b\\u044f\\u043b\\u044c\\u043a\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u044f\\u043b\\u044c\\u043e\\u043a\",\"ru\":\"\\u041b\\u044f\\u043b\\u044c\\u043a\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u044f\\u043b\\u044c\\u043e\\u043a\",\"ua\":\"\\u041b\\u044f\\u043b\\u044c\\u043a\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u044f\\u043b\\u044c\\u043e\\u043a\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041b\\u044f\\u043b\\u044c\\u043a\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u044f\\u043b\\u044c\\u043e\\u043a\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041b\\u044f\\u043b\\u044c\\u043a\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u044f\\u043b\\u044c\\u043e\\u043a\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041b\\u044f\\u043b\\u044c\\u043a\\u0438, \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u044f\\u043b\\u044c\\u043e\\u043a\"}'),
(418,	'{\"en\":\"\\u041c\'\\u044f\\u043a\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ru\":\"\\u041c\'\\u044f\\u043a\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ua\":\"\\u041c\'\\u044f\\u043a\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\'\\u044f\\u043a\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\'\\u044f\\u043a\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\'\\u044f\\u043a\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\"}'),
(419,	'{\"en\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0430 \\u0437\\u0431\\u0440\\u043e\\u044f\",\"ru\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0430 \\u0437\\u0431\\u0440\\u043e\\u044f\",\"ua\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0430 \\u0437\\u0431\\u0440\\u043e\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0430 \\u0437\\u0431\\u0440\\u043e\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0430 \\u0437\\u0431\\u0440\\u043e\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0430 \\u0437\\u0431\\u0440\\u043e\\u044f\"}'),
(420,	'{\"en\":\"\\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ru\":\"\\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ua\":\"\\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\"}'),
(421,	'{\"en\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ru\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ua\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430\"}'),
(422,	'{\"en\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043a\\u0438, \\u0433\\u0430\\u0440\\u0430\\u0436\\u0456, \\u043f\\u0430\\u0440\\u043a\\u0456\\u043d\\u0433\\u0438\",\"ru\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043a\\u0438, \\u0433\\u0430\\u0440\\u0430\\u0436\\u0456, \\u043f\\u0430\\u0440\\u043a\\u0456\\u043d\\u0433\\u0438\",\"ua\":\"\\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043a\\u0438, \\u0433\\u0430\\u0440\\u0430\\u0436\\u0456, \\u043f\\u0430\\u0440\\u043a\\u0456\\u043d\\u0433\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043a\\u0438, \\u0433\\u0430\\u0440\\u0430\\u0436\\u0456, \\u043f\\u0430\\u0440\\u043a\\u0456\\u043d\\u0433\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043a\\u0438, \\u0433\\u0430\\u0440\\u0430\\u0436\\u0456, \\u043f\\u0430\\u0440\\u043a\\u0456\\u043d\\u0433\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0410\\u0432\\u0442\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u044c\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043a\\u0438, \\u0433\\u0430\\u0440\\u0430\\u0436\\u0456, \\u043f\\u0430\\u0440\\u043a\\u0456\\u043d\\u0433\\u0438\"}'),
(423,	'{\"en\":\"\\u0417\\u0430\\u043b\\u0456\\u0437\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u0417\\u0430\\u043b\\u0456\\u0437\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u0417\\u0430\\u043b\\u0456\\u0437\\u043d\\u0438\\u0446\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0417\\u0430\\u043b\\u0456\\u0437\\u043d\\u0438\\u0446\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0417\\u0430\\u043b\\u0456\\u0437\\u043d\\u0438\\u0446\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0417\\u0430\\u043b\\u0456\\u0437\\u043d\\u0438\\u0446\\u0456\"}'),
(424,	'{\"en\":\"\\u041c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\",\"ru\":\"\\u041c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\",\"ua\":\"\\u041c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u041c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u041c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u041c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\"}'),
(425,	'{\"en\":\"\\u0420\\u0430\\u0434\\u0456\\u043e\\u043a\\u0435\\u0440\\u043e\\u0432\\u0430\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456, \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ru\":\"\\u0420\\u0430\\u0434\\u0456\\u043e\\u043a\\u0435\\u0440\\u043e\\u0432\\u0430\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456, \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ua\":\"\\u0420\\u0430\\u0434\\u0456\\u043e\\u043a\\u0435\\u0440\\u043e\\u0432\\u0430\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456, \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0420\\u0430\\u0434\\u0456\\u043e\\u043a\\u0435\\u0440\\u043e\\u0432\\u0430\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456, \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0420\\u0430\\u0434\\u0456\\u043e\\u043a\\u0435\\u0440\\u043e\\u0432\\u0430\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456, \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u042