(426,	'{\"en\":\"\\u0417\\u0431\\u0456\\u0440\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\",\"ru\":\"\\u0417\\u0431\\u0456\\u0440\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\",\"ua\":\"\\u0417\\u0431\\u0456\\u0440\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0417\\u0431\\u0456\\u0440\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0417\\u0431\\u0456\\u0440\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0417\\u0431\\u0456\\u0440\\u043d\\u0456 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456\"}'),
(427,	'{\"en\":\"\\u0422\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440\\u0438\",\"ru\":\"\\u0422\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440\\u0438\",\"ua\":\"\\u0422\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0422\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0422\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u041c\\u0430\\u0448\\u0438\\u043d\\u043a\\u0438, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0456 \\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438 > \\u0422\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440\\u0438\"}'),
(428,	'{\"en\":\"\\u0413\\u043e\\u043b\\u043e\\u0432\\u043e\\u043b\\u043e\\u043c\\u043a\\u0438\",\"ru\":\"\\u0413\\u043e\\u043b\\u043e\\u0432\\u043e\\u043b\\u043e\\u043c\\u043a\\u0438\",\"ua\":\"\\u0413\\u043e\\u043b\\u043e\\u0432\\u043e\\u043b\\u043e\\u043c\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0413\\u043e\\u043b\\u043e\\u0432\\u043e\\u043b\\u043e\\u043c\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0413\\u043e\\u043b\\u043e\\u0432\\u043e\\u043b\\u043e\\u043c\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 > \\u0413\\u043e\\u043b\\u043e\\u0432\\u043e\\u043b\\u043e\\u043c\\u043a\\u0438\"}'),
(429,	'{\"en\":\"\\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\",\"ru\":\"\\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\",\"ua\":\"\\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\"}'),
(430,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u043d\\u0430\\u0442\\u0430\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u043d\\u0430\\u0442\\u0430\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u043d\\u0430\\u0442\\u0430\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u043d\\u0430\\u0442\\u0430\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u043d\\u0430\\u0442\\u0430\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u043d\\u0430\\u0442\\u0430\"}'),
(431,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043f\\u043e\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0430 \\u0431\\u0456\\u043b\\u0438\\u0437\\u043d\\u0430 \\u0442\\u0430 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043f\\u043e\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0430 \\u0431\\u0456\\u043b\\u0438\\u0437\\u043d\\u0430 \\u0442\\u0430 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043f\\u043e\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0430 \\u0431\\u0456\\u043b\\u0438\\u0437\\u043d\\u0430 \\u0442\\u0430 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u043d\\u0430\\u0442\\u0430 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043f\\u043e\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0430 \\u0431\\u0456\\u043b\\u0438\\u0437\\u043d\\u0430 \\u0442\\u0430 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u043d\\u0430\\u0442\\u0430 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043f\\u043e\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0430 \\u0431\\u0456\\u043b\\u0438\\u0437\\u043d\\u0430 \\u0442\\u0430 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u