(432,	'{\"en\":\"\\u041d\\u0456\\u0447\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u041d\\u0456\\u0447\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u041d\\u0456\\u0447\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u043d\\u0430\\u0442\\u0430 > \\u041d\\u0456\\u0447\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u043d\\u0430\\u0442\\u0430 > \\u041d\\u0456\\u0447\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u043a\\u0456\\u043c\\u043d\\u0430\\u0442\\u0430 > \\u041d\\u0456\\u0447\\u043d\\u0438\\u043a\\u0438\"}'),
(433,	'{\"en\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(434,	'{\"en\":\"\\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438 \\u0456 \\u0442\\u0440\\u0443\\u0441\\u0438\\u043a\\u0438\",\"ru\":\"\\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438 \\u0456 \\u0442\\u0440\\u0443\\u0441\\u0438\\u043a\\u0438\",\"ua\":\"\\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438 \\u0456 \\u0442\\u0440\\u0443\\u0441\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438 \\u0456 \\u0442\\u0440\\u0443\\u0441\\u0438\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438 \\u0456 \\u0442\\u0440\\u0443\\u0441\\u0438\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438 \\u0456 \\u0442\\u0440\\u0443\\u0441\\u0438\\u043a\\u0438\"}'),
(435,	'{\"en\":\"\\u0412\\u0430\\u043d\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u043f\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0412\\u0430\\u043d\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u043f\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0412\\u0430\\u043d\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u043f\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0412\\u0430\\u043d\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u043f\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0412\\u0430\\u043d\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u043f\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0412\\u0430\\u043d\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043a\\u0443\\u043f\\u0430\\u043d\\u043d\\u044f\"}'),
(436,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0435 \\u0445\\u0430\\u0440\\u0447\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0435 \\u0445\\u0430\\u0440\\u0447\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0435 \\u0445\\u0430\\u0440\\u0447\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0435 \\u0445\\u0430\\u0440\\u0447\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0435 \\u0445\\u0430\\u0440\\u0447\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0435 \\u0445\\u0430\\u0440\\u0447\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(437,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0440\\u0449\\u0438\\u043a\\u0438 \\u0456 \\u0441\\u0438\\u0434\\u0456\\u043d\\u043d\\u044f\"}'),
(438,	'{\"en\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 \\u0437\\u0430 \\u043c\\u0430\\u043b\\u044e\\u043a\\u043e\\u043c\",\"ru\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 \\u0437\\u0430 \\u043c\\u0430\\u043b\\u044e\\u043a\\u043e\\u043c\",\"ua\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 \\u0437\\u0430 \\u043c\\u0430\\u043b\\u044e\\u043a\\u043e\\u043c\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 \\u0437\\u0430 \\u043c\\u0430\\u043b\\u044e\\u043a\\u043e\\u043c\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 \\u0437\\u0430 \\u043c\\u0430\\u043b\\u044e\\u043a\\u043e\\u043c\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 \\u0437\\u0430 \\u043c\\u0430\\u043b\\u044e\\u043a\\u043e\\u043c\"}'),
(439,	'{\"en\":\"\\u041f\\u0443\\u0441\\u0442\\u0443\\u0448\\u043a\\u0438\",\"ru\":\"\\u041f\\u0443\\u0441\\u0442\\u0443\\u0448\\u043a\\u0438\",\"ua\":\"\\u041f\\u0443\\u0441\\u0442\\u0443\\u0448\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0443\\u0441\\u0442\\u0443\\u0448\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0443\\u0441\\u0442\\u0443\\u0448\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434, \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430, \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0443\\u0441\\u0442\\u0443\\u0448\\u043a\\u0438\"}'),
(440,	'{\"en\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438\",\"ru\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438\",\"ua\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438\"}'),
(441,	'{\"en\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\",\"ru\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\",\"ua\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u0456\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432\"}'),
(442,	'{\"en\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\",\"ru\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\",\"ua\":\"\\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0432\\u0430\\u044e\\u0447\\u0456 \\u043a\\u0438\\u043b\\u0438\\u043c\\u043a\\u0438\"}'),
(443,	'{\"en\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u043a\\u0430\\u0440\\u0443\\u0441\\u0435\\u043b\\u0456, \\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ru\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u043a\\u0430\\u0440\\u0443\\u0441\\u0435\\u043b\\u0456, \\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ua\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u043a\\u0430\\u0440\\u0443\\u0441\\u0435\\u043b\\u0456, \\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u043a\\u0430\\u0440\\u0443\\u0441\\u0435\\u043b\\u0456, \\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u043a\\u0430\\u0440\\u0443\\u0441\\u0435\\u043b\\u0456, \\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u043a\\u0430\\u0440\\u0443\\u0441\\u0435\\u043b\\u0456, \\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\"}'),
(444,	'{\"en\":\"\\u0411\\u0440\\u044f\\u0437\\u043a\\u0430\\u043b\\u044c\\u0446\\u044f, \\u043f\\u0456\\u0434\\u0432\\u0456\\u0441\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0440\\u0456\\u0437\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0411\\u0440\\u044f\\u0437\\u043a\\u0430\\u043b\\u044c\\u0446\\u044f, \\u043f\\u0456\\u0434\\u0432\\u0456\\u0441\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0440\\u0456\\u0437\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0411\\u0440\\u044f\\u0437\\u043a\\u0430\\u043b\\u044c\\u0446\\u044f, \\u043f\\u0456\\u0434\\u0432\\u0456\\u0441\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0440\\u0456\\u0437\\u0443\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0411\\u0440\\u044f\\u0437\\u043a\\u0430\\u043b\\u044c\\u0446\\u044f, \\u043f\\u0456\\u0434\\u0432\\u0456\\u0441\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0440\\u0456\\u0437\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0411\\u0440\\u044f\\u0437\\u043a\\u0430\\u043b\\u044c\\u0446\\u044f, \\u043f\\u0456\\u0434\\u0432\\u0456\\u0441\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0440\\u0456\\u0437\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0411\\u0440\\u044f\\u0437\\u043a\\u0430\\u043b\\u044c\\u0446\\u044f, \\u043f\\u0456\\u0434\\u0432\\u0456\\u0441\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0440\\u0456\\u0437\\u0443\\u0432\\u0430\\u0447\\u0456\"}'),
(445,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430-\\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430-\\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430-\\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430-\\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430-\\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u0440\\u0456\\u0441\\u043b\\u0430-\\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\"}'),
(446,	'{\"en\":\"\\u0425\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u0441\\u0442\\u0440\\u0438\\u0431\\u0443\\u043d\\u0438\",\"ru\":\"\\u0425\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u0441\\u0442\\u0440\\u0438\\u0431\\u0443\\u043d\\u0438\",\"ua\":\"\\u0425\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u0441\\u0442\\u0440\\u0438\\u0431\\u0443\\u043d\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0425\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u0441\\u0442\\u0440\\u0438\\u0431\\u0443\\u043d\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0425\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u0441\\u0442\\u0440\\u0438\\u0431\\u0443\\u043d\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u043a\\u0456\\u0432 > \\u0420\\u043e\\u0437\\u0432\\u0438\\u0442\\u043e\\u043a \\u0456 \\u0440\\u043e\\u0437\\u0432\\u0430\\u0433\\u0438 > \\u0425\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u0441\\u0442\\u0440\\u0438\\u0431\\u0443\\u043d\\u0438\"}'),
(447,	'{\"en\":\"\\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a\",\"ru\":\"\\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a\",\"ua\":\"\\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a\"}'),
(448,	'{\"en\":\"\\u0421\\u0430\\u043d\\u043a\\u0438\",\"ru\":\"\\u0421\\u0430\\u043d\\u043a\\u0438\",\"ua\":\"\\u0421\\u0430\\u043d\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u0430\\u043d\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u0430\\u043d\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u0430\\u043d\\u043a\\u0438\"}'),
(449,	'{\"en\":\"\\u0421\\u043d\\u0456\\u0436\\u043a\\u043e\\u043b\\u0456\\u043f\\u0438\",\"ru\":\"\\u0421\\u043d\\u0456\\u0436\\u043a\\u043e\\u043b\\u0456\\u043f\\u0438\",\"ua\":\"\\u0421\\u043d\\u0456\\u0436\\u043a\\u043e\\u043b\\u0456\\u043f\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043d\\u0456\\u0436\\u043a\\u043e\\u043b\\u0456\\u043f\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043d\\u0456\\u0436\\u043a\\u043e\\u043b\\u0456\\u043f\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043d\\u0456\\u0436\\u043a\\u043e\\u043b\\u0456\\u043f\\u0438\"}'),
(450,	'{\"en\":\"\\u041b\\u0438\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043d\\u0430\\u0439\\u043c\\u0435\\u043d\\u0448\\u0438\\u0445\",\"ru\":\"\\u041b\\u0438\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043d\\u0430\\u0439\\u043c\\u0435\\u043d\\u0448\\u0438\\u0445\",\"ua\":\"\\u041b\\u0438\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043d\\u0430\\u0439\\u043c\\u0435\\u043d\\u0448\\u0438\\u0445\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041b\\u0438\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043d\\u0430\\u0439\\u043c\\u0435\\u043d\\u0448\\u0438\\u0445\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041b\\u0438\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043d\\u0430\\u0439\\u043c\\u0435\\u043d\\u0448\\u0438\\u0445\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041b\\u0438\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043d\\u0430\\u0439\\u043c\\u0435\\u043d\\u0448\\u0438\\u0445\"}'),
(451,	'{\"en\":\"\\u0422\\u043e\\u043b\\u043e\\u043a\\u0430\\u0440\\u0438, \\u043a\\u0430\\u0447\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0422\\u043e\\u043b\\u043e\\u043a\\u0430\\u0440\\u0438, \\u043a\\u0430\\u0447\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0422\\u043e\\u043b\\u043e\\u043a\\u0430\\u0440\\u0438, \\u043a\\u0430\\u0447\\u0430\\u043b\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0422\\u043e\\u043b\\u043e\\u043a\\u0430\\u0440\\u0438, \\u043a\\u0430\\u0447\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0422\\u043e\\u043b\\u043e\\u043a\\u0430\\u0440\\u0438, \\u043a\\u0430\\u0447\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0422\\u043e\\u043b\\u043e\\u043a\\u0430\\u0440\\u0438, \\u043a\\u0430\\u0447\\u0430\\u043b\\u043a\\u0438\"}'),
(452,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e-\\u0442\\u0430 \\u0432\\u0435\\u043b\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e-\\u0442\\u0430 \\u0432\\u0435\\u043b\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e-\\u0442\\u0430 \\u0432\\u0435\\u043b\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e-\\u0442\\u0430 \\u0432\\u0435\\u043b\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e-\\u0442\\u0430 \\u0432\\u0435\\u043b\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e-\\u0442\\u0430 \\u0432\\u0435\\u043b\\u043e\\u043c\\u043e\\u0431\\u0456\\u043b\\u0456\"}'),
(453,	'{\"en\":\"\\u0421\\u043a\\u0435\\u0439\\u0442\\u0431\\u043e\\u0440\\u0434\\u0438\",\"ru\":\"\\u0421\\u043a\\u0435\\u0439\\u0442\\u0431\\u043e\\u0440\\u0434\\u0438\",\"ua\":\"\\u0421\\u043a\\u0435\\u0439\\u0442\\u0431\\u043e\\u0440\\u0434\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043a\\u0435\\u0439\\u0442\\u0431\\u043e\\u0440\\u0434\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043a\\u0435\\u0439\\u0442\\u0431\\u043e\\u0440\\u0434\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043a\\u0435\\u0439\\u0442\\u0431\\u043e\\u0440\\u0434\\u0438\"}'),
(454,	'{\"en\":\"\\u0421\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0438\",\"ru\":\"\\u0421\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0438\",\"ua\":\"\\u0421\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0438\"}'),
(455,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043b\\u0435\\u0441\\u0430 \\u0434\\u043b\\u044f \\u0441\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043b\\u0435\\u0441\\u0430 \\u0434\\u043b\\u044f \\u0441\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043b\\u0435\\u0441\\u0430 \\u0434\\u043b\\u044f \\u0441\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043b\\u0435\\u0441\\u0430 \\u0434\\u043b\\u044f \\u0441\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0456\\u0432\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043b\\u0435\\u0441\\u0430 \\u0434\\u043b\\u044f \\u0441\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0456\\u0432\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u043a\\u043e\\u043b\\u0435\\u0441\\u0430 \\u0434\\u043b\\u044f \\u0441\\u0430\\u043c\\u043e\\u043a\\u0430\\u0442\\u0456\\u0432\"}'),
(456,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0432\\u0435\\u043b\\u043e\\u0441\\u0438\\u043f\\u0435\\u0434\\u0438\"}'),
(457,	'{\"en\":\"\\u0411\\u0456\\u0433\\u043e\\u0432\\u0435\\u043b\\u0438\",\"ru\":\"\\u0411\\u0456\\u0433\\u043e\\u0432\\u0435\\u043b\\u0438\",\"ua\":\"\\u0411\\u0456\\u0433\\u043e\\u0432\\u0435\\u043b\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0456\\u0433\\u043e\\u0432\\u0435\\u043b\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0456\\u0433\\u043e\\u0432\\u0435\\u043b\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0411\\u0456\\u0433\\u043e\\u0432\\u0435\\u043b\\u0438\"}'),
(458,	'{\"en\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438\",\"ru\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438\",\"ua\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438\"}'),
(459,	'{\"en\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438, \\u043d\\u0430\\u043c\\u0435\\u0442\\u0438\",\"ru\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438, \\u043d\\u0430\\u043c\\u0435\\u0442\\u0438\",\"ua\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438, \\u043d\\u0430\\u043c\\u0435\\u0442\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438, \\u043d\\u0430\\u043c\\u0435\\u0442\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438, \\u043d\\u0430\\u043c\\u0435\\u0442\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438, \\u043d\\u0430\\u043c\\u0435\\u0442\\u0438\"}'),
(460,	'{\"en\":\"\\u0411\\u0430\\u0442\\u0443\\u0442\\u0438\",\"ru\":\"\\u0411\\u0430\\u0442\\u0443\\u0442\\u0438\",\"ua\":\"\\u0411\\u0430\\u0442\\u0443\\u0442\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0411\\u0430\\u0442\\u0443\\u0442\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0411\\u0430\\u0442\\u0443\\u0442\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0411\\u0430\\u0442\\u0443\\u0442\\u0438\"}'),
(461,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0442\\u0443\\u0442\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0442\\u0443\\u0442\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0442\\u0443\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0442\\u0443\\u0442\\u0456\\u0432\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0442\\u0443\\u0442\\u0456\\u0432\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0431\\u0430\\u0442\\u0443\\u0442\\u0456\\u0432\"}'),
(462,	'{\"en\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0439\\u0434\\u0430\\u043d\\u0447\\u0438\\u043a\\u0438\",\"ru\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0439\\u0434\\u0430\\u043d\\u0447\\u0438\\u043a\\u0438\",\"ua\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0439\\u0434\\u0430\\u043d\\u0447\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0439\\u0434\\u0430\\u043d\\u0447\\u0438\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0439\\u0434\\u0430\\u043d\\u0447\\u0438\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043c\\u0430\\u0439\\u0434\\u0430\\u043d\\u0447\\u0438\\u043a\\u0438\"}'),
(463,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0433\\u043e\\u0439\\u0434\\u0430\\u043b\\u043a\\u0438\"}'),
(464,	'{\"en\":\"\\u0413\\u0456\\u0440\\u043a\\u0438\",\"ru\":\"\\u0413\\u0456\\u0440\\u043a\\u0438\",\"ua\":\"\\u0413\\u0456\\u0440\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0413\\u0456\\u0440\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0413\\u0456\\u0440\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438 > \\u0413\\u0456\\u0440\\u043a\\u0438\"}'),
(465,	'{\"en\":\"\\u0406\\u0433\\u0440\\u0438 \\u043d\\u0430 \\u043f\\u043b\\u044f\\u0436\\u0456, \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0406\\u0433\\u0440\\u0438 \\u043d\\u0430 \\u043f\\u043b\\u044f\\u0436\\u0456, \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0406\\u0433\\u0440\\u0438 \\u043d\\u0430 \\u043f\\u043b\\u044f\\u0436\\u0456, \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u0438 \\u043d\\u0430 \\u043f\\u043b\\u044f\\u0436\\u0456, \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u0438 \\u043d\\u0430 \\u043f\\u043b\\u044f\\u0436\\u0456, \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u041f\\u0440\\u043e\\u0433\\u0443\\u043b\\u044f\\u043d\\u043a\\u0430 \\u0456 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u0438 \\u043d\\u0430 \\u043f\\u043b\\u044f\\u0436\\u0456, \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(466,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456\"}'),
(467,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043b\\u0456\\u0436\\u0435\\u0447\\u043a\\u0430, \\u043a\\u043e\\u043b\\u0438\\u0441\\u043a\\u0438, \\u043c\\u0430\\u043d\\u0435\\u0436\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043b\\u0456\\u0436\\u0435\\u0447\\u043a\\u0430, \\u043a\\u043e\\u043b\\u0438\\u0441\\u043a\\u0438, \\u043c\\u0430\\u043d\\u0435\\u0436\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043b\\u0456\\u0436\\u0435\\u0447\\u043a\\u0430, \\u043a\\u043e\\u043b\\u0438\\u0441\\u043a\\u0438, \\u043c\\u0430\\u043d\\u0435\\u0436\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043b\\u0456\\u0436\\u0435\\u0447\\u043a\\u0430, \\u043a\\u043e\\u043b\\u0438\\u0441\\u043a\\u0438, \\u043c\\u0430\\u043d\\u0435\\u0436\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043b\\u0456\\u0436\\u0435\\u0447\\u043a\\u0430, \\u043a\\u043e\\u043b\\u0438\\u0441\\u043a\\u0438, \\u043c\\u0430\\u043d\\u0435\\u0436\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043b\\u0456\\u0436\\u0435\\u0447\\u043a\\u0430, \\u043a\\u043e\\u043b\\u0438\\u0441\\u043a\\u0438, \\u043c\\u0430\\u043d\\u0435\\u0436\\u0456\"}'),
(468,	'{\"en\":\"\\u0421\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0421\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0421\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0421\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(469,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0441\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0456\\u0432 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0441\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0456\\u0432 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0441\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0456\\u0432 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0441\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0456\\u0432 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0441\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0456\\u0432 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0441\\u0442\\u0456\\u043b\\u044c\\u0447\\u0438\\u043a\\u0456\\u0432 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(470,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438 \\u0456 \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438 \\u0456 \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438 \\u0456 \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438 \\u0456 \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438 \\u0456 \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043a\\u043e\\u043c\\u043e\\u0434\\u0438, \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438\\u043a\\u0438 \\u0456 \\u043f\\u0435\\u043b\\u0435\\u043d\\u0430\\u0442\\u043e\\u0440\\u0438\"}'),
(471,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u0441\\u0442\\u0456\\u043b\\u044c\\u0446\\u0456\"}'),
(472,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043f\\u0438\\u0441\\u044c\\u043c\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u043f\\u0430\\u0440\\u0442\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043f\\u0438\\u0441\\u044c\\u043c\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u043f\\u0430\\u0440\\u0442\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043f\\u0438\\u0441\\u044c\\u043c\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u043f\\u0430\\u0440\\u0442\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043f\\u0438\\u0441\\u044c\\u043c\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u043f\\u0430\\u0440\\u0442\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043f\\u0438\\u0441\\u044c\\u043c\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u043f\\u0430\\u0440\\u0442\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043f\\u0438\\u0441\\u044c\\u043c\\u043e\\u0432\\u0456 \\u0441\\u0442\\u043e\\u043b\\u0438 \\u0442\\u0430 \\u043f\\u0430\\u0440\\u0442\\u0438\"}'),
(473,	'{\"en\":\"\\u041f\\u0456\\u0434\\u043b\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\",\"ru\":\"\\u041f\\u0456\\u0434\\u043b\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\",\"ua\":\"\\u041f\\u0456\\u0434\\u043b\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u041f\\u0456\\u0434\\u043b\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u041f\\u0456\\u0434\\u043b\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u041f\\u0456\\u0434\\u043b\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\"}'),
(474,	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0434\\u0438\\u0442\\u044f\\u0447\\u0438\\u0445 \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0434\\u0438\\u0442\\u044f\\u0447\\u0438\\u0445 \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0434\\u0438\\u0442\\u044f\\u0447\\u0438\\u0445 \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0434\\u0438\\u0442\\u044f\\u0447\\u0438\\u0445 \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0434\\u0438\\u0442\\u044f\\u0447\\u0438\\u0445 \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0438 \\u0434\\u0438\\u0442\\u044f\\u0447\\u0438\\u0445 \\u043c\\u0435\\u0431\\u043b\\u0456\\u0432\"}'),
(475,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0448\\u0430\\u0444\\u0438, \\u0441\\u0442\\u0435\\u043b\\u0430\\u0436\\u0456, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0448\\u0430\\u0444\\u0438, \\u0441\\u0442\\u0435\\u043b\\u0430\\u0436\\u0456, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0448\\u0430\\u0444\\u0438, \\u0441\\u0442\\u0435\\u043b\\u0430\\u0436\\u0456, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0448\\u0430\\u0444\\u0438, \\u0441\\u0442\\u0435\\u043b\\u0430\\u0436\\u0456, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0448\\u0430\\u0444\\u0438, \\u0441\\u0442\\u0435\\u043b\\u0430\\u0436\\u0456, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0448\\u0430\\u0444\\u0438, \\u0441\\u0442\\u0435\\u043b\\u0430\\u0436\\u0456, \\u0442\\u0443\\u043c\\u0431\\u0438, \\u043f\\u043e\\u043b\\u0438\\u0446\\u0456\"}'),
(476,	'{\"en\":\"\\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u0433\\u0440\\u0430\\u0448\\u043e\\u043a\",\"ru\":\"\\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u0433\\u0440\\u0430\\u0448\\u043e\\u043a\",\"ua\":\"\\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u0433\\u0440\\u0430\\u0448\\u043e\\u043a\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u0433\\u0440\\u0430\\u0448\\u043e\\u043a\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u0433\\u0440\\u0430\\u0448\\u043e\\u043a\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u043c\\u0435\\u0431\\u043b\\u0456 > \\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u0433\\u0440\\u0430\\u0448\\u043e\\u043a\"}'),
(477,	'{\"en\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438\",\"ru\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438\",\"ua\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438\"}'),
(478,	'{\"en\":\"\\u041a\\u0430\\u043d\\u0446\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ru\":\"\\u041a\\u0430\\u043d\\u0446\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ua\":\"\\u041a\\u0430\\u043d\\u0446\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041a\\u0430\\u043d\\u0446\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041a\\u0430\\u043d\\u0446\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041a\\u0430\\u043d\\u0446\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\"}'),
(479,	'{\"en\":\"\\u0422\\u0435\\u043b\\u0435\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ru\":\"\\u0422\\u0435\\u043b\\u0435\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ua\":\"\\u0422\\u0435\\u043b\\u0435\\u0441\\u043a\\u043e\\u043f\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0422\\u0435\\u043b\\u0435\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0422\\u0435\\u043b\\u0435\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0422\\u0435\\u043b\\u0435\\u0441\\u043a\\u043e\\u043f\\u0438\"}'),
(480,	'{\"en\":\"\\u041c\\u0456\\u043a\\u0440\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ru\":\"\\u041c\\u0456\\u043a\\u0440\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ua\":\"\\u041c\\u0456\\u043a\\u0440\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041c\\u0456\\u043a\\u0440\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041c\\u0456\\u043a\\u0440\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041c\\u0456\\u043a\\u0440\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\"}'),
(481,	'{\"en\":\"\\u0417\\u043e\\u0448\\u0438\\u0442\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0417\\u043e\\u0448\\u0438\\u0442\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0417\\u043e\\u0448\\u0438\\u0442\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0417\\u043e\\u0448\\u0438\\u0442\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0417\\u043e\\u0448\\u0438\\u0442\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0417\\u043e\\u0448\\u0438\\u0442\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438\"}'),
(482,	'{\"en\":\"\\u0428\\u043a\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0435\\u043d\\u0430\\u043b\\u0438\",\"ru\":\"\\u0428\\u043a\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0435\\u043d\\u0430\\u043b\\u0438\",\"ua\":\"\\u0428\\u043a\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0435\\u043d\\u0430\\u043b\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0428\\u043a\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0435\\u043d\\u0430\\u043b\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0428\\u043a\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0435\\u043d\\u0430\\u043b\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0428\\u043a\\u0456\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0435\\u043d\\u0430\\u043b\\u0438\"}'),
(483,	'{\"en\":\"\\u041e\\u0440\\u0433\\u0430\\u043d\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438, \\u0431\\u043b\\u043e\\u043a\\u043d\\u043e\\u0442\\u0438\",\"ru\":\"\\u041e\\u0440\\u0433\\u0430\\u043d\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438, \\u0431\\u043b\\u043e\\u043a\\u043d\\u043e\\u0442\\u0438\",\"ua\":\"\\u041e\\u0440\\u0433\\u0430\\u043d\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438, \\u0431\\u043b\\u043e\\u043a\\u043d\\u043e\\u0442\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041e\\u0440\\u0433\\u0430\\u043d\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438, \\u0431\\u043b\\u043e\\u043a\\u043d\\u043e\\u0442\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041e\\u0440\\u0433\\u0430\\u043d\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438, \\u0431\\u043b\\u043e\\u043a\\u043d\\u043e\\u0442\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041e\\u0440\\u0433\\u0430\\u043d\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438, \\u0449\\u043e\\u0434\\u0435\\u043d\\u043d\\u0438\\u043a\\u0438, \\u0431\\u043b\\u043e\\u043a\\u043d\\u043e\\u0442\\u0438\"}'),
(484,	'{\"en\":\"\\u041c\\u043e\\u043b\\u044c\\u0431\\u0435\\u0440\\u0442\\u0438, \\u0434\\u043e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041c\\u043e\\u043b\\u044c\\u0431\\u0435\\u0440\\u0442\\u0438, \\u0434\\u043e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041c\\u043e\\u043b\\u044c\\u0431\\u0435\\u0440\\u0442\\u0438, \\u0434\\u043e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041c\\u043e\\u043b\\u044c\\u0431\\u0435\\u0440\\u0442\\u0438, \\u0434\\u043e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041c\\u043e\\u043b\\u044c\\u0431\\u0435\\u0440\\u0442\\u0438, \\u0434\\u043e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041c\\u043e\\u043b\\u044c\\u0431\\u0435\\u0440\\u0442\\u0438, \\u0434\\u043e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(485,	'{\"en\":\"\\u0413\\u043b\\u043e\\u0431\\u0443\\u0441\\u0438, \\u043a\\u0430\\u0440\\u0442\\u0438\",\"ru\":\"\\u0413\\u043b\\u043e\\u0431\\u0443\\u0441\\u0438, \\u043a\\u0430\\u0440\\u0442\\u0438\",\"ua\":\"\\u0413\\u043b\\u043e\\u0431\\u0443\\u0441\\u0438, \\u043a\\u0430\\u0440\\u0442\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0413\\u043b\\u043e\\u0431\\u0443\\u0441\\u0438, \\u043a\\u0430\\u0440\\u0442\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0413\\u043b\\u043e\\u0431\\u0443\\u0441\\u0438, \\u043a\\u0430\\u0440\\u0442\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u0413\\u043b\\u043e\\u0431\\u0443\\u0441\\u0438, \\u043a\\u0430\\u0440\\u0442\\u0438\"}'),
(486,	'{\"en\":\"\\u041d\\u0430\\u0432\\u0447\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043e\\u0441\\u0456\\u0431\\u043d\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u044f\\u0440\\u0456\\u0432\",\"ru\":\"\\u041d\\u0430\\u0432\\u0447\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043e\\u0441\\u0456\\u0431\\u043d\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u044f\\u0440\\u0456\\u0432\",\"ua\":\"\\u041d\\u0430\\u0432\\u0447\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043e\\u0441\\u0456\\u0431\\u043d\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u044f\\u0440\\u0456\\u0432\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041d\\u0430\\u0432\\u0447\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043e\\u0441\\u0456\\u0431\\u043d\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u044f\\u0440\\u0456\\u0432\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041d\\u0430\\u0432\\u0447\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043e\\u0441\\u0456\\u0431\\u043d\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u044f\\u0440\\u0456\\u0432\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u0438 > \\u041d\\u0430\\u0432\\u0447\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043f\\u043e\\u0441\\u0456\\u0431\\u043d\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0448\\u043a\\u043e\\u043b\\u044f\\u0440\\u0456\\u0432\"}'),
(487,	'{\"en\":\"\\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c\",\"ru\":\"\\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c\",\"ua\":\"\\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c\"}'),
(488,	'{\"en\":\"\\u041c\\u043e\\u043b\\u043e\\u043a\\u043e\\u0432\\u0456\\u0434\\u0441\\u043c\\u043e\\u043a\\u0442\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u041c\\u043e\\u043b\\u043e\\u043a\\u043e\\u0432\\u0456\\u0434\\u0441\\u043c\\u043e\\u043a\\u0442\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u041c\\u043e\\u043b\\u043e\\u043a\\u043e\\u0432\\u0456\\u0434\\u0441\\u043c\\u043e\\u043a\\u0442\\u0443\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041c\\u043e\\u043b\\u043e\\u043a\\u043e\\u0432\\u0456\\u0434\\u0441\\u043c\\u043e\\u043a\\u0442\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041c\\u043e\\u043b\\u043e\\u043a\\u043e\\u0432\\u0456\\u0434\\u0441\\u043c\\u043e\\u043a\\u0442\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041c\\u043e\\u043b\\u043e\\u043a\\u043e\\u0432\\u0456\\u0434\\u0441\\u043c\\u043e\\u043a\\u0442\\u0443\\u0432\\u0430\\u0447\\u0456\"}'),
(489,	'{\"en\":\"\\u0420\\u044e\\u043a\\u0437\\u0430\\u043a\\u0438-\\u043a\\u0435\\u043d\\u0433\\u0443\\u0440\\u0443, \\u0441\\u043b\\u0456\\u043d\\u0433\\u0438, \\u0432\\u0456\\u0436\\u043a\\u0438\",\"ru\":\"\\u0420\\u044e\\u043a\\u0437\\u0430\\u043a\\u0438-\\u043a\\u0435\\u043d\\u0433\\u0443\\u0440\\u0443, \\u0441\\u043b\\u0456\\u043d\\u0433\\u0438, \\u0432\\u0456\\u0436\\u043a\\u0438\",\"ua\":\"\\u0420\\u044e\\u043a\\u0437\\u0430\\u043a\\u0438-\\u043a\\u0435\\u043d\\u0433\\u0443\\u0440\\u0443, \\u0441\\u043b\\u0456\\u043d\\u0433\\u0438, \\u0432\\u0456\\u0436\\u043a\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0420\\u044e\\u043a\\u0437\\u0430\\u043a\\u0438-\\u043a\\u0435\\u043d\\u0433\\u0443\\u0440\\u0443, \\u0441\\u043b\\u0456\\u043d\\u0433\\u0438, \\u0432\\u0456\\u0436\\u043a\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0420\\u044e\\u043a\\u0437\\u0430\\u043a\\u0438-\\u043a\\u0435\\u043d\\u0433\\u0443\\u0440\\u0443, \\u0441\\u043b\\u0456\\u043d\\u0433\\u0438, \\u0432\\u0456\\u0436\\u043a\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0420\\u044e\\u043a\\u0437\\u0430\\u043a\\u0438-\\u043a\\u0435\\u043d\\u0433\\u0443\\u0440\\u0443, \\u0441\\u043b\\u0456\\u043d\\u0433\\u0438, \\u0432\\u0456\\u0436\\u043a\\u0438\"}'),
(490,	'{\"en\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(491,	'{\"en\":\"\\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u0434\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(492,	'{\"en\":\"\\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041f\\u0456\\u0434\\u0456\\u0433\\u0440\\u0456\\u0432\\u0430\\u0447\\u0456, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\"}'),
(493,	'{\"en\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043c\",\"ru\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043c\",\"ua\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043c\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043c\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043c\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043c\"}'),
(494,	'{\"en\":\"\\u0420\\u0430\\u0434\\u0456\\u043e-, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043d\\u044f\\u043d\\u0456\",\"ru\":\"\\u0420\\u0430\\u0434\\u0456\\u043e-, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043d\\u044f\\u043d\\u0456\",\"ua\":\"\\u0420\\u0430\\u0434\\u0456\\u043e-, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043d\\u044f\\u043d\\u0456\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0420\\u0430\\u0434\\u0456\\u043e-, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043d\\u044f\\u043d\\u0456\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0420\\u0430\\u0434\\u0456\\u043e-, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043d\\u044f\\u043d\\u0456\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0420\\u0430\\u0434\\u0456\\u043e-, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043d\\u044f\\u043d\\u0456\"}'),
(495,	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\"}',	'{\"en\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\",\"ru\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\",\"ua\":\"\\u0414\\u0438\\u0442\\u044f\\u0447\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0432\\u0430\\u0433\\u0456\\u0442\\u043d\\u0438\\u0445 \\u0456 \\u0433\\u043e\\u0434\\u0443\\u044e\\u0447\\u0438\\u0445 \\u043c\\u0430\\u043c > \\u0414\\u0438\\u0442\\u044f\\u0447\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u043a\\u0430\"}'),
(496,	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438\"}'),
(497,	'{\"en\":\"\\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ru\":\"\\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ua\":\"\\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\"}'),
(498,	'{\"en\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ru\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ua\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\"}'),
(499,	'{\"en\":\"\\u041e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ru\":\"\\u041e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ua\":\"\\u041e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\"}'),
(500,	'{\"en\":\"\\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ru\":\"\\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ua\":\"\\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a\"}'),
(501,	'{\"en\":\"\\u041d\\u0430\\u0448\\u0438\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u041d\\u0430\\u0448\\u0438\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u041d\\u0430\\u0448\\u0438\\u0439\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041d\\u0430\\u0448\\u0438\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041d\\u0430\\u0448\\u0438\\u0439\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041d\\u0430\\u0448\\u0438\\u0439\\u043d\\u0438\\u043a\\u0438\"}'),
(502,	'{\"en\":\"\\u041d\\u0430\\u043c\\u043e\\u0440\\u0434\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u041d\\u0430\\u043c\\u043e\\u0440\\u0434\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u041d\\u0430\\u043c\\u043e\\u0440\\u0434\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041d\\u0430\\u043c\\u043e\\u0440\\u0434\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041d\\u0430\\u043c\\u043e\\u0440\\u0434\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041d\\u0430\\u043c\\u043e\\u0440\\u0434\\u043d\\u0438\\u043a\\u0438\"}'),
(503,	'{\"en\":\"\\u041f\\u043e\\u0432\\u0456\\u0434\\u0446\\u0456, \\u0448\\u043b\\u0435\\u0457\",\"ru\":\"\\u041f\\u043e\\u0432\\u0456\\u0434\\u0446\\u0456, \\u0448\\u043b\\u0435\\u0457\",\"ua\":\"\\u041f\\u043e\\u0432\\u0456\\u0434\\u0446\\u0456, \\u0448\\u043b\\u0435\\u0457\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041f\\u043e\\u0432\\u0456\\u0434\\u0446\\u0456, \\u0448\\u043b\\u0435\\u0457\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041f\\u043e\\u0432\\u0456\\u0434\\u0446\\u0456, \\u0448\\u043b\\u0435\\u0457\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0410\\u043c\\u0443\\u043d\\u0456\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u041f\\u043e\\u0432\\u0456\\u0434\\u0446\\u0456, \\u0448\\u043b\\u0435\\u0457\"}'),
(504,	'{\"en\":\"\\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0456\\u0441\\u0446\\u044f, \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ru\":\"\\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0456\\u0441\\u0446\\u044f, \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ua\":\"\\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0456\\u0441\\u0446\\u044f, \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0456\\u0441\\u0446\\u044f, \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0456\\u0441\\u0446\\u044f, \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0421\\u043f\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0456\\u0441\\u0446\\u044f, \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\"}'),
(505,	'{\"en\":\"\\u0413\\u0440\\u0443\\u043c\\u0456\\u043d\\u0433 \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ru\":\"\\u0413\\u0440\\u0443\\u043c\\u0456\\u043d\\u0433 \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ua\":\"\\u0413\\u0440\\u0443\\u043c\\u0456\\u043d\\u0433 \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0413\\u0440\\u0443\\u043c\\u0456\\u043d\\u0433 \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0413\\u0440\\u0443\\u043c\\u0456\\u043d\\u0433 \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a > \\u0413\\u0440\\u0443\\u043c\\u0456\\u043d\\u0433 \\u0434\\u043b\\u044f \\u0441\\u043e\\u0431\\u0430\\u043a \\u0456 \\u043a\\u043e\\u0442\\u0456\\u0432\"}'),
(506,	'{\"en\":\"\\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ru\":\"\\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ua\":\"\\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\"}'),
(507,	'{\"en\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ru\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ua\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\"}'),
(508,	'{\"en\":\"\\u0414\\u0440\\u044f\\u043f\\u043a\\u0438\",\"ru\":\"\\u0414\\u0440\\u044f\\u043f\\u043a\\u0438\",\"ua\":\"\\u0414\\u0440\\u044f\\u043f\\u043a\\u0438\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u0414\\u0440\\u044f\\u043f\\u043a\\u0438\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u0414\\u0440\\u044f\\u043f\\u043a\\u0438\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u0414\\u0440\\u044f\\u043f\\u043a\\u0438\"}'),
(509,	'{\"en\":\"\\u041d\\u0430\\u043f\\u043e\\u0432\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0456\\u0432 \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ru\":\"\\u041d\\u0430\\u043f\\u043e\\u0432\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0456\\u0432 \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ua\":\"\\u041d\\u0430\\u043f\\u043e\\u0432\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0456\\u0432 \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u041d\\u0430\\u043f\\u043e\\u0432\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0456\\u0432 \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u041d\\u0430\\u043f\\u043e\\u0432\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0456\\u0432 \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u041d\\u0430\\u043f\\u043e\\u0432\\u043d\\u044e\\u0432\\u0430\\u0447\\u0456 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0456\\u0432 \\u0434\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432\"}'),
(510,	'{\"en\":\"\\u0414\\u0432\\u0435\\u0440\\u0446\\u044f\\u0442\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0456\\u0448\\u043e\\u043a \\u0456 \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ru\":\"\\u0414\\u0432\\u0435\\u0440\\u0446\\u044f\\u0442\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0456\\u0448\\u043e\\u043a \\u0456 \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ua\":\"\\u0414\\u0432\\u0435\\u0440\\u0446\\u044f\\u0442\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0456\\u0448\\u043e\\u043a \\u0456 \\u0441\\u043e\\u0431\\u0430\\u043a\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u0414\\u0432\\u0435\\u0440\\u0446\\u044f\\u0442\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0456\\u0448\\u043e\\u043a \\u0456 \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u0414\\u0432\\u0435\\u0440\\u0446\\u044f\\u0442\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0456\\u0448\\u043e\\u043a \\u0456 \\u0441\\u043e\\u0431\\u0430\\u043a\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043a\\u043e\\u0442\\u0456\\u0432 > \\u0414\\u0432\\u0435\\u0440\\u0446\\u044f\\u0442\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0456\\u0448\\u043e\\u043a \\u0456 \\u0441\\u043e\\u0431\\u0430\\u043a\"}'),
(511,	'{\"en\":\"\\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ru\":\"\\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ua\":\"\\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\"}'),
(512,	'{\"en\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ru\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ua\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\"}'),
(513,	'{\"en\":\"\\u041a\\u043b\\u0456\\u0442\\u043a\\u0438, \\u0432\\u043e\\u043b\\u044c\\u0454\\u0440\\u0438, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ru\":\"\\u041a\\u043b\\u0456\\u0442\\u043a\\u0438, \\u0432\\u043e\\u043b\\u044c\\u0454\\u0440\\u0438, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ua\":\"\\u041a\\u043b\\u0456\\u0442\\u043a\\u0438, \\u0432\\u043e\\u043b\\u044c\\u0454\\u0440\\u0438, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432 > \\u041a\\u043b\\u0456\\u0442\\u043a\\u0438, \\u0432\\u043e\\u043b\\u044c\\u0454\\u0440\\u0438, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432 > \\u041a\\u043b\\u0456\\u0442\\u043a\\u0438, \\u0432\\u043e\\u043b\\u044c\\u0454\\u0440\\u0438, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432 > \\u041a\\u043b\\u0456\\u0442\\u043a\\u0438, \\u0432\\u043e\\u043b\\u044c\\u0454\\u0440\\u0438, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\"}'),
(514,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u0433\\u0440\\u0438\\u0437\\u0443\\u043d\\u0456\\u0432\"}'),
(515,	'{\"en\":\"\\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ru\":\"\\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ua\":\"\\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\"}'),
(516,	'{\"en\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ru\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ua\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\"}'),
(517,	'{\"en\":\"\\u041a\\u043b\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ru\":\"\\u041a\\u043b\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ua\":\"\\u041a\\u043b\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u041a\\u043b\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u041a\\u043b\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u041a\\u043b\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\"}'),
(518,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u043a\\u043b\\u0456\\u0442\\u043e\\u043a \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\"}'),
(519,	'{\"en\":\"\\u0413\\u043e\\u0434\\u0456\\u0432\\u043d\\u0438\\u0446\\u0456, \\u0448\\u043f\\u0430\\u043a\\u0456\\u0432\\u043d\\u0456, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ru\":\"\\u0413\\u043e\\u0434\\u0456\\u0432\\u043d\\u0438\\u0446\\u0456, \\u0448\\u043f\\u0430\\u043a\\u0456\\u0432\\u043d\\u0456, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ua\":\"\\u0413\\u043e\\u0434\\u0456\\u0432\\u043d\\u0438\\u0446\\u0456, \\u0448\\u043f\\u0430\\u043a\\u0456\\u0432\\u043d\\u0456, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u0413\\u043e\\u0434\\u0456\\u0432\\u043d\\u0438\\u0446\\u0456, \\u0448\\u043f\\u0430\\u043a\\u0456\\u0432\\u043d\\u0456, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u0413\\u043e\\u0434\\u0456\\u0432\\u043d\\u0438\\u0446\\u0456, \\u0448\\u043f\\u0430\\u043a\\u0456\\u0432\\u043d\\u0456, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432 > \\u0413\\u043e\\u0434\\u0456\\u0432\\u043d\\u0438\\u0446\\u0456, \\u0448\\u043f\\u0430\\u043a\\u0456\\u0432\\u043d\\u0456, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043e\\u0447\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0442\\u0430\\u0445\\u0456\\u0432\"}'),
(520,	'{\"en\":\"\\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\",\"ru\":\"\\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\",\"ua\":\"\\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\"}'),
(521,	'{\"en\":\"\\u0410\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\",\"ru\":\"\\u0410\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\",\"ua\":\"\\u0410\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0410\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0410\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0410\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\"}'),
(522,	'{\"en\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\",\"ru\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\",\"ua\":\"\\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u041a\\u043e\\u0440\\u043c \\u0434\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439\"}'),
(523,	'{\"en\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}'),
(524,	'{\"en\":\"\\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}'),
(525,	'{\"en\":\"\\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u041e\\u0441\\u0432\\u0456\\u0442\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}'),
(526,	'{\"en\":\"\\u041f\\u043e\\u043c\\u043f\\u0438 \\u0456 \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u041f\\u043e\\u043c\\u043f\\u0438 \\u0456 \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u041f\\u043e\\u043c\\u043f\\u0438 \\u0456 \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u041f\\u043e\\u043c\\u043f\\u0438 \\u0456 \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u041f\\u043e\\u043c\\u043f\\u0438 \\u0456 \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\