(527,	'{\"en\":\"\\u0422\\u0435\\u0440\\u043c\\u043e\\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0422\\u0435\\u0440\\u043c\\u043e\\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0422\\u0435\\u0440\\u043c\\u043e\\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u0422\\u0435\\u0440\\u043c\\u043e\\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u0422\\u0435\\u0440\\u043c\\u043e\\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u0422\\u0435\\u0440\\u043c\\u043e\\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0446\\u0456\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}'),
(528,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}'),
(529,	'{\"en\":\"\\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ru\":\"\\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ua\":\"\\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 (\\u0440\\u0456\\u0437\\u043d\\u0435)\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0430\\u043a\\u0432\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 (\\u0440\\u0456\\u0437\\u043d\\u0435)\"}'),
(530,	'{\"en\":\"\\u0422\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\",\"ru\":\"\\u0422\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\",\"ua\":\"\\u0422\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0422\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0422\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0422\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0438\"}'),
(531,	'{\"en\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}'),
(532,	'{\"en\":\"\\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0442\\u0430 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0442\\u0430 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0442\\u0430 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0442\\u0430 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0442\\u0430 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0414\\u043b\\u044f \\u0440\\u0438\\u0431 \\u0456 \\u0440\\u0435\\u043f\\u0442\\u0438\\u043b\\u0456\\u0439 > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432 > \\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0442\\u0430 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0435\\u0440\\u0430\\u0440\\u0456\\u0443\\u043c\\u0456\\u0432\"}'),
(533,	'{\"en\":\"\\u0420\\u0456\\u0437\\u043d\\u0435\",\"ru\":\"\\u0420\\u0456\\u0437\\u043d\\u0435\",\"ua\":\"\\u0420\\u0456\\u0437\\u043d\\u0435\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435\"}'),
(534,	'{\"en\":\"\\u0412\\u0456\\u0442\\u0430\\u043c\\u0456\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ru\":\"\\u0412\\u0456\\u0442\\u0430\\u043c\\u0456\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ua\":\"\\u0412\\u0456\\u0442\\u0430\\u043c\\u0456\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0412\\u0456\\u0442\\u0430\\u043c\\u0456\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0412\\u0456\\u0442\\u0430\\u043c\\u0456\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0412\\u0456\\u0442\\u0430\\u043c\\u0456\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\"}'),
(535,	'{\"en\":\"\\u041f\\u043e\\u0441\\u0443\\u0434 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ru\":\"\\u041f\\u043e\\u0441\\u0443\\u0434 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ua\":\"\\u041f\\u043e\\u0441\\u0443\\u0434 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u041f\\u043e\\u0441\\u0443\\u0434 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u041f\\u043e\\u0441\\u0443\\u0434 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u041f\\u043e\\u0441\\u0443\\u0434 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\"}'),
(536,	'{\"en\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ru\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ua\":\"\\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0406\\u0433\\u0440\\u0430\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\"}'),
(537,	'{\"en\":\"\\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\",\"ru\":\"\\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\",\"ua\":\"\\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443\"}'),
(538,	'{\"en\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ru\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ua\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\"}',	'{\"en\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ru\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\",\"ua\":\"\\u0417\\u043e\\u043e\\u0442\\u043e\\u0432\\u0430\\u0440\\u0438 > \\u0420\\u0456\\u0437\\u043d\\u0435 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0433\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0442\\u0432\\u0430\\u0440\\u0438\\u043d\"}'),
(539,	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\"}'),
(540,	'{\"en\":\"\\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}'),
(541,	'{\"en\":\"\\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u0456 (\\u0446\\u0438\\u0440\\u043a\\u0443\\u043b\\u044f\\u0440\\u043d\\u0456) \\u043f\\u0438\\u043b\\u0438\",\"ru\":\"\\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u0456 (\\u0446\\u0438\\u0440\\u043a\\u0443\\u043b\\u044f\\u0440\\u043d\\u0456) \\u043f\\u0438\\u043b\\u0438\",\"ua\":\"\\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u0456 (\\u0446\\u0438\\u0440\\u043a\\u0443\\u043b\\u044f\\u0440\\u043d\\u0456) \\u043f\\u0438\\u043b\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u0456 (\\u0446\\u0438\\u0440\\u043a\\u0443\\u043b\\u044f\\u0440\\u043d\\u0456) \\u043f\\u0438\\u043b\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u0456 (\\u0446\\u0438\\u0440\\u043a\\u0443\\u043b\\u044f\\u0440\\u043d\\u0456) \\u043f\\u0438\\u043b\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u0456 (\\u0446\\u0438\\u0440\\u043a\\u0443\\u043b\\u044f\\u0440\\u043d\\u0456) \\u043f\\u0438\\u043b\\u0438\"}'),
(542,	'{\"en\":\"\\u0411\\u043e\\u043b\\u0433\\u0430\\u0440\\u043a\\u0438 (\\u043a\\u0443\\u0442\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u043c\\u0430\\u0448\\u0438\\u043d\\u0438)\",\"ru\":\"\\u0411\\u043e\\u043b\\u0433\\u0430\\u0440\\u043a\\u0438 (\\u043a\\u0443\\u0442\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u043c\\u0430\\u0448\\u0438\\u043d\\u0438)\",\"ua\":\"\\u0411\\u043e\\u043b\\u0433\\u0430\\u0440\\u043a\\u0438 (\\u043a\\u0443\\u0442\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u043c\\u0430\\u0448\\u0438\\u043d\\u0438)\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0411\\u043e\\u043b\\u0433\\u0430\\u0440\\u043a\\u0438 (\\u043a\\u0443\\u0442\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u043c\\u0430\\u0448\\u0438\\u043d\\u0438)\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0411\\u043e\\u043b\\u0433\\u0430\\u0440\\u043a\\u0438 (\\u043a\\u0443\\u0442\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u043c\\u0430\\u0448\\u0438\\u043d\\u0438)\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0411\\u043e\\u043b\\u0433\\u0430\\u0440\\u043a\\u0438 (\\u043a\\u0443\\u0442\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u043c\\u0430\\u0448\\u0438\\u043d\\u0438)\"}'),
(543,	'{\"en\":\"\\u0412\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0456, \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u043b\\u043e\\u0442\\u043d\\u0430\",\"ru\":\"\\u0412\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0456, \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u043b\\u043e\\u0442\\u043d\\u0430\",\"ua\":\"\\u0412\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0456, \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u043b\\u043e\\u0442\\u043d\\u0430\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0412\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0456, \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u043b\\u043e\\u0442\\u043d\\u0430\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0412\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0456, \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u043b\\u043e\\u0442\\u043d\\u0430\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0412\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0456, \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u043b\\u043e\\u0442\\u043d\\u0430\"}'),
(544,	'{\"en\":\"\\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}'),
(545,	'{\"en\":\"\\u0428\\u0430\\u0431\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u0438\",\"ru\":\"\\u0428\\u0430\\u0431\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u0438\",\"ua\":\"\\u0428\\u0430\\u0431\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0428\\u0430\\u0431\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0428\\u0430\\u0431\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0428\\u0430\\u0431\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u0438\"}'),
(546,	'{\"en\":\"\\u041f\\u0440\\u044f\\u043c\\u0456, \\u0449\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u041f\\u0440\\u044f\\u043c\\u0456, \\u0449\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u041f\\u0440\\u044f\\u043c\\u0456, \\u0449\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0440\\u044f\\u043c\\u0456, \\u0449\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0440\\u044f\\u043c\\u0456, \\u0449\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0440\\u044f\\u043c\\u0456, \\u0449\\u0456\\u0442\\u043a\\u043e\\u0432\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}'),
(547,	'{\"en\":\"\\u0412\\u0456\\u0431\\u0440\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0412\\u0456\\u0431\\u0440\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0412\\u0456\\u0431\\u0440\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0412\\u0456\\u0431\\u0440\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0412\\u0456\\u0431\\u0440\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0412\\u0456\\u0431\\u0440\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0448\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}'),
(548,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u043e\\u0431\\u0437\\u0438\\u043a\\u0438\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u043e\\u0431\\u0437\\u0438\\u043a\\u0438\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u043e\\u0431\\u0437\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u043e\\u0431\\u0437\\u0438\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u043e\\u0431\\u0437\\u0438\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043b\\u043e\\u0431\\u0437\\u0438\\u043a\\u0438\"}'),
(549,	'{\"en\":\"\\u041f\\u043e\\u043b\\u0456\\u0440\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u041f\\u043e\\u043b\\u0456\\u0440\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u041f\\u043e\\u043b\\u0456\\u0440\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u043e\\u043b\\u0456\\u0440\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u043e\\u043b\\u0456\\u0440\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u043e\\u043b\\u0456\\u0440\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}'),
(550,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0428\\u043b\\u0456\\u0444\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439, \\u0432\\u0456\\u0434\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043e\\u0436\\u0438\\u0446\\u0456\"}'),
(551,	'{\"en\":\"\\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}'),
(552,	'{\"en\":\"\\u0428\\u0443\\u0440\\u0443\\u043f\\u043e\\u043a\\u0440\\u0443\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0434\\u0440\\u0438\\u043b\\u0456\",\"ru\":\"\\u0428\\u0443\\u0440\\u0443\\u043f\\u043e\\u043a\\u0440\\u0443\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0434\\u0440\\u0438\\u043b\\u0456\",\"ua\":\"\\u0428\\u0443\\u0440\\u0443\\u043f\\u043e\\u043a\\u0440\\u0443\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0434\\u0440\\u0438\\u043b\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0428\\u0443\\u0440\\u0443\\u043f\\u043e\\u043a\\u0440\\u0443\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0434\\u0440\\u0438\\u043b\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0428\\u0443\\u0440\\u0443\\u043f\\u043e\\u043a\\u0440\\u0443\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0434\\u0440\\u0438\\u043b\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0428\\u0443\\u0440\\u0443\\u043f\\u043e\\u043a\\u0440\\u0443\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0434\\u0440\\u0438\\u043b\\u0456\"}'),
(553,	'{\"en\":\"\\u041f\\u0435\\u0440\\u0444\\u043e\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041f\\u0435\\u0440\\u0444\\u043e\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041f\\u0435\\u0440\\u0444\\u043e\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0435\\u0440\\u0444\\u043e\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0435\\u0440\\u0444\\u043e\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0435\\u0440\\u0444\\u043e\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}'),
(554,	'{\"en\":\"\\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0430, \\u0431\\u0443\\u0440\\u0438, \\u0441\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u043a\\u043e\\u0440\\u043e\\u043d\\u043a\\u0438\",\"ru\":\"\\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0430, \\u0431\\u0443\\u0440\\u0438, \\u0441\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u043a\\u043e\\u0440\\u043e\\u043d\\u043a\\u0438\",\"ua\":\"\\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0430, \\u0431\\u0443\\u0440\\u0438, \\u0441\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u043a\\u043e\\u0440\\u043e\\u043d\\u043a\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0430, \\u0431\\u0443\\u0440\\u0438, \\u0441\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u043a\\u043e\\u0440\\u043e\\u043d\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0430, \\u0431\\u0443\\u0440\\u0438, \\u0441\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u043a\\u043e\\u0440\\u043e\\u043d\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0430, \\u0431\\u0443\\u0440\\u0438, \\u0441\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u043a\\u043e\\u0440\\u043e\\u043d\\u043a\\u0438\"}'),
(555,	'{\"en\":\"\\u041f\\u0430\\u0442\\u0440\\u043e\\u043d\\u0438, \\u043d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0443\",\"ru\":\"\\u041f\\u0430\\u0442\\u0440\\u043e\\u043d\\u0438, \\u043d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0443\",\"ua\":\"\\u041f\\u0430\\u0442\\u0440\\u043e\\u043d\\u0438, \\u043d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0443\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0430\\u0442\\u0440\\u043e\\u043d\\u0438, \\u043d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0443\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0430\\u0442\\u0440\\u043e\\u043d\\u0438, \\u043d\\u0430\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\