(565,	'{\"en\":\"\\u041f\\u0430\\u044f\\u043b\\u044c\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\",\"ru\":\"\\u041f\\u0430\\u044f\\u043b\\u044c\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\",\"ua\":\"\\u041f\\u0430\\u044f\\u043b\\u044c\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0430\\u044f\\u043b\\u044c\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0430\\u044f\\u043b\\u044c\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0430\\u044f\\u043b\\u044c\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f\"}'),
(566,	'{\"en\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0435\\u043d\\u0438\",\"ru\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0435\\u043d\\u0438\",\"ua\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0435\\u043d\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0435\\u043d\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0435\\u043d\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0422\\u0435\\u0445\\u043d\\u0456\\u0447\\u043d\\u0456 \\u0444\\u0435\\u043d\\u0438\"}'),
(567,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0440\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0440\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0440\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0440\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0440\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0440\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\"}'),
(568,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0435\\u043f\\u043b\\u0435\\u0440\\u0438, \\u0446\\u0432\\u044f\\u0445\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0435\\u043f\\u043b\\u0435\\u0440\\u0438, \\u0446\\u0432\\u044f\\u0445\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0435\\u043f\\u043b\\u0435\\u0440\\u0438, \\u0446\\u0432\\u044f\\u0445\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0435\\u043f\\u043b\\u0435\\u0440\\u0438, \\u0446\\u0432\\u044f\\u0445\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0435\\u043f\\u043b\\u0435\\u0440\\u0438, \\u0446\\u0432\\u044f\\u0445\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0441\\u0442\\u0435\\u043f\\u043b\\u0435\\u0440\\u0438, \\u0446\\u0432\\u044f\\u0445\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456\"}'),
(569,	'{\"en\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0437\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\"}'),
(570,	'{\"en\":\"\\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\"}'),
(571,	'{\"en\":\"\\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043f\\u0430\\u0440\\u0430\\u0442\\u0438\",\"ru\":\"\\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043f\\u0430\\u0440\\u0430\\u0442\\u0438\",\"ua\":\"\\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043f\\u0430\\u0440\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043f\\u0430\\u0440\\u0430\\u0442\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043f\\u0430\\u0440\\u0430\\u0442\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0430\\u043f\\u0430\\u0440\\u0430\\u0442\\u0438\"}'),
(572,	'{\"en\":\"\\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ru\":\"\\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ua\":\"\\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\"}'),
(573,	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 \\u0434\\u043b\\u044f \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0443\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 \\u0434\\u043b\\u044f \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0443\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 \\u0434\\u043b\\u044f \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0443\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 \\u0434\\u043b\\u044f \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0443\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 \\u0434\\u043b\\u044f \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0443\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u044