(574,	'{\"en\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0456\\u043d\\u0434\\u0438\\u0432\\u0456\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\\u0443 \\u0434\\u043b\\u044f \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\",\"ru\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0456\\u043d\\u0434\\u0438\\u0432\\u0456\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\\u0443 \\u0434\\u043b\\u044f \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\",\"ua\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0456\\u043d\\u0434\\u0438\\u0432\\u0456\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\\u0443 \\u0434\\u043b\\u044f \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0456\\u043d\\u0434\\u0438\\u0432\\u0456\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\\u0443 \\u0434\\u043b\\u044f \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0456\\u043d\\u0434\\u0438\\u0432\\u0456\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\\u0443 \\u0434\\u043b\\u044f \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0417\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0456\\u043d\\u0434\\u0438\\u0432\\u0456\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\\u0443 \\u0434\\u043b\\u044f \\u0437\\u0432\\u0430\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\"}'),
(575,	'{\"en\":\"\\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}'),
(576,	'{\"en\":\"\\u0422\\u043e\\u043a\\u0430\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0422\\u043e\\u043a\\u0430\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0422\\u043e\\u043a\\u0430\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0422\\u043e\\u043a\\u0430\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0422\\u043e\\u043a\\u0430\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0422\\u043e\\u043a\\u0430\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}'),
(577,	'{\"en\":\"\\u0417\\u0430\\u0442\\u043e\\u0447\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0417\\u0430\\u0442\\u043e\\u0447\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0417\\u0430\\u0442\\u043e\\u0447\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0417\\u0430\\u0442\\u043e\\u0447\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0417\\u0430\\u0442\\u043e\\u0447\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0417\\u0430\\u0442\\u043e\\u0447\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}'),
(578,	'{\"en\":\"\\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0421\\u0432\\u0435\\u0440\\u0434\\u043b\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}'),
(579,	'{\"en\":\"\\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}'),
(580,	'{\"en\":\"\\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\",\"ru\":\"\\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\",\"ua\":\"\\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0424\\u0440\\u0435\\u0437\\u0435\\u0440\"}'),
(581,	'{\"en\":\"\\u0420\\u0435\\u0439\\u0441\\u043c\\u0443\\u0441\\u043e\\u0432\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0420\\u0435\\u0439\\u0441\\u043c\\u0443\\u0441\\u043e\\u0432\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0420\\u0435\\u0439\\u0441\\u043c\\u0443\\u0441\\u043e\\u0432\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0420\\u0435\\u0439\\u0441\\u043c\\u0443\\u0441\\u043e\\u0432\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0420\\u0435\\u0439\\u0441\\u043c\\u0443\\u0441\\u043e\\u0432\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0420\\u0435\\u0439\\u0441\\u043c\\u0443\\u0441\\u043e\\u0432\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}'),
(582,	'{\"en\":\"\\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u043f\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u043f\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u043f\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u043f\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u043f\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0421\\u0442\\u0440\\u0456\\u0447\\u043a\\u043e\\u043f\\u0438\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438\"}'),
(583,	'{\"en\":\"\\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 (\\u0456\\u043d\\u0448\\u0456)\",\"ru\":\"\\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 (\\u0456\\u043d\\u0448\\u0456)\",\"ua\":\"\\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 (\\u0456\\u043d\\u0448\\u0456)\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 (\\u0456\\u043d\\u0448\\u0456)\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 (\\u0456\\u043d\\u0448\\u0456)\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 (\\u0456\\u043d\\u0448\\u0456)\"}'),
(584,	'{\"en\":\"\\u0424\\u0440\\u0435\\u0437\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\",\"ru\":\"\\u0424\\u0440\\u0435\\u0437\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\",\"ua\":\"\\u0424\\u0440\\u0435\\u0437\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0424\\u0440\\u0435\\u0437\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0424\\u0440\\u0435\\u0437\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0424\\u0440\\u0435\\u0437\\u0438 \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\"}'),
(585,	'{\"en\":\"\\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\",\"ru\":\"\\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\",\"ua\":\"\\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0438 > \\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0435\\u0440\\u0441\\u0442\\u0430\\u0442\\u0456\\u0432\"}'),
(586,	'{\"en\":\"\\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ru\":\"\\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ua\":\"\\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456\"}'),
(587,	'{\"en\":\"\\u0422\\u043e\\u0440\\u0446\\u0435\\u0432\\u0456 \\u0433\\u043e\\u043b\\u043e\\u0432\\u043a\\u0438\",\"ru\":\"\\u0422\\u043e\\u0440\\u0446\\u0435\\u0432\\u0456 \\u0433\\u043e\\u043b\\u043e\\u0432\\u043a\\u0438\",\"ua\":\"\\u0422\\u043e\\u0440\\u0446\\u0435\\u0432\\u0456 \\u0433\\u043e\\u043b\\u043e\\u0432\\u043a\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u043e\\u0440\\u0446\\u0435\\u0432\\u0456 \\u0433\\u043e\\u043b\\u043e\\u0432\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u043e\\u0440\\u0446\\u0435\\u0432\\u0456 \\u0433\\u043e\\u043b\\u043e\\u0432\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u043e\\u0440\\u0446\\u0435\\u0432\\u0456 \\u0433\\u043e\\u043b\\u043e\\u0432\\u043a\\u0438\"}'),
(588,	'{\"en\":\"\\u0413\\u0430\\u0439\\u043a\\u043e\\u0432\\u0456, \\u0440\\u043e\\u0437\\u0432\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ru\":\"\\u0413\\u0430\\u0439\\u043a\\u043e\\u0432\\u0456, \\u0440\\u043e\\u0437\\u0432\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ua\":\"\\u0413\\u0430\\u0439\\u043a\\u043e\\u0432\\u0456, \\u0440\\u043e\\u0437\\u0432\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0413\\u0430\\u0439\\u043a\\u043e\\u0432\\u0456, \\u0440\\u043e\\u0437\\u0432\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0413\\u0430\\u0439\\u043a\\u043e\\u0432\\u0456, \\u0440\\u043e\\u0437\\u0432\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0413\\u0430\\u0439\\u043a\\u043e\\u0432\\u0456, \\u0440\\u043e\\u0437\\u0432\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\"}'),
(589,	'{\"en\":\"\\u0422\\u0440\\u0435\\u0449\\u0456\\u0442\\u043a\\u0438, \\u0434\\u0438\\u043d\\u0430\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ru\":\"\\u0422\\u0440\\u0435\\u0449\\u0456\\u0442\\u043a\\u0438, \\u0434\\u0438\\u043d\\u0430\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ua\":\"\\u0422\\u0440\\u0435\\u0449\\u0456\\u0442\\u043a\\u0438, \\u0434\\u0438\\u043d\\u0430\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u0440\\u0435\\u0449\\u0456\\u0442\\u043a\\u0438, \\u0434\\u0438\\u043d\\u0430\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u0440\\u0435\\u0449\\u0456\\u0442\\u043a\\u0438, \\u0434\\u0438\\u043d\\u0430\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u0440\\u0435\\u0449\\u0456\\u0442\\u043a\\u0438, \\u0434\\u0438\\u043d\\u0430\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\"}'),
(590,	'{\"en\":\"\\u0412\\u043e\\u0440\\u043e\\u0442\\u043a\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0445\\u0456\\u0434\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0412\\u043e\\u0440\\u043e\\u0442\\u043a\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0445\\u0456\\u0434\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0412\\u043e\\u0440\\u043e\\u0442\\u043a\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0445\\u0456\\u0434\\u043d\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0412\\u043e\\u0440\\u043e\\u0442\\u043a\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0445\\u0456\\u0434\\u043d\\u0438\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0412\\u043e\\u0440\\u043e\\u0442\\u043a\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0445\\u0456\\u0434\\u043d\\u0438\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0412\\u043e\\u0440\\u043e\\u0442\\u043a\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0445\\u0456\\u0434\\u043d\\u0438\\u043a\\u0438\"}'),
(591,	'{\"en\":\"\\u0422\\u0440\\u0443\\u0431\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ru\":\"\\u0422\\u0440\\u0443\\u0431\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ua\":\"\\u0422\\u0440\\u0443\\u0431\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u0440\\u0443\\u0431\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u0440\\u0443\\u0431\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u0440\\u0443\\u0431\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\"}'),
(592,	'{\"en\":\"\\u0428\\u0435\\u0441\\u0442\\u0438\\u0433\\u0440\\u0430\\u043d\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ru\":\"\\u0428\\u0435\\u0441\\u0442\\u0438\\u0433\\u0440\\u0430\\u043d\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ua\":\"\\u0428\\u0435\\u0441\\u0442\\u0438\\u0433\\u0440\\u0430\\u043d\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0428\\u0435\\u0441\\u0442\\u0438\\u0433\\u0440\\u0430\\u043d\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0428\\u0435\\u0441\\u0442\\u0438\\u0433\\u0440\\u0430\\u043d\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0428\\u0435\\u0441\\u0442\\u0438\\u0433\\u0440\\u0430\\u043d\\u043d\\u0456 \\u043a\\u043b\\u044e\\u0447\\u0456\"}'),
(593,	'{\"en\":\"\",\"ru\":\"\",\"ua\":\"\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \"}'),
(594,	'{\"en\":\"\\u0417\\u0443\\u0431\\u0438\\u043b\\u0430, \\u0441\\u0442\\u0430\\u043c\\u0435\\u0441\\u043a\\u0438, \\u0434\\u043e\\u043b\\u043e\\u0442\\u043e\",\"ru\":\"\\u0417\\u0443\\u0431\\u0438\\u043b\\u0430, \\u0441\\u0442\\u0430\\u043c\\u0435\\u0441\\u043a\\u0438, \\u0434\\u043e\\u043b\\u043e\\u0442\\u043e\",\"ua\":\"\\u0417\\u0443\\u0431\\u0438\\u043b\\u0430, \\u0441\\u0442\\u0430\\u043c\\u0435\\u0441\\u043a\\u0438, \\u0434\\u043e\\u043b\\u043e\\u0442\\u043e\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0417\\u0443\\u0431\\u0438\\u043b\\u0430, \\u0441\\u0442\\u0430\\u043c\\u0435\\u0441\\u043a\\u0438, \\u0434\\u043e\\u043b\\u043e\\u0442\\u043e\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0417\\u0443\\u0431\\u0438\\u043b\\u0430, \\u0441\\u0442\\u0430\\u043c\\u0435\\u0441\\u043a\\u0438, \\u0434\\u043e\\u043b\\u043e\\u0442\\u043e\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0417\\u0443\\u0431\\u0438\\u043b\\u0430, \\u0441\\u0442\\u0430\\u043c\\u0435\\u0441\\u043a\\u0438, \\u0434\\u043e\\u043b\\u043e\\u0442\\u043e\"}'),
(595,	'{\"en\":\"\\u041c\\u043e\\u043b\\u043e\\u0442\\u043a\\u0438\",\"ru\":\"\\u041c\\u043e\\u043b\\u043e\\u0442\\u043a\\u0438\",\"ua\":\"\\u041c\\u043e\\u043b\\u043e\\u0442\\u043a\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041c\\u043e\\u043b\\u043e\\u0442\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041c\\u043e\\u043b\\u043e\\u0442\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041c\\u043e\\u043b\\u043e\\u0442\\u043a\\u0438\"}'),
(596,	'{\"en\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ru\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ua\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\"}'),
(597,	'{\"en\":\"\\u041d\\u0430\\u043f\\u0438\\u043b\\u043a\\u0438, \\u0440\\u0430\\u0448\\u043f\\u0438\\u043b\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u043c\\u0435\\u0442\\u0430\\u043b\\u0435\\u0432\\u0456\",\"ru\":\"\\u041d\\u0430\\u043f\\u0438\\u043b\\u043a\\u0438, \\u0440\\u0430\\u0448\\u043f\\u0438\\u043b\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u043c\\u0435\\u0442\\u0430\\u043b\\u0435\\u0432\\u0456\",\"ua\":\"\\u041d\\u0430\\u043f\\u0438\\u043b\\u043a\\u0438, \\u0440\\u0430\\u0448\\u043f\\u0438\\u043b\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u043c\\u0435\\u0442\\u0430\\u043b\\u0435\\u0432\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u0430\\u043f\\u0438\\u043b\\u043a\\u0438, \\u0440\\u0430\\u0448\\u043f\\u0438\\u043b\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u043c\\u0435\\u0442\\u0430\\u043b\\u0435\\u0432\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u0430\\u043f\\u0438\\u043b\\u043a\\u0438, \\u0440\\u0430\\u0448\\u043f\\u0438\\u043b\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u043c\\u0435\\u0442\\u0430\\u043b\\u0435\\u0432\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u0430\\u043f\\u0438\\u043b\\u043a\\u0438, \\u0440\\u0430\\u0448\\u043f\\u0438\\u043b\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u043c\\u0435\\u0442\\u0430\\u043b\\u0435\\u043