(598,	'{\"en\":\"\\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u043f\\u043e \\u043c\\u0435\\u0442\\u0430\\u043b\\u0443\",\"ru\":\"\\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u043f\\u043e \\u043c\\u0435\\u0442\\u0430\\u043b\\u0443\",\"ua\":\"\\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u043f\\u043e \\u043c\\u0435\\u0442\\u0430\\u043b\\u0443\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u043f\\u043e \\u043c\\u0435\\u0442\\u0430\\u043b\\u0443\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u043f\\u043e \\u043c\\u0435\\u0442\\u0430\\u043b\\u0443\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u043f\\u043e \\u043c\\u0435\\u0442\\u0430\\u043b\\u0443\"}'),
(599,	'{\"en\":\"\\u041d\\u043e\\u0436\\u0456\\u0432\\u043a\\u0438\",\"ru\":\"\\u041d\\u043e\\u0436\\u0456\\u0432\\u043a\\u0438\",\"ua\":\"\\u041d\\u043e\\u0436\\u0456\\u0432\\u043a\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u043e\\u0436\\u0456\\u0432\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u043e\\u0436\\u0456\\u0432\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041d\\u043e\\u0436\\u0456\\u0432\\u043a\\u0438\"}'),
(600,	'{\"en\":\"\\u0412\\u0438\\u043a\\u0440\\u0443\\u0442\\u043a\\u0438\",\"ru\":\"\\u0412\\u0438\\u043a\\u0440\\u0443\\u0442\\u043a\\u0438\",\"ua\":\"\\u0412\\u0438\\u043a\\u0440\\u0443\\u0442\\u043a\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0412\\u0438\\u043a\\u0440\\u0443\\u0442\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0412\\u0438\\u043a\\u0440\\u0443\\u0442\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0412\\u0438\\u043a\\u0440\\u0443\\u0442\\u043a\\u0438\"}'),
(601,	'{\"en\":\"\\u041f\\u043b\\u043e\\u0441\\u043a\\u043e\\u0433\\u0443\\u0431\\u0446\\u0456, \\u043a\\u0443\\u0441\\u0430\\u0447\\u043a\\u0438, \\u043a\\u043b\\u0456\\u0449\\u0456\",\"ru\":\"\\u041f\\u043b\\u043e\\u0441\\u043a\\u043e\\u0433\\u0443\\u0431\\u0446\\u0456, \\u043a\\u0443\\u0441\\u0430\\u0447\\u043a\\u0438, \\u043a\\u043b\\u0456\\u0449\\u0456\",\"ua\":\"\\u041f\\u043b\\u043e\\u0441\\u043a\\u043e\\u0433\\u0443\\u0431\\u0446\\u0456, \\u043a\\u0443\\u0441\\u0430\\u0447\\u043a\\u0438, \\u043a\\u043b\\u0456\\u0449\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041f\\u043b\\u043e\\u0441\\u043a\\u043e\\u0433\\u0443\\u0431\\u0446\\u0456, \\u043a\\u0443\\u0441\\u0430\\u0447\\u043a\\u0438, \\u043a\\u043b\\u0456\\u0449\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041f\\u043b\\u043e\\u0441\\u043a\\u043e\\u0433\\u0443\\u0431\\u0446\\u0456, \\u043a\\u0443\\u0441\\u0430\\u0447\\u043a\\u0438, \\u043a\\u043b\\u0456\\u0449\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041f\\u043b\\u043e\\u0441\\u043a\\u043e\\u0433\\u0443\\u0431\\u0446\\u0456, \\u043a\\u0443\\u0441\\u0430\\u0447\\u043a\\u0438, \\u043a\\u043b\\u0456\\u0449\\u0456\"}'),
(602,	'{\"en\":\"\\u0420\\u0456\\u0437\\u044c\\u0431\\u043e\\u043d\\u0430\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0420\\u0456\\u0437\\u044c\\u0431\\u043e\\u043d\\u0430\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0420\\u0456\\u0437\\u044c\\u0431\\u043e\\u043d\\u0430\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0420\\u0456\\u0437\\u044c\\u0431\\u043e\\u043d\\u0430\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0420\\u0456\\u0437\\u044c\\u0431\\u043e\\u043d\\u0430\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0420\\u0456\\u0437\\u044c\\u0431\\u043e\\u043d\\u0430\\u0440\\u0456\\u0437\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}'),
(603,	'{\"en\":\"\\u0421\\u043a\\u043e\\u0431\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456, \\u0441\\u043a\\u043e\\u0431\\u0438\",\"ru\":\"\\u0421\\u043a\\u043e\\u0431\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456, \\u0441\\u043a\\u043e\\u0431\\u0438\",\"ua\":\"\\u0421\\u043a\\u043e\\u0431\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456, \\u0441\\u043a\\u043e\\u0431\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0421\\u043a\\u043e\\u0431\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456, \\u0441\\u043a\\u043e\\u0431\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0421\\u043a\\u043e\\u0431\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456, \\u0441\\u043a\\u043e\\u0431\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0421\\u043a\\u043e\\u0431\\u043e\\u0437\\u0430\\u0431\\u0438\\u0432\\u0430\\u0447\\u0456, \\u0441\\u043a\\u043e\\u0431\\u0438\"}'),
(604,	'{\"en\":\"\\u0417\\u043d\\u0456\\u043c\\u0430\\u0447\\u0456 \\u0443\\u043d\\u0456\\u0432\\u0435\\u0440\\u0441\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ru\":\"\\u0417\\u043d\\u0456\\u043c\\u0430\\u0447\\u0456 \\u0443\\u043d\\u0456\\u0432\\u0435\\u0440\\u0441\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ua\":\"\\u0417\\u043d\\u0456\\u043c\\u0430\\u0447\\u0456 \\u0443\\u043d\\u0456\\u0432\\u0435\\u0440\\u0441\\u0430\\u043b\\u044c\\u043d\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0417\\u043d\\u0456\\u043c\\u0430\\u0447\\u0456 \\u0443\\u043d\\u0456\\u0432\\u0435\\u0440\\u0441\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0417\\u043d\\u0456\\u043c\\u0430\\u0447\\u0456 \\u0443\\u043d\\u0456\\u0432\\u0435\\u0440\\u0441\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0417\\u043d\\u0456\\u043c\\u0430\\u0447\\u0456 \\u0443\\u043d\\u0456\\u0432\\u0435\\u0440\\u0441\\u0430\\u043b\\u044c\\u043d\\u0456\"}'),
(605,	'{\"en\":\"\\u041b\\u0435\\u0449\\u0430\\u0442\\u0430, \\u0441\\u0442\\u0440\\u0443\\u0431\\u0446\\u0438\\u043d\\u0438\",\"ru\":\"\\u041b\\u0435\\u0449\\u0430\\u0442\\u0430, \\u0441\\u0442\\u0440\\u0443\\u0431\\u0446\\u0438\\u043d\\u0438\",\"ua\":\"\\u041b\\u0435\\u0449\\u0430\\u0442\\u0430, \\u0441\\u0442\\u0440\\u0443\\u0431\\u0446\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041b\\u0435\\u0449\\u0430\\u0442\\u0430, \\u0441\\u0442\\u0440\\u0443\\u0431\\u0446\\u0438\\u043d\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041b\\u0435\\u0449\\u0430\\u0442\\u0430, \\u0441\\u0442\\u0440\\u0443\\u0431\\u0446\\u0438\\u043d\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u041b\\u0435\\u0449\\u0430\\u0442\\u0430, \\u0441\\u0442\\u0440\\u0443\\u0431\\u0446\\u0438\\u043d\\u0438\"}'),
(606,	'{\"en\":\"\\u0422\\u0440\\u0443\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u0422\\u0440\\u0443\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u0422\\u0440\\u0443\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u0440\\u0443\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u0440\\u0443\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u0422\\u0440\\u0443\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\"}'),
(607,	'{\"en\":\"\\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ru\":\"\\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ua\":\"\\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u043b\\u044e\\u0441\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442, \\u043a\\u043b\\u044e\\u0447\\u0456 > \\u042f\\u0449\\u0438\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0456\\u0432\"}'),
(608,	'{\"en\":\"\\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}'),
(609,	'{\"en\":\"\\u0412\\u0430\\u043b\\u0438\\u043a\\u0438, \\u043c\\u0430\\u043b\\u044f\\u0440\\u043d\\u0456 \\u043a\\u0438\\u0441\\u0442\\u0456\",\"ru\":\"\\u0412\\u0430\\u043b\\u0438\\u043a\\u0438, \\u043c\\u0430\\u043b\\u044f\\u0440\\u043d\\u0456 \\u043a\\u0438\\u0441\\u0442\\u0456\",\"ua\":\"\\u0412\\u0430\\u043b\\u0438\\u043a\\u0438, \\u043c\\u0430\\u043b\\u044f\\u0440\\u043d\\u0456 \\u043a\\u0438\\u0441\\u0442\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0412\\u0430\\u043b\\u0438\\u043a\\u0438, \\u043c\\u0430\\u043b\\u044f\\u0440\\u043d\\u0456 \\u043a\\u0438\\u0441\\u0442\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0412\\u0430\\u043b\\u0438\\u043a\\u0438, \\u043c\\u0430\\u043b\\u044f\\u0440\\u043d\\u0456 \\u043a\\u0438\\u0441\\u0442\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0412\\u0430\\u043b\\u0438\\u043a\\u0438, \\u043c\\u0430\\u043b\\u044f\\u0440\\u043d\\u0456 \\u043a\\u0438\\u0441\\u0442\\u0456\"}'),
(610,	'{\"en\":\"\\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\",\"ru\":\"\\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\",\"ua\":\"\\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0404\\u043c\\u043d\\u043e\\u0441\\u0442\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\"}'),
(611,	'{\"en\":\"\\u041d\\u043e\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\",\"ru\":\"\\u041d\\u043e\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\",\"ua\":\"\\u041d\\u043e\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041d\\u043e\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041d\\u043e\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041d\\u043e\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442\"}'),
(612,	'{\"en\":\"\\u041f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0440\\u043c\\u0435\\u0442\\u0438\\u043a\\u0456\\u0432, \\u043f\\u0456\\u043d\",\"ru\":\"\\u041f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0440\\u043c\\u0435\\u0442\\u0438\\u043a\\u0456\\u0432, \\u043f\\u0456\\u043d\",\"ua\":\"\\u041f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0440\\u043c\\u0435\\u0442\\u0438\\u043a\\u0456\\u0432, \\u043f\\u0456\\u043d\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0440\\u043c\\u0435\\u0442\\u0438\\u043a\\u0456\\u0432, \\u043f\\u0456\\u043d\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0440\\u043c\\u0435\\u0442\\u0438\\u043a\\u0456\\u0432, \\u043f\\u0456\\u043d\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0440\\u043c\\u0435\\u0442\\u0438\\u043a\\u0456\\u0432, \\u043f\\u0456\\u043d\"}'),
(613,	'{\"en\":\"\\u0428\\u043f\\u0430\\u0442\\u0435\\u043b\\u0456, \\u0442\\u0435\\u0440\\u043a\\u0438 \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ru\":\"\\u0428\\u043f\\u0430\\u0442\\u0435\\u043b\\u0456, \\u0442\\u0435\\u0440\\u043a\\u0438 \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ua\":\"\\u0428\\u043f\\u0430\\u0442\\u0435\\u043b\\u0456, \\u0442\\u0435\\u0440\\u043a\\u0438 \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0428\\u043f\\u0430\\u0442\\u0435\\u043b\\u0456, \\u0442\\u0435\\u0440\\u043a\\u0438 \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0428\\u043f\\u0430\\u0442\\u0435\\u043b\\u0456, \\u0442\\u0435\\u0440\\u043a\\u0438 \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043b\\u044f\\u0440\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0428\\u043f\\u0430\\u0442\\u0435\\u043b\\u0456, \\u0442\\u0435\\u0440\\u043a\\u0438 \\u043e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456\"}'),
(614,	'{\"en\":\"\\u0421\\u0442\\u043e\\u043b\\u044f\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0421\\u0442\\u043e\\u043b\\u044f\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0421\\u0442\\u043e\\u043b\\u044f\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0442\\u043e\\u043b\\u044f\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0442\\u043e\\u043b\\u044f\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0442\\u043e\\u043b\\u044f\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}'),
(615,	'{\"en\":\"\\u0420\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\",\"ru\":\"\\u0420\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\",\"ua\":\"\\u0420\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0442\\u043e\\u043b\\u044f\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0420\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0442\\u043e\\u043b\\u044f\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0420\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0421\\u0442\\u043e\\u043b\\u044f\\u0440\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0420\\u0443\\u0431\\u0430\\u043d\\u043a\\u0438\"}'),
