(617,	'{\"en\":\"\\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}'),
(618,	'{\"en\":\"\\u041b\\u0430\\u0437\\u0435\\u0440\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u041b\\u0430\\u0437\\u0435\\u0440\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u041b\\u0430\\u0437\\u0435\\u0440\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041b\\u0430\\u0437\\u0435\\u0440\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041b\\u0430\\u0437\\u0435\\u0440\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041b\\u0430\\u0437\\u0435\\u0440\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u