(620,	'{\"en\":\"\\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ru\":\"\\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ua\":\"\\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u041c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\"}'),
(621,	'{\"en\":\"\\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0421\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u0456\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}'),
(622,	'{\"en\":\"\\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0420\\u0443\\u0447\\u043d\\u0438\\u0439 \\u0432\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\