(623,	'{\"en\":\"\\u0420\\u0456\\u0432\\u043d\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\",\"ru\":\"\\u0420\\u0456\\u0432\\u043d\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\",\"ua\":\"\\u0420\\u0456\\u0432\\u043d\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0420\\u0456\\u0432\\u043d\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0420\\u0456\\u0432\\u043d\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0412\\u0438\\u043c\\u0456\\u0440\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 > \\u0420\\u0456\\u0432\\u043d\\u0456 \\u0431\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456\"}'),
(624,	'{\"en\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\"}'),
(625,	'{\"en\":\"\\u0411\\u0435\\u043d\\u0437\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u0411\\u0435\\u043d\\u0437\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u0411\\u0435\\u043d\\u0437\\u043e\\u0440\\u0456\\u0437\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0435\\u043d\\u0437\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0435\\u043d\\u0437\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0435\\u043d\\u0437\\u043e\\u0440\\u0456\\u0437\\u0438\"}'),
(626,	'{\"en\":\"\\u0411\\u0435\\u0442\\u043e\\u043d\\u043e\\u0437\\u043c\\u0456\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0411\\u0435\\u0442\\u043e\\u043d\\u043e\\u0437\\u043c\\u0456\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0411\\u0435\\u0442\\u043e\\u043d\\u043e\\u0437\\u043c\\u0456\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0435\\u0442\\u043e\\u043d\\u043e\\u0437\\u043c\\u0456\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0435\\u0442\\u043e\\u043d\\u043e\\u0437\\u043c\\u0456\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0435\\u0442\\u043e\\u043d\\u043e\\u0437\\u043c\\u0456\\u0448\\u0443\\u0432\\u0430\\u0447\\u0456\"}'),
(627,	'{\"en\":\"\\u0412\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442\\u0438, \\u0432\\u0456\\u0431\\u0440\\u043e\\u0431\\u0443\\u043b\\u0430\\u0432\\u0438\",\"ru\":\"\\u0412\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442\\u0438, \\u0432\\u0456\\u0431\\u0440\\u043e\\u0431\\u0443\\u043b\\u0430\\u0432\\u0438\",\"ua\":\"\\u0412\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442\\u0438, \\u0432\\u0456\\u0431\\u0440\\u043e\\u0431\\u0443\\u043b\\u0430\\u0432\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0412\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442\\u0438, \\u0432\\u0456\\u0431\\u0440\\u043e\\u0431\\u0443\\u043b\\u0430\\u0432\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0412\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442\\u0438, \\u0432\\u0456\\u0431\\u0440\\u043e\\u0431\\u0443\\u043b\\u0430\\u0432\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0412\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442\\u0438, \\u0432\\u0456\\u0431\\u0440\\u043e\\u0431\\u0443\\u043b\\u0430\\u0432\\u0438\"}'),
(628,	'{\"en\":\"\\u0417\\u0430\\u0442\\u0438\\u0440\\u043e\\u0447\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0417\\u0430\\u0442\\u0438\\u0440\\u043e\\u0447\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0417\\u0430\\u0442\\u0438\\u0440\\u043e\\u0447\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0417\\u0430\\u0442\\u0438\\u0440\\u043e\\u0447\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0417\\u0430\\u0442\\u0438\\u0440\\u043e\\u0447\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0417\\u0430\\u0442\\u0438\\u0440\\u043e\\u0447\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}'),
(629,	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0438\"}'),
(630,	'{\"en\":\"\\u0414\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438, \\u0440\\u043e\\u0437\\u0441\\u0443\\u0432\\u043di \\u0434\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438\",\"ru\":\"\\u0414\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438, \\u0440\\u043e\\u0437\\u0441\\u0443\\u0432\\u043di \\u0434\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438\",\"ua\":\"\\u0414\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438, \\u0440\\u043e\\u0437\\u0441\\u0443\\u0432\\u043di \\u0434\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0414\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438, \\u0440\\u043e\\u0437\\u0441\\u0443\\u0432\\u043di \\u0434\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0414\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438, \\u0440\\u043e\\u0437\\u0441\\u0443\\u0432\\u043di \\u0434\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0414\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438, \\u0440\\u043e\\u0437\\u0441\\u0443\\u0432\\u043di \\u0434\\u0440\\u0430\\u0431\\u0438\\u043d\\u0438\"}'),
(631,	'{\"en\":\"\\u041b\\u043e\\u043c\\u0438, \\u043e\\u0431\\u0446\\u0435\\u043d\\u044c\\u043a\\u0438\",\"ru\":\"\\u041b\\u043e\\u043c\\u0438, \\u043e\\u0431\\u0446\\u0435\\u043d\\u044c\\u043a\\u0438\",\"ua\":\"\\u041b\\u043e\\u043c\\u0438, \\u043e\\u0431\\u0446\\u0435\\u043d\\u044c\\u043a\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041b\\u043e\\u043c\\u0438, \\u043e\\u0431\\u0446\\u0435\\u043d\\u044c\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041b\\u043e\\u043c\\u0438, \\u043e\\u0431\\u0446\\u0435\\u043d\\u044c\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041b\\u043e\\u043c\\u0438, \\u043e\\u0431\\u0446\\u0435\\u043d\\u044c\\u043a\\u0438\"}'),
(632,	'{\"en\":\"\\u041c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0438\",\"ru\":\"\\u041c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0438\",\"ua\":\"\\u041c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0438\"}'),
(633,	'{\"en\":\"\\u041f\\u043b\\u0438\\u0442\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u041f\\u043b\\u0438\\u0442\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u041f\\u043b\\u0438\\u0442\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u043b\\u0438\\u0442\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u043b\\u0438\\u0442\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u043b\\u0438\\u0442\\u043a\\u043e\\u0440\\u0456\\u0437\\u0438\"}'),
(634,	'{\"en\":\"\\u0421\\u043a\\u043b\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u0421\\u043a\\u043b\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u0421\\u043a\\u043b\\u043e\\u0440\\u0456\\u0437\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0421\\u043a\\u043b\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0421\\u043a\\u043b\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0421\\u043a\\u043b\\u043e\\u0440\\u0456\\u0437\\u0438\"}'),
(635,	'{\"en\":\"\\u041d\\u0430\\u0432\\u0430\\u043d\\u0442\\u0430\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u0448\\u0442\\u0430\\u0431\\u0435\\u043b\\u0435\\u0440\\u0438, \\u0433\\u0456\\u0434\\u0440\\u0430\\u0432\\u043b\\u0456\\u0447\\u043d\\u0456 \\u0432\\u0456\\u0437\\u043a\\u0438\",\"ru\":\"\\u041d\\u0430\\u0432\\u0430\\u043d\\u0442\\u0430\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u0448\\u0442\\u0430\\u0431\\u0435\\u043b\\u0435\\u0440\\u0438, \\u0433\\u0456\\u0434\\u0440\\u0430\\u0432\\u043b\\u0456\\u0447\\u043d\\u0456 \\u0432\\u0456\\u0437\\u043a\\u0438\",\"ua\":\"\\u041d\\u0430\\u0432\\u0430\\u043d\\u0442\\u0430\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u0448\\u0442\\u0430\\u0431\\u0435\\u043b\\u0435\\u0440\\u0438, \\u0433\\u0456\\u0434\\u0440\\u0430\\u0432\\u043b\\u0456\\u0447\\u043d\\u0456 \\u0432\\u0456\\u0437\\u043a\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0432\\u0430\\u043d\\u0442\\u0430\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u0448\\u0442\\u0430\\u0431\\u0435\\u043b\\u0435\\u0440\\u0438, \\u0433\\u0456\\u0434\\u0440\\u0430\\u0432\\u043b\\u0456\\u0447\\u043d\\u0456 \\u0432\\u0456\\u0437\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0432\\u0430\\u043d\\u0442\\u0430\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u0448\\u0442\\u0430\\u0431\\u0435\\u043b\\u0435\\u0440\\u0438, \\u0433\\u0456\\u0434\\u0440\\u0430\\u0432\\u043b\\u0456\\u0447\\u043d\\u0456 \\u0432\\u0456\\u0437\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041d\\u0430\\u0432\\u0430\\u043d\\u0442\\u0430\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456, \\u0448\\u0442\\u0430\\u0431\\u0435\\u043b\\u0435\\u0440\\u0438, \\u0433\\u0456\\u0434\\u0440\\u0430\\u0432\\u043b\\u0456\\u0447\\u043d\\u0456 \\u0432\\u0456\\u0437\\u043a\\u0438\"}'),
(636,	'{\"en\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0438\\u0448\\u043a\\u0438, \\u043f\\u043e\\u043c\\u043e\\u0441\\u0442\\u0438, \\u0440\\u0438\\u0448\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0438\\u0448\\u043a\\u0438, \\u043f\\u043e\\u043c\\u043e\\u0441\\u0442\\u0438, \\u0440\\u0438\\u0448\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0438\\u0448\\u043a\\u0438, \\u043f\\u043e\\u043c\\u043e\\u0441\\u0442\\u0438, \\u0440\\u0438\\u0448\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0438\\u0448\\u043a\\u0438, \\u043f\\u043e\\u043c\\u043e\\u0441\\u0442\\u0438, \\u0440\\u0438\\u0448\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0438\\u0448\\u043a\\u0438, \\u043f\\u043e\\u043c\\u043e\\u0441\\u0442\\u0438, \\u0440\\u0438\\u0448\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u0432\\u0438\\u0448\\u043a\\u0438, \\u043f\\u043e\\u043c\\u043e\\u0441\\u0442\\u0438, \\u0440\\u0438\\u0448\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(637,	'{\"en\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043b\\u0435\\u0431\\u0456\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043b\\u0456\",\"ru\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043b\\u0435\\u0431\\u0456\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043b\\u0456\",\"ua\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043b\\u0435\\u0431\\u0456\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043b\\u0456\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043b\\u0435\\u0431\\u0456\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043b\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043b\\u0435\\u0431\\u0456\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043b\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043b\\u0435\\u0431\\u0456\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043b\\u0456\"}'),
(638,	'{\"en\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438, \\u043f\\u0456\\u0434\\u043c\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438, \\u043f\\u0456\\u0434\\u043c\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438, \\u043f\\u0456\\u0434\\u043c\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438, \\u043f\\u0456\\u0434\\u043c\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438, \\u043f\\u0456\\u0434\\u043c\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0456 \\u043f\\u0438\\u043b\\u043e\\u0441\\u043e\\u0441\\u0438, \\u043f\\u0456\\u0434\\u043c\\u0456\\u0442\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0448\\u0438\\u043d\\u0438\"}'),
(639,	'{\"en\":\"\\u0428\\u0442\\u0440\\u043e\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u0428\\u0442\\u0440\\u043e\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u0428\\u0442\\u0440\\u043e\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0428\\u0442\\u0440\\u043e\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0428\\u0442\\u0440\\u043e\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0428\\u0442\\u0440\\u043e\\u0431\\u043e\\u0440\\u0456\\u0437\\u0438\"}'),
(640,	'{\"en\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u0432\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442, \\u0433\\u043b\\u0438\\u0431\\u0438\\u043d\\u043d\\u0438\\u0445 \\u0432\\u0456\\u0431\\u0440\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\",\"ru\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u0432\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442, \\u0433\\u043b\\u0438\\u0431\\u0438\\u043d\\u043d\\u0438\\u0445 \\u0432\\u0456\\u0431\\u0440\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\",\"ua\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u0432\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442, \\u0433\\u043b\\u0438\\u0431\\u0438\\u043d\\u043d\\u0438\\u0445 \\u0432\\u0456\\u0431\\u0440\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u0432\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442, \\u0433\\u043b\\u0438\\u0431\\u0438\\u043d\\u043d\\u0438\\u0445 \\u0432\\u0456\\u0431\\u0440\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u0432\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442, \\u0433\\u043b\\u0438\\u0431\\u0438\\u043d\\u043d\\u0438\\u0445 \\u0432\\u0456\\u0431\\u0440\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u0432\\u0456\\u0431\\u0440\\u043e\\u043f\\u043b\\u0438\\u0442, \\u0433\\u043b\\u0438\\u0431\\u0438\\u043d\\u043d\\u0438\\u0445 \\u0432\\u0456\\u0431\\u0440\\u0430\\u0442\\u043e\\u0440\\u0456\\u0432\"}'),
(641,	'{\"en\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u043f\\u043d\\u0435\\u0432\\u043c\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0443\",\"ru\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u043f\\u043d\\u0435\\u0432\\u043c\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0443\",\"ua\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u043f\\u043d\\u0435\\u0432\\u043c\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0443\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u043f\\u043d\\u0435\\u0432\\u043c\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0443\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u043f\\u043d\\u0435\\u0432\\u043c\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0443\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u043e\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u043f\\u043d\\u0435\\u0432\\u043c\\u043e\\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0443\"}'),
(642,	'{\"en\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0456\\u0432\",\"ru\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0456\\u0432\",\"ua\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0456\\u0432\"}',	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0456\\u0432\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0456\\u0432\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0411\\u0443\\u0434\\u0456\\u0432\\u0435\\u043b\\u044c\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0434\\u044f \\u0434\\u043b\\u044f \\u043c\\u043e\\u0442\\u043e\\u0431\\u0443\\u0440\\u0456\\u0432\"}'),
(643,	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456\"}'),
(644,	'{\"en\":\"\\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438\",\"ru\":\"\\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438\",\"ua\":\"\\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438\"}'),
(645,	'{\"en\":\"\\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438\",\"ru\":\"\\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438\",\"ua\":\"\\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438\"}'),
(646,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\"}'),
(647,	'{\"en\":\"\\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\",\"ru\":\"\\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\",\"ua\":\"\\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432 > \\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432 > \\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432 > \\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u043d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0456\\u0432\"}'),
