(651,	'{\"en\":\"\\u041f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438\",\"ru\":\"\\u041f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438\",\"ua\":\"\\u041f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u041f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u041f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041d\\u043e\\u0443\\u0442\\u0431\\u0443\\u043a\\u0438, \\u043f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438, \\u0435\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0456 \\u043a\\u043d\\u0438\\u0433\\u0438 > \\u041f\\u043b\\u0430\\u043d\\u0448\\u0435\\u0442\\u0438\"}'),
