(668,	'{\"en\":\"SSD \\u043d\\u0430\\u043a\\u043e\\u043f\\u0438\\u0447\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"SSD \\u043d\\u0430\\u043a\\u043e\\u043f\\u0438\\u0447\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"SSD \\u043d\\u0430\\u043a\\u043e\\u043f\\u0438\\u0447\\u0443\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > SSD \\u043d\\u0430\\u043a\\u043e\\u043f\\u0438\\u0447\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > SSD \\u043d\\u0430\\u043a\\u043e\\u043f\\u0438\\u0447\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > SSD \\u043d\\u0430\\u043a\\u043e\\u043f\\u0438\\u0447\\u0443\\u0432\\u0430\\u0447\\u0456\"}'),
(669,	'{\"en\":\"\\u0416\\u043e\\u0440\\u0441\\u0442\\u043a\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ru\":\"\\u0416\\u043e\\u0440\\u0441\\u0442\\u043a\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ua\":\"\\u0416\\u043e\\u0440\\u0441\\u0442\\u043a\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u0416\\u043e\\u0440\\u0441\\u0442\\u043a\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u0416\\u043e\\u0440\\u0441\\u0442\\u043a\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u0416\\u043e\\u0440\\u0441\\u0442\\u043a\\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438\"}'),
