(674,	'{\"en\":\"\\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u043e\\u0434\\u0438 DVD, Blu-ray\",\"ru\":\"\\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u043e\\u0434\\u0438 DVD, Blu-ray\",\"ua\":\"\\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u043e\\u0434\\u0438 DVD, Blu-ray\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u043e\\u0434\\u0438 DVD, Blu-ray\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u043e\\u0434\\u0438 DVD, Blu-ray\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u0414\\u0438\\u0441\\u043a\\u043e\\u0432\\u043e\\u0434\\u0438 DVD, Blu-ray\"}'),
(675,	'{\"en\":\"\\u041a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0456\\u0432\",\"ru\":\"\\u041a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0456\\u0432\",\"ua\":\"\\u041a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0456\\u0432\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u041a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0456\\u0432\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u041a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0456\\u0432\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u041a\\u043e\\u0440\\u043f\\u0443\\u0441\\u0438 \\u0434\\u043b\\u044f \\u043a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0456\\u0432\"}'),
(676,	'{\"en\":\"\\u0411\\u043b\\u043e\\u043a\\u0438 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u0411\\u043b\\u043e\\u043a\\u0438 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u0411\\u043b\\u043e\\u043a\\u0438 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u0411\\u043b\\u043e\\u043a\\u0438 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u0411\\u043b\\u043e\\u043a\\u0438 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u0411\\u043b\\u043e\\u043a\\u0438 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\"}'),
(677,	'{\"en\":\"\\u041a\\u0443\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u043e\\u0445\\u043e\\u043b\\u043e\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u0443\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u043e\\u0445\\u043e\\u043b\\u043e\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u0443\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u043e\\u0445\\u043e\\u043b\\u043e\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u041a\\u0443\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u043e\\u0445\\u043e\\u043b\\u043e\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u041a\\u0443\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u043e\\u0445\\u043e\\u043b\\u043e\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0442\\u0443\\u044e\\u0447\\u0456 > \\u041a\\u0443\\u043b\\u0435\\u0440\\u0438 \\u0442\\u0430 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u043e\\u0445\\u043e\\u043b\\u043e\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\"}'),
