(692,	'{\"en\":\"\\u041a\\u043e\\u043c\\u0443\\u0442\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043a\\u043e\\u043d\\u0441\\u043e\\u043b\\u0435\\u0439 (KVM Switches)\",\"ru\":\"\\u041a\\u043e\\u043c\\u0443\\u0442\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043a\\u043e\\u043d\\u0441\\u043e\\u043b\\u0435\\u0439 (KVM Switches)\",\"ua\":\"\\u041a\\u043e\\u043c\\u0443\\u0442\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043a\\u043e\\u043d\\u0441\\u043e\\u043b\\u0435\\u0439 (KVM Switches)\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041a\\u043e\\u043c\\u0443\\u0442\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043a\\u043e\\u043d\\u0441\\u043e\\u043b\\u0435\\u0439 (KVM Switches)\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041a\\u043e\\u043c\\u0443\\u0442\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043a\\u043e\\u043d\\u0441\\u043e\\u043b\\u0435\\u0439 (KVM Switches)\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041a\\u043e\\u043c\\u0443\\u0442\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043a\\u043e\\u043d\\u0441\\u043e\\u043b\\u0435\\u0439 (KVM Switches)\"}'),
