(694,	'{\"en\":\"\\u041c\\u0456\\u0436\\u043c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0435\\u043a\\u0440\\u0430\\u043d\\u0438 (Firewall)\",\"ru\":\"\\u041c\\u0456\\u0436\\u043c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0435\\u043a\\u0440\\u0430\\u043d\\u0438 (Firewall)\",\"ua\":\"\\u041c\\u0456\\u0436\\u043c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0435\\u043a\\u0440\\u0430\\u043d\\u0438 (Firewall)\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u0456\\u0436\\u043c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0435\\u043a\\u0440\\u0430\\u043d\\u0438 (Firewall)\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u0456\\u0436\\u043c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0435\\u043a\\u0440\\u0430\\u043d\\u0438 (Firewall)\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u0456\\u0436\\u043c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0435\\u043a\\u0440\\u0430\\u043d\\u0438 (Firewall)\"}'),
(695,	'{\"en\":\"IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457\",\"ru\":\"IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457\",\"ua\":\"IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457\"}'),
(696,	'{\"en\":\"IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0438\",\"ru\":\"IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0438\",\"ua\":\"IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0438\"}'),
(697,	'{\"en\":\"VoIP-\\u0448\\u043b\\u044e\\u0437\\u0438\",\"ru\":\"VoIP-\\u0448\\u043b\\u044e\\u0437\\u0438\",\"ua\":\"VoIP-\\u0448\\u043b\\u044e\\u0437\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457 > VoIP-\\u0448\\u043b\\u044e\\u0437\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457 > VoIP-\\u0448\\u043b\\u044e\\u0437\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457 > VoIP-\\u0448\\u043b\\u044e\\u0437\\u0438\"}'),
(698,	'{\"en\":\"\\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446-\\u0437\\u0432\'\\u044f\\u0437\\u043a\\u0443\",\"ru\":\"\\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446-\\u0437\\u0432\'\\u044f\\u0437\\u043a\\u0443\",\"ua\":\"\\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446-\\u0437\\u0432\'\\u044f\\u0437\\u043a\\u0443\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457 > \\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446-\\u0437\\u0432\'\\u044f\\u0437\\u043a\\u0443\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457 > \\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446-\\u0437\\u0432\'\\u044f\\u0437\\u043a\\u0443\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > IP-\\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u044f, \\u0432\\u0456\\u0434\\u0435\\u043e\\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0456\\u0457 > \\u041e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u043a\\u043e\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446-\\u0437\\u0432\'\\u044f\\u0437\\u043a\\u0443\"}'),
(699,	'{\"en\":\"\\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\"}'),
(700,	'{\"en\":\"\\u041a\\u0430\\u0431\\u0435\\u043b\\u0456 \\u0432\\u0438\\u0442\\u043e\\u0457 \\u043f\\u0430\\u0440\\u0438, \\u043f\\u0430\\u0442\\u0447-\\u043a\\u043e\\u0440\\u0434\\u0438\",\"ru\":\"\\u041a\\u0430\\u0431\\u0435\\u043b\\u0456 \\u0432\\u0438\\u0442\\u043e\\u0457 \\u043f\\u0430\\u0440\\u0438, \\u043f\\u0430\\u0442\\u0447-\\u043a\\u043e\\u0440\\u0434\\u0438\",\"ua\":\"\\u041a\\u0430\\u0431\\u0435\\u043b\\u0456 \\u0432\\u0438\\u0442\\u043e\\u0457 \\u043f\\u0430\\u0440\\u0438, \\u043f\\u0430\\u0442\\u0447-\\u043a\\u043e\\u0440\\u0434\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041a\\u0430\\u0431\\u0435\\u043b\\u0456 \\u0432\\u0438\\u0442\\u043e\\u0457 \\u043f\\u0430\\u0440\\u0438, \\u043f\\u0430\\u0442\\u0447-\\u043a\\u043e\\u0440\\u0434\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041a\\u0430\\u0431\\u0435\\u043b\\u0456 \\u0432\\u0438\\u0442\\u043e\\u0457 \\u043f\\u0430\\u0440\\u0438, \\u043f\\u0430\\u0442\\u0447-\\u043a\\u043e\\u0440\\u0434\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041a\\u0430\\u0