(701,	'{\"en\":\"\\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0430\\u0444\\u0438 \\u0456 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\",\"ru\":\"\\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0430\\u0444\\u0438 \\u0456 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\",\"ua\":\"\\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0430\\u0444\\u0438 \\u0456 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0430\\u0444\\u0438 \\u0456 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0430\\u0444\\u0438 \\u0456 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0456 \\u0448\\u0430\\u0444\\u0438 \\u0456 \\u0441\\u0442\\u0456\\u0439\\u043a\\u0438\"}'),
(702,	'{\"en\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 \\u0434\\u043b\\u044f \\u043f\\u0440\\u043e\\u043a\\u043b\\u0430\\u0434\\u043a\\u0438 \\u043c\\u0435\\u0440\\u0435\\u0436\\u0456\",\"ru\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 \\u0434\\u043b\\u044f \\u043f\\u0440\\u043e\\u043a\\u043b\\u0430\\u0434\\u043a\\u0438 \\u043c\\u0435\\u0440\\u0435\\u0436\\u0456\",\"ua\":\"\\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 \\u0434\\u043b\\u044f \\u043f\\u0440\\u043e\\u043a\\u043b\\u0430\\u0434\\u043a\\u0438 \\u043c\\u0435\\u0440\\u0435\\u0436\\u0456\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 \\u0434\\u043b\\u044f \\u043f\\u0440\\u043e\\u043a\\u043b\\u0430\\u0434\\u043a\\u0438 \\u043c\\u0435\\u0440\\u0435\\u0436\\u0456\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u043d\\u0442\\u0430\\u0436\\u043d\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0406\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442 \\u0434\\u043b\\u044f \\u043f\\u0440\\u043e\\u043a\\u043b\\u0430\\u0434\\u043a\\u0438 \\u043c\\u0435\\u0440\\u0435\\u0436\\u0456\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456, \\u0456\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442 > \\u041c\\u043e\\u0