(703,	'{\"en\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432\",\"ru\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432\",\"ua\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432\"}'),
(704,	'{\"en\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043a\\u0438\",\"ru\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043a\\u0438\",\"ua\":\"\\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043a\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043a\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432 > \\u0406\\u0433\\u0440\\u043e\\u0432\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043a\\u0438\"}'),
(705,	'{\"en\":\"\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ru\":\"\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ua\":\"\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432 > \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432 > \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432 > \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0440\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\"}'),
