(708,	'{\"en\":\"\\u0406\\u0433\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043e\\u043a \\u0456 \\u041f\\u041a\",\"ru\":\"\\u0406\\u0433\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043e\\u043a \\u0456 \\u041f\\u041a\",\"ua\":\"\\u0406\\u0433\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043e\\u043a \\u0456 \\u041f\\u041a\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432 > \\u0406\\u0433\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043e\\u043a \\u0456 \\u041f\\u041a\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432 > \\u0406\\u0433\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043e\\u043a \\u0456 \\u041f\\u041a\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0435\\u0439\\u043c\\u0435\\u0440\\u0456\\u0432 > \\u0406\\u0433\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043e\\u043a \\u0456 \\u041f\\u041a\"}'),
(709,	'{\"en\":\"\\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f\",\"ru\":\"\\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f\",\"ua\":\"\\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f\"}'),
