(712,	'{\"en\":\"3D-\\u0440\\u0443\\u0447\\u043a\\u0438\",\"ru\":\"3D-\\u0440\\u0443\\u0447\\u043a\\u0438\",\"ua\":\"3D-\\u0440\\u0443\\u0447\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > 3D-\\u0440\\u0443\\u0447\\u043a\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > 3D-\\u0440\\u0443\\u0447\\u043a\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > 3D-\\u0440\\u0443\\u0447\\u043a\\u0438\"}'),
(713,	'{\"en\":\"\\u041f\\u043b\\u043e\\u0442\\u0442\\u0435\\u0440\\u0438\",\"ru\":\"\\u041f\\u043b\\u043e\\u0442\\u0442\\u0435\\u0440\\u0438\",\"ua\":\"\\u041f\\u043b\\u043e\\u0442\\u0442\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u041f\\u043b\\u043e\\u0442\\u0442\\u0435\\u0440\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u041f\\u043b\\u043e\\u0442\\u0442\\u0435\\u0440\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u041f\\u043b\\u043e\\u0442\\u0442\\u0435\\u0440\\u0438\"}'),
(714,	'{\"en\":\"\\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ru\":\"\\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ua\":\"\\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\"}'),
(715,	'{\"en\":\"\\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u0411\\u0424\\u041f\",\"ru\":\"\\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u0411\\u0424\\u041f\",\"ua\":\"\\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u0411\\u0424\\u041f\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u0411\\u0424\\u041f\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u0411\\u0424\\u041f\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u041a\\u0430\\u0440\\u0442\\u0440\\u0438\\u0434\\u0436\\u0456 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0442\\u0430 \\u0411\\u0424\\u041f\"}'),
(716,	'{\"en\":\"\\u0427\\u043e\\u0440\\u043d\\u0438\\u043b\\u0430, \\u0442\\u043e\\u043d\\u0435\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0456 \\u0411\\u0424\\u041f\",\"ru\":\"\\u0427\\u043e\\u0440\\u043d\\u0438\\u043b\\u0430, \\u0442\\u043e\\u043d\\u0435\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0456 \\u0411\\u0424\\u041f\",\"ua\":\"\\u0427\\u043e\\u0440\\u043d\\u0438\\u043b\\u0430, \\u0442\\u043e\\u043d\\u0435\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0456 \\u0411\\u0424\\u041f\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0427\\u043e\\u0440\\u043d\\u0438\\u043b\\u0430, \\u0442\\u043e\\u043d\\u0435\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0456 \\u0411\\u0424\\u041f\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0427\\u043e\\u0440\\u043d\\u0438\\u043b\\u0430, \\u0442\\u043e\\u043d\\u0435\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0456 \\u0411\\u0424\\u041f\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0427\\u043e\\u0440\\u043d\\u0438\\u043b\\u0430, \\u0442\\u043e\\u043d\\u0435\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432 \\u0456 \\u0411\\u0424\\u041f\"}'),
(717,	'{\"en\":\"\\u0421\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0440\\u0432\\u043d\\u043e\\u0457 \\u043f\\u043e\\u0434\\u0430\\u0447\\u0456 \\u0447\\u043e\\u0440\\u043d\\u0438\\u043b\",\"ru\":\"\\u0421\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0440\\u0432\\u043d\\u043e\\u0457 \\u043f\\u043e\\u0434\\u0430\\u0447\\u0456 \\u0447\\u043e\\u0440\\u043d\\u0438\\u043b\",\"ua\":\"\\u0421\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0440\\u0432\\u043d\\u043e\\u0457 \\u043f\\u043e\\u0434\\u0430\\u0447\\u0456 \\u0447\\u043e\\u0440\\u043d\\u0438\\u043b\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0440\\u0432\\u043d\\u043e\\u0457 \\u043f\\u043e\\u0434\\u0430\\u0447\\u0456 \\u0447\\u043e\\u0440\\u043d\\u0438\\u043b\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0440\\u0432\\u043d\\u043e\\u0457 \\u043f\\u043e\\u0434\\u0430\\u0447\\u0456 \\u0447\\u043e\\u0440\\u043d\\u0438\\u043b\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0438\\u0441\\u0442\\u0435\\u043c\\u0438 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0440\\u0432\\u043d\\u043e\\u0457 \\u043f\\u043e\\u0434\\u0430\\u0447\\u0456 \\u0447\\u043e\\u0440\\u043d\\u0438\\u043b\"}'),
(718,	'{\"en\":\"\\u0414\\u0440\\u0443\\u043a\\u0443\\u044e\\u0447\\u0456 \\u0433\\u043e\\u043b\\u043e\\u0432\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0435\\u0432\\u0438\\u0445 \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432\",\"ru\":\"\\u0414\\u0440\\u0443\\u043a\\u0443\\u044e\\u0447\\u0456 \\u0433\\u043e\\u043b\\u043e\\u0432\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0435\\u0432\\u0438\\u0445 \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432\",\"ua\":\"\\u0414\\u0440\\u0443\\u043a\\u0443\\u044e\\u0447\\u0456 \\u0433\\u043e\\u043b\\u043e\\u0432\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0435\\u0432\\u0438\\u0445 \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0414\\u0440\\u0443\\u043a\\u0443\\u044e\\u0447\\u0456 \\u0433\\u043e\\u043b\\u043e\\u0432\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0435\\u0432\\u0438\\u0445 \\u043f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0456\\u0432\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u0438\\u043d\\u0442\\u0435\\u0440\\u0438, \\u0411\\u0424\\u041f > \\u0412\\u0438\\u0442\\u0440\\u0430\\u0442\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0414\\u0440\\u0443\\u043a\\u0443\\u044e\\u0447\\u0456 \\u0433\\u043e\\u043b\\u043e\\u0432\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0435\\u0432\\u0438\\u0445 \\u043f\\