(740,	'{\"en\":\"\\u0412\\u0435\\u0431-\\u043a\\u0430\\u043c\\u0435\\u0440\\u0438\",\"ru\":\"\\u0412\\u0435\\u0431-\\u043a\\u0430\\u043c\\u0435\\u0440\\u0438\",\"ua\":\"\\u0412\\u0435\\u0431-\\u043a\\u0430\\u043c\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u043d\\u0430 \\u043f\\u0435\\u0440\\u0438\\u0444\\u0435\\u0440\\u0456\\u044f > \\u0412\\u0435\\u0431-\\u043a\\u0430\\u043c\\u0435\\u0440\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u043d\\u0430 \\u043f\\u0435\\u0440\\u0438\\u0444\\u0435\\u0440\\u0456\\u044f > \\u0412\\u0435\\u0431-\\u043a\\u0430\\u043c\\u0435\\u0440\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u043d\\u0430 \\u043f\\u0435\\u0440\\u0438\\u0444\\u0435\\u0440\\u0456\\u044f > \\u0412\\u0435\\u0431-\\u043a\\u0430\\u043c\\u0435\\u0440\\u0438\"}'),
(741,	'{\"en\":\"\\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\"}'),
(742,	'{\"en\":\"\\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f > \\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f > \\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f > \\u041f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043d\\u0435 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0435\\u043d\\u043d\\u044f\"}'),
(743,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\"}'),
(744,	'{\"en\":\"\\u0414\\u0436\\u0435\\u0440\\u0435\\u043b\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0431\\u0456\\u0439\\u043d\\u043e\\u0433\\u043e \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f (\\u0414\\u0411\\u0416)\",\"ru\":\"\\u0414\\u0436\\u0435\\u0440\\u0435\\u043b\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0431\\u0456\\u0439\\u043d\\u043e\\u0433\\u043e \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f (\\u0414\\u0411\\u0416)\",\"ua\":\"\\u0414\\u0436\\u0435\\u0440\\u0435\\u043b\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0431\\u0456\\u0439\\u043d\\u043e\\u0433\\u043e \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f (\\u0414\\u0411\\u0416)\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0414\\u0436\\u0435\\u0440\\u0435\\u043b\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0431\\u0456\\u0439\\u043d\\u043e\\u0433\\u043e \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f (\\u0414\\u0411\\u0416)\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0414\\u0436\\u0435\\u0440\\u0435\\u043b\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0431\\u0456\\u0439\\u043d\\u043e\\u0433\\u043e \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f (\\u0414\\u0411\\u0416)\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0414\\u0436\\u0435\\u0440\\u0435\\u043b\\u0430 \\u0431\\u0435\\u0437\\u043f\\u0435\\u0440\\u0435\\u0431\\u0456\\u0439\\u043d\\u043e\\u0433\\u043e \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f (\\u0414\\u0411\\u0416)\"}'),
(745,	'{\"en\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0414\\u0411\\u0416\",\"ru\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0414\\u0411\\u0416\",\"ua\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0414\\u0411\\u0416\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0414\\u0411\\u0416\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0414\\u0411\\u0416\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0414\\u0411\\u0416\"}'),
(746,	'{\"en\":\"\\u0421\\u0442\\u0430\\u0431\\u0456\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438\",\"ru\":\"\\u0421\\u0442\\u0430\\u0431\\u0456\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438\",\"ua\":\"\\u0421\\u0442\\u0430\\u0431\\u0456\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0421\\u0442\\u0430\\u0431\\u0456\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0421\\u0442\\u0430\\u0431\\u0456\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0421\\u0442\\u0430\\u0431\\u0456\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438 \\u043d\\u0430\\u043f\\u0440\\u0443\\u0433\\u0438\"}'),
(747,	'{\"en\":\"\\u041c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u041c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u041c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u041c\\u0435\\u0440\\u0435\\u0436\\u0435\\u0432\\u0456 \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438, \\u043f\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0447\\u0456\"}'),
(748,	'{\"en\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\\u043a\\u0438\",\"ru\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\\u043a\\u0438\",\"ua\":\"\\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\\u043a\\u0438\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\\u043a\\u0438\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0410\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438, \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u0439\\u043a\\u0438\"}'),
(749,	'{\"en\":\"\\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 AA, AAA\",\"ru\":\"\\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 AA, AAA\",\"ua\":\"\\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 AA, AAA\"}',	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 AA, AAA\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 AA, AAA\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\'\\u044e\\u0442\\u0435\\u0440\\u0438, \\u041c\\u0435\\u0440\\u0435\\u0436\\u0456 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f > \\u0417\\u0430\\u0440\\u044f\\u0434\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457 \\u0434\\u043b\\u044f \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 AA, AAA\"}'),
(750,	'{\"en\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ru\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ua\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\"}',	'{\"en\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ru\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ua\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\"}'),
(751,	'{\"en\":\"\\u0413\\u0456\\u0442\\u0430\\u0440\\u0438\",\"ru\":\"\\u0413\\u0456\\u0442\\u0430\\u0440\\u0438\",\"ua\":\"\\u0413\\u0456\\u0442\\u0430\\u0440\\u0438\"}',	'{\"en\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438\",\"ru\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438\",\"ua\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438\"}'),
(752,	'{\"en\":\"\\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 \\u0430\\u043a\\u0443\\u0441\\u0442\\u0438\\u0447\\u043d\\u0456\",\"ru\":\"\\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 \\u0430\\u043a\\u0443\\u0441\\u0442\\u0438\\u0447\\u043d\\u0456\",\"ua\":\"\\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 \\u0430\\u043a\\u0443\\u0441\\u0442\\u0438\\u0447\\u043d\\u0456\"}',	'{\"en\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 \\u0430\\u043a\\u0443\\u0441\\u0442\\u0438\\u0447\\u043d\\u0456\",\"ru\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 \\u0430\\u043a\\u0443\\u0441\\u0442\\u0438\\u0447\\u043d\\u0456\",\"ua\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 \\u0430\\u043a\\u0443\\u0441\\u0442\\u0438\\u0447\\u043d\\u0456\"}'),
(753,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0442\\u0430\\u0440\\u0438\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0442\\u0430\\u0440\\u0438\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0442\\u0430\\u0440\\u0438\"}',	'{\"en\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0442\\u0430\\u0440\\u0438\",\"ru\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0442\\u0430\\u0440\\u0438\",\"ua\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0456\\u0442\\u0430\\u0440\\u0438\"}'),
(754,	'{\"en\":\"\\u0421\\u0442\\u0440\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0456\\u0442\\u0430\\u0440\",\"ru\":\"\\u0421\\u0442\\u0440\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0456\\u0442\\u0430\\u0440\",\"ua\":\"\\u0421\\u0442\\u0440\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0456\\u0442\\u0430\\u0440\"}',	'{\"en\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0421\\u0442\\u0440\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0456\\u0442\\u0430\\u0440\",\"ru\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0421\\u0442\\u0440\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0456\\u0442\\u0430\\u0440\",\"ua\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0421\\u0442\\u0440\\u0443\\u043d\\u0438 \\u0434\\u043b\\u044f \\u0433\\u0456\\u0442\\u0430\\u0440\"}'),
(755,	'{\"en\":\"\\u0413\\u0456\\u0442\\u0430\\u0440\\u043d\\u0456 \\u043f\\u0435\\u0434\\u0430\\u043b\\u0456 \\u0435\\u0444\\u0435\\u043a\\u0442\\u0456\\u0432\",\"ru\":\"\\u0413\\u0456\\u0442\\u0430\\u0440\\u043d\\u0456 \\u043f\\u0435\\u0434\\u0430\\u043b\\u0456 \\u0435\\u0444\\u0435\\u043a\\u0442\\u0456\\u0432\",\"ua\":\"\\u0413\\u0456\\u0442\\u0430\\u0440\\u043d\\u0456 \\u043f\\u0435\\u0434\\u0430\\u043b\\u0456 \\u0435\\u0444\\u0435\\u043a\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u043d\\u0456 \\u043f\\u0435\\u0434\\u0430\\u043b\\u0456 \\u0435\\u0444\\u0435\\u043a\\u0442\\u0456\\u0432\",\"ru\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u043d\\u0456 \\u043f\\u0435\\u0434\\u0430\\u043b\\u0456 \\u0435\\u0444\\u0435\\u043a\\u0442\\u0456\\u0432\",\"ua\":\"\\u041c\\u0443\\u0437\\u0438\\u0447\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u0438 > \\u0413\\u0456\\u0442\\u0430\\u0440\\u043d\\u0456 \\u043f\\u0435\\u0434\\u0430\\u043b\\u0456 \\u0435\\u0444\\u0435\\u043a\\u0442\\u0456\\u0432\"}'),
