(817,	'{\"en\":\"\\u0416\\u0456\\u043d\\u043e\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\",\"ru\":\"\\u0416\\u0456\\u043d\\u043e\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\",\"ua\":\"\\u0416\\u0456\\u043d\\u043e\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f > \\u0416\\u0456\\u043d\\u043e\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f > \\u0416\\u0456\\u043d\\u043e\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f > \\u0416\\u0456\\u043d\\u043e\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\"}'),
(818,	'{\"en\":\"\\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\",\"ru\":\"\\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\",\"ua\":\"\\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043f\\u0430\\u0440\\u0444\\u0443\\u043c\\u0435\\u0440\\u0456\\u044f\"}'),
(819,	'{\"en\":\"\\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ru\":\"\\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ua\":\"\\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443\"}'),
(820,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0442\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0442\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0442\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0442\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0442\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0442\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\"}'),
(821,	'{\"en\":\"\\u0406\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438)\",\"ru\":\"\\u0406\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438)\",\"ua\":\"\\u0406\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438)\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438)\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438)\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0406\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0438 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0438)\"}'),
(822,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0456\\u0432)\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0456\\u0432)\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0456\\u0432)\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0456\\u0432)\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0456\\u0432)\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0456\\u043d\\u0433\\u0430\\u043b\\u044f\\u0442\\u043e\\u0440\\u0456\\u0432 (\\u043d\\u0435\\u0431\\u0443\\u043b\\u0430\\u0439\\u0437\\u0435\\u0440\\u0456\\u0432)\"}'),
(823,	'{\"en\":\"\\u0422\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ru\":\"\\u0422\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ua\":\"\\u0422\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0422\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0422\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0422\\u043e\\u043d\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\"}'),
(824,	'{\"en\":\"\\u0421\\u0442\\u0435\\u0442\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438, \\u0444\\u043e\\u043d\\u0435\\u043d\\u0434\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ru\":\"\\u0421\\u0442\\u0435\\u0442\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438, \\u0444\\u043e\\u043d\\u0435\\u043d\\u0434\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ua\":\"\\u0421\\u0442\\u0435\\u0442\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438, \\u0444\\u043e\\u043d\\u0435\\u043d\\u0434\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0421\\u0442\\u0435\\u0442\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438, \\u0444\\u043e\\u043d\\u0435\\u043d\\u0434\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0421\\u0442\\u0435\\u0442\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438, \\u0444\\u043e\\u043d\\u0435\\u043d\\u0434\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0421\\u0442\\u0435\\u0442\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438, \\u0444\\u043e\\u043d\\u0435\\u043d\\u0434\\u043e\\u0441\\u043a\\u043e\\u043f\\u0438\"}'),
(825,	'{\"en\":\"\\u0413\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ru\":\"\\u0413\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ua\":\"\\u0413\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438\"}'),
(826,	'{\"en\":\"\\u0422\\u0435\\u0441\\u0442-\\u0441\\u043c\\u0443\\u0436\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0433\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\",\"ru\":\"\\u0422\\u0435\\u0441\\u0442-\\u0441\\u043c\\u0443\\u0436\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0433\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\",\"ua\":\"\\u0422\\u0435\\u0441\\u0442-\\u0441\\u043c\\u0443\\u0436\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0433\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0422\\u0435\\u0441\\u0442-\\u0441\\u043c\\u0443\\u0436\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0433\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0422\\u0435\\u0441\\u0442-\\u0441\\u043c\\u0443\\u0436\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0433\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0422\\u0435\\u0441\\u0442-\\u0441\\u043c\\u0443\\u0436\\u043a\\u0438 \\u0456 \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043e \\u0433\\u043b\\u044e\\u043a\\u043e\\u043c\\u0435\\u0442\\u0440\\u0456\\u0432\"}'),
(827,	'{\"en\":\"\\u0422\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456\",\"ru\":\"\\u0422\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456\",\"ua\":\"\\u0422\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0422\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0422\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0422\\u0435\\u0440\\u043c\\u043e\\u043c\\u0435\\u0442\\u0440\\u0438 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456\"}'),
(828,	'{\"en\":\"\\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0430\\u043c\\u043f\\u0438, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0430\\u043c\\u043f\\u0438, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0430\\u043c\\u043f\\u0438, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0430\\u043c\\u043f\\u0438, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0430\\u043c\\u043f\\u0438, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0430\\u043c\\u043f\\u0438, \\u0441\\u0442\\u0435\\u0440\\u0438\\u043b\\u0456\\u0437\\u0430\\u0442\\u043e\\u0440\\u0438\"}'),
(829,	'{\"en\":\"\\u0414\\u043e\\u0437\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438, \\u043d\\u0456\\u0442\\u0440\\u0430\\u0442\\u043e\\u043c\\u0456\\u0440\\u0438\",\"ru\":\"\\u0414\\u043e\\u0437\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438, \\u043d\\u0456\\u0442\\u0440\\u0430\\u0442\\u043e\\u043c\\u0456\\u0440\\u0438\",\"ua\":\"\\u0414\\u043e\\u0437\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438, \\u043d\\u0456\\u0442\\u0440\\u0430\\u0442\\u043e\\u043c\\u0456\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u0437\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438, \\u043d\\u0456\\u0442\\u0440\\u0430\\u0442\\u043e\\u043c\\u0456\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u0437\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438, \\u043d\\u0456\\u0442\\u0440\\u0430\\u0442\\u043e\\u043c\\u0456\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u0414\\u043e\\u0437\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438, \\u043d\\u0456\\u0442\\u0440\\u0430\\u0442\\u043e\\u043c\\u0456\\u0440\\u0438\"}'),
(830,	'{\"en\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0430\\u0448\\u043d\\u044c\\u043e\\u0457 \\u0442\\u0435\\u0440\\u0430\\u043f\\u0456\\u0457\",\"ru\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0430\\u0448\\u043d\\u044c\\u043e\\u0457 \\u0442\\u0435\\u0440\\u0430\\u043f\\u0456\\u0457\",\"ua\":\"\\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0430\\u0448\\u043d\\u044c\\u043e\\u0457 \\u0442\\u0435\\u0440\\u0430\\u043f\\u0456\\u0457\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0430\\u0448\\u043d\\u044c\\u043e\\u0457 \\u0442\\u0435\\u0440\\u0430\\u043f\\u0456\\u0457\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0430\\u0448\\u043d\\u044c\\u043e\\u0457 \\u0442\\u0435\\u0440\\u0430\\u043f\\u0456\\u0457\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0440\\u0438\\u043b\\u0430\\u0434\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0430\\u0448\\u043d\\u044c\\u043e\\u0457 \\u0442\\u0435\\u0440\\u0430\\u043f\\u0456\\u0457\"}'),
(831,	'{\"en\":\"\\u041a\\u0438\\u0441\\u043d\\u0435\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041a\\u0438\\u0441\\u043d\\u0435\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041a\\u0438\\u0441\\u043d\\u0435\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041a\\u0438\\u0441\\u043d\\u0435\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041a\\u0438\\u0441\\u043d\\u0435\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041a\\u0438\\u0441\\u043d\\u0435\\u0432\\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}'),
(832,	'{\"en\":\"\\u041f\\u0443\\u043b\\u044c\\u0441\\u043e\\u043a\\u0441\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ru\":\"\\u041f\\u0443\\u043b\\u044c\\u0441\\u043e\\u043a\\u0441\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ua\":\"\\u041f\\u0443\\u043b\\u044c\\u0441\\u043e\\u043a\\u0441\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0443\\u043b\\u044c\\u0441\\u043e\\u043a\\u0441\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0443\\u043b\\u044c\\u0441\\u043e\\u043a\\u0441\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u0434\\u043e\\u043c\\u0443 > \\u041f\\u0443\\u043b\\u044c\\u0441\\u043e\\u043a\\u0441\\u0438\\u043c\\u0435\\u0442\\u0440\\u0438\"}'),
(833,	'{\"en\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443\",\"ru\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443\",\"ua\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443\"}'),
(834,	'{\"en\":\"\\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f\",\"ru\":\"\\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f\",\"ua\":\"\\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f\"}'),
(835,	'{\"en\":\"\\u0411\\u0430\\u043d\\u0434\\u0430\\u0436\\u0456, \\u043e\\u0440\\u0442\\u0435\\u0437\\u0438, \\u043a\\u043e\\u0440\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u0411\\u0430\\u043d\\u0434\\u0430\\u0436\\u0456, \\u043e\\u0440\\u0442\\u0435\\u0437\\u0438, \\u043a\\u043e\\u0440\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u0411\\u0430\\u043d\\u0434\\u0430\\u0436\\u0456, \\u043e\\u0440\\u0442\\u0435\\u0437\\u0438, \\u043a\\u043e\\u0440\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f > \\u0411\\u0430\\u043d\\u0434\\u0430\\u0436\\u0456, \\u043e\\u0440\\u0442\\u0435\\u0437\\u0438, \\u043a\\u043e\\u0440\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f > \\u0411\\u0430\\u043d\\u0434\\u0430\\u0436\\u0456, \\u043e\\u0440\\u0442\\u0435\\u0437\\u0438, \\u043a\\u043e\\u0440\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f > \\u0411\\u0430\\u043d\\u0434\\u0430\\u0436\\u0456, \\u043e\\u0440\\u0442\\u0435\\u0437\\u0438, \\u043a\\u043e\\u0440\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\"}'),
(836,	'{\"en\":\"\\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0438\\u0447\\u043d\\u0435 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\",\"ru\":\"\\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0438\\u0447\\u043d\\u0435 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\",\"ua\":\"\\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0438\\u0447\\u043d\\u0435 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0438\\u0447\\u043d\\u0435 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0438\\u0447\\u043d\\u0435 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0438\\u0447\\u043d\\u0435 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\"}'),
(837,	'{\"en\":\"\\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u0443\\u0441\\u0442\\u0456\\u043b\\u043a\\u0438 (\\u0441\\u0443\\u043f\\u0456\\u043d\\u0430\\u0442\\u043e\\u0440\\u0438)\",\"ru\":\"\\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u0443\\u0441\\u0442\\u0456\\u043b\\u043a\\u0438 (\\u0441\\u0443\\u043f\\u0456\\u043d\\u0430\\u0442\\u043e\\u0440\\u0438)\",\"ua\":\"\\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u0443\\u0441\\u0442\\u0456\\u043b\\u043a\\u0438 (\\u0441\\u0443\\u043f\\u0456\\u043d\\u0430\\u0442\\u043e\\u0440\\u0438)\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u0443\\u0441\\u0442\\u0456\\u043b\\u043a\\u0438 (\\u0441\\u0443\\u043f\\u0456\\u043d\\u0430\\u0442\\u043e\\u0440\\u0438)\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0456\\u044f > \\u041e\\u0440\\u0442\\u043e\\u043f\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u0443\\u0441\\u0442\\u0456\\u043b\\u043a\\u0438 (\\u0441\\u0443\\u043f\\u0456\\u043d\\u0430\\u0442\\u043e\\u0440\\u0438)\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442