(838,	'{\"en\":\"\\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f\",\"ru\":\"\\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f\",\"ua\":\"\\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f\"}'),
(839,	'{\"en\":\"\\u0422\\u0440\\u043e\\u0441\\u0442\\u0438\\u043d\\u0438, \\u0445\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u043c\\u0438\\u043b\\u0438\\u0446\\u0456\",\"ru\":\"\\u0422\\u0440\\u043e\\u0441\\u0442\\u0438\\u043d\\u0438, \\u0445\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u043c\\u0438\\u043b\\u0438\\u0446\\u0456\",\"ua\":\"\\u0422\\u0440\\u043e\\u0441\\u0442\\u0438\\u043d\\u0438, \\u0445\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u043c\\u0438\\u043b\\u0438\\u0446\\u0456\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u0422\\u0440\\u043e\\u0441\\u0442\\u0438\\u043d\\u0438, \\u0445\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u043c\\u0438\\u043b\\u0438\\u0446\\u0456\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u0422\\u0440\\u043e\\u0441\\u0442\\u0438\\u043d\\u0438, \\u0445\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u043c\\u0438\\u043b\\u0438\\u0446\\u0456\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u0422\\u0440\\u043e\\u0441\\u0442\\u0438\\u043d\\u0438, \\u0445\\u043e\\u0434\\u0443\\u043d\\u043a\\u0438, \\u043c\\u0438\\u043b\\u0438\\u0446\\u0456\"}'),
(840,	'{\"en\":\"\\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u0456\\u0439\\u043d\\u0438\\u0439 \\u0442\\u0440\\u0438\\u043a\\u043e\\u0442\\u0430\\u0436\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u0456\\u0439\\u043d\\u0438\\u0439 \\u0442\\u0440\\u0438\\u043a\\u043e\\u0442\\u0430\\u0436\",\"ua\":\"\\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u0456\\u0439\\u043d\\u0438\\u0439 \\u0442\\u0440\\u0438\\u043a\\u043e\\u0442\\u0430\\u0436\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u0456\\u0439\\u043d\\u0438\\u0439 \\u0442\\u0440\\u0438\\u043a\\u043e\\u0442\\u0430\\u0436\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u0456\\u0439\\u043d\\u0438\\u0439 \\u0442\\u0440\\u0438\\u043a\\u043e\\u0442\\u0430\\u0436\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u041a\\u043e\\u043c\\u043f\\u0440\\u0435\\u0441\\u0456\\u0439\\u043d\\u0438\\u0439 \\u0442\\u0440\\u0438\\u043a\\u043e\\u0442\\u0430\\u0436\"}'),
(841,	'{\"en\":\"\\u0406\\u043d\\u0432\\u0430\\u043b\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\",\"ru\":\"\\u0406\\u043d\\u0432\\u0430\\u043b\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\",\"ua\":\"\\u0406\\u043d\\u0432\\u0430\\u043b\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u0406\\u043d\\u0432\\u0430\\u043b\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u0406\\u043d\\u0432\\u0430\\u043b\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u0406\\u043d\\u0432\\u0430\\u043b\\u0456\\u0434\\u043d\\u0456 \\u043a\\u043e\\u043b\\u044f\\u0441\\u043a\\u0438\"}'),
(842,	'{\"en\":\"\\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\",\"ru\":\"\\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\",\"ua\":\"\\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0456 \\u043b\\u0456\\u0436\\u043a\\u0430\"}'),
(843,	'{\"en\":\"\\u041f\\u0440\\u043e\\u0442\\u0438\\u043f\\u0440\\u043e\\u043b\\u0435\\u0436\\u043d\\u0435\\u0432\\u0456 \\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\",\"ru\":\"\\u041f\\u0440\\u043e\\u0442\\u0438\\u043f\\u0440\\u043e\\u043b\\u0435\\u0436\\u043d\\u0435\\u0432\\u0456 \\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\",\"ua\":\"\\u041f\\u0440\\u043e\\u0442\\u0438\\u043f\\u0440\\u043e\\u043b\\u0435\\u0436\\u043d\\u0435\\u0432\\u0456 \\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u041f\\u0440\\u043e\\u0442\\u0438\\u043f\\u0440\\u043e\\u043b\\u0435\\u0436\\u043d\\u0435\\u0432\\u0456 \\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u041f\\u0440\\u043e\\u0442\\u0438\\u043f\\u0440\\u043e\\u043b\\u0435\\u0436\\u043d\\u0435\\u0432\\u0456 \\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u041f\\u0440\\u043e\\u0442\\u0438\\u043f\\u0440\\u043e\\u043b\\u0435\\u0436\\u043d\\u0435\\u0432\\u0456 \\u043c\\u0430\\u0442\\u0440\\u0430\\u0446\\u0438 \\u0442\\u0430 \\u043f\\u043e\\u0434\\u0443\\u0448\\u043a\\u0438\"}'),
(844,	'{\"en\":\"\\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ru\":\"\\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ua\":\"\\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f > \\u0420\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u0439\\u043d\\u0456 \\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\"}'),
(845,	'{\"en\":\"\\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e\",\"ru\":\"\\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e\",\"ua\":\"\\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e\"}'),
(846,	'{\"en\":\"\\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430 \\u0456 \\u043f\\u0435\\u043b\\u044e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u0440\\u043e\\u0441\\u043b\\u0438\\u0445\",\"ru\":\"\\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430 \\u0456 \\u043f\\u0435\\u043b\\u044e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u0440\\u043e\\u0441\\u043b\\u0438\\u0445\",\"ua\":\"\\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430 \\u0456 \\u043f\\u0435\\u043b\\u044e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u0440\\u043e\\u0441\\u043b\\u0438\\u0445\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e > \\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430 \\u0456 \\u043f\\u0435\\u043b\\u044e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u0440\\u043e\\u0441\\u043b\\u0438\\u0445\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e > \\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430 \\u0456 \\u043f\\u0435\\u043b\\u044e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u0440\\u043e\\u0441\\u043b\\u0438\\u0445\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e > \\u041f\\u0456\\u0434\\u0433\\u0443\\u0437\\u043a\\u0438, \\u043f\\u0440\\u043e\\u0441\\u0442\\u0438\\u0440\\u0430\\u0434\\u043b\\u0430 \\u0456 \\u043f\\u0435\\u043b\\u044e\\u0448\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0434\\u043e\\u0440\\u043e\\u0441\\u043b\\u0438\\u0445\"}'),
(847,	'{\"en\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0430 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0443 (\\u043c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430)\",\"ru\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0430 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0443 (\\u043c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430)\",\"ua\":\"\\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0430 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0443 (\\u043c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430)\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0430 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0443 (\\u043c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430)\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0430 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0443 (\\u043c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430)\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0442\\u0430 \\u0440\\u0435\\u0430\\u0431\\u0456\\u043b\\u0456\\u0442\\u0430\\u0446\\u0456\\u044f \\u043d\\u0430 \\u0434\\u043e\\u043c\\u0443 > \\u0413\\u0456\\u0433\\u0456\\u0454\\u043d\\u0430 \\u0445\\u0432\\u043e\\u0440\\u043e\\u0433\\u043e > \\u0423\\u0441\\u0442\\u0430\\u0442\\u043a\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\\u043e\\u0457 \\u0442\\u0430 \\u0442\\u0443\\u0430\\u043b\\u0435\\u0442\\u0443 (\\u043c\\u0435\\u0434\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430)\"}'),
(848,	'{\"en\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ru\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ua\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\"}'),
(849,	'{\"en\":\"\\u0414\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\",\"ru\":\"\\u0414\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\",\"ua\":\"\\u0414\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\"}'),
