(856,	'{\"en\":\"\\u0413\\u0440\\u0435\\u0431\\u0456\\u043d\\u0446\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\",\"ru\":\"\\u0413\\u0440\\u0435\\u0431\\u0456\\u043d\\u0446\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\",\"ua\":\"\\u0413\\u0440\\u0435\\u0431\\u0456\\u043d\\u0446\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f > \\u0413\\u0440\\u0435\\u0431\\u0456\\u043d\\u0446\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f > \\u0413\\u0440\\u0435\\u0431\\u0456\\u043d\\u0446\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f > \\u0413\\u0440\\u0435\\u0431\\u0456\\u043d\\u0446\\u0456, \\u0449\\u0456\\u0442\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\"}'),
(857,	'{\"en\":\"\\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ru\":\"\\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ua\":\"\\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\"}'),
(858,	'{\"en\":\"\\u041a\\u0440\\u0435\\u043c \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ru\":\"\\u041a\\u0440\\u0435\\u043c \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ua\":\"\\u041a\\u0440\\u0435\\u043c \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u041a\\u0440\\u0435\\u043c \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u041a\\u0440\\u0435\\u043c \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u041a\\u0440\\u0435\\u043c \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\"}'),
(859,	'{\"en\":\"\\u0412\\u0430\\u0442\\u044f\\u043d\\u0456 \\u043f\\u0430\\u043b\\u0438\\u0447\\u043a\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\",\"ru\":\"\\u0412\\u0430\\u0442\\u044f\\u043d\\u0456 \\u043f\\u0430\\u043b\\u0438\\u0447\\u043a\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\",\"ua\":\"\\u0412\\u0430\\u0442\\u044f\\u043d\\u0456 \\u043f\\u0430\\u043b\\u0438\\u0447\\u043a\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0412\\u0430\\u0442\\u044f\\u043d\\u0456 \\u043f\\u0430\\u043b\\u0438\\u0447\\u043a\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0412\\u0430\\u0442\\u044f\\u043d\\u0456 \\u043f\\u0430\\u043b\\u0438\\u0447\\u043a\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0412\\u0430\\u0442\\u044f\\u043d\\u0456 \\u043f\\u0430\\u043b\\u0438\\u0447\\u043a\\u0438 \\u0456 \\u0434\\u0438\\u0441\\u043a\\u0438, \\u0441\\u0435\\u0440\\u0432\\u0435\\u0442\\u043a\\u0438\"}'),
(860,	'{\"en\":\"\\u041b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0442\\u043e\\u043d\\u0456\\u043a \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ru\":\"\\u041b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0442\\u043e\\u043d\\u0456\\u043a \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ua\":\"\\u041b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0442\\u043e\\u043d\\u0456\\u043a \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u041b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0442\\u043e\\u043d\\u0456\\u043a \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u041b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0442\\u043e\\u043d\\u0456\\u043a \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u041b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0442\\u043e\\u043d\\u0456\\u043a \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\"}'),
(861,	'{\"en\":\"\\u0421\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u043a\\u0430, \\u0444\\u043b\\u044e\\u0457\\u0434 \\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ru\":\"\\u0421\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u043a\\u0430, \\u0444\\u043b\\u044e\\u0457\\u0434 \\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ua\":\"\\u0421\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u043a\\u0430, \\u0444\\u043b\\u044e\\u0457\\u0434 \\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0421\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u043a\\u0430, \\u0444\\u043b\\u044e\\u0457\\u0434 \\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0421\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u043a\\u0430, \\u0444\\u043b\\u044e\\u0457\\u0434 \\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0421\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u043a\\u0430, \\u0444\\u043b\\u044e\\u0457\\u0434 \\u0456 \\u043a\\u043e\\u043d\\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u0442 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\"}'),
(862,	'{\"en\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u043d\\u044f\\u0442\\u0442\\u044f \\u043c\\u0430\\u043a\\u0456\\u044f\\u0436\\u0443\",\"ru\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u043d\\u044f\\u0442\\u0442\\u044f \\u043c\\u0430\\u043a\\u0456\\u044f\\u0436\\u0443\",\"ua\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u043d\\u044f\\u0442\\u0442\\u044f \\u043c\\u0430\\u043a\\u0456\\u044f\\u0436\\u0443\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u043d\\u044f\\u0442\\u0442\\u044f \\u043c\\u0430\\u043a\\u0456\\u044f\\u0436\\u0443\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u043d\\u044f\\u0442\\u0442\\u044f \\u043c\\u0430\\u043a\\u0456\\u044f\\u0436\\u0443\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u043d\\u044f\\u0442\\u0442\\u044f \\u043c\\u0430\\u043a\\u0456\\u044f\\u0436\\u0443\"}'),
(863,	'{\"en\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043c\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043c\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043c\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043c\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043c\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043c\\u0438\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(864,	'{\"en\":\"\\u041c\\u0430\\u0441\\u043a\\u0430 \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ru\":\"\\u041c\\u0430\\u0441\\u043a\\u0430 \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ua\":\"\\u041c\\u0430\\u0441\\u043a\\u0430 \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u041c\\u0430\\u0441\\u043a\\u0430 \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u041c\\u0430\\u0441\\u043a\\u0430 \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f > \\u041c\\u0430\\u0441\\u043a\\u0430 \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\"}'),
(865,	'{\"en\":\"\\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f\",\"ru\":\"\\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f\",\"ua\":\"\\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f\"}'),
(866,	'{\"en\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\",\"ru\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\",\"ua\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\"}'),
(867,	'{\"en\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\",\"ru\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\",\"ua\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441\\u0441\\u044f\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\"}'),
(868,	'{\"en\":\"\\u0421\\u0442\\u0430\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043c\\u0430\\u0437\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\",\"ru\":\"\\u0421\\u0442\\u0430\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043c\\u0430\\u0437\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\",\"ua\":\"\\u0421\\u0442\\u0430\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043c\\u0430\\u0437\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0421\\u0442\\u0430\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043c\\u0430\\u0437\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0421\\u0442\\u0430\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043c\\u0430\\u0437\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0421\\u0442\\u0430\\u043d\\u043a\\u0438, \\u043f\\u043e\\u043c\\u0430\\u0437\\u043a\\u0438 \\u0434\\u043b\\u044f \\u0433\\u043e\\u043b\\u0456\\u043d\\u043d\\u044f\"}'),
(869,	'{\"en\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\\u043c \\u0456 \\u0442\\u0456\\u043b\\u043e\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\",\"ru\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\\u043c \\u0456 \\u0442\\u0456\\u043b\\u043e\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\",\"ua\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\\u043c \\u0456 \\u0442\\u0456\\u043b\\u043e\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\\u043c \\u0456 \\u0442\\u0456\\u043b\\u043e\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\\u043c \\u0456 \\u0442\\u0456\\u043b\\u043e\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043e\\u0431\\u043b\\u0438\\u0447\\u0447\\u044f\\u043c \\u0456 \\u0442\\u0456\\u043b\\u043e\\u043c \\u0434\\u043b\\u044f \\u0447\\u043e\\u043b\\u043e\\u0432\\u0456\\u043a\\u0456\\u0432\"}'),
(870,	'{\"en\":\"\\u041c\\u0438\\u043b\\u043e \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\",\"ru\":\"\\u041c\\u0438\\u043b\\u043e \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\",\"ua\":\"\\u041c\\u0438\\u043b\\u043e \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u041c\\u0438\\u043b\\u043e \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u041c\\u0438\\u043b\\u043e \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0427\\u043e\\u043b\\u043e\\u0432\\u0456\\u0447\\u0430 \\u043b\\u0456\\u043d\\u0456\\u044f > \\u041c\\u0438\\u043b\\u043e \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\"}'),
(871,	'{\"en\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430\",\"ru\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430\",\"ua\":\"\\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430\"}'),
(872,	'{\"en\":\"\\u0417\\u0443\\u0431\\u043d\\u0430 \\u043f\\u0430\\u0441\\u0442\\u0430, \\u043e\\u043f\\u043e\\u043b\\u0456\\u0441\\u043a\\u0443\\u0432\\u0430\\u0447\",\"ru\":\"\\u0417\\u0443\\u0431\\u043d\\u0430 \\u043f\\u0430\\u0441\\u0442\\u0430, \\u043e\\u043f\\u043e\\u043b\\u0456\\u0441\\u043a\\u0443\\u0432\\u0430\\u0447\",\"ua\":\"\\u0417\\u0443\\u0431\\u043d\\u0430 \\u043f\\u0430\\u0441\\u0442\\u0430, \\u043e\\u043f\\u043e\\u043b\\u0456\\u0441\\u043a\\u0443\\u0432\\u0430\\u0447\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430 > \\u0417\\u0443\\u0431\\u043d\\u0430 \\u043f\\u0430\\u0441\\u0442\\u0430, \\u043e\\u043f\\u043e\\u043b\\u0456\\u0441\\u043a\\u0443\\u0432\\u0430\\u0447\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430 > \\u0417\\u0443\\u0431\\u043d\\u0430 \\u043f\\u0430\\u0441\\u0442\\u0430, \\u043e\\u043f\\u043e\\u043b\\u0456\\u0441\\u043a\\u0443\\u0432\\u0430\\u0447\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430 > \\u0417\\u0443\\u0431\\u043d\\u0430 \\u043f\\u0430\\u0441\\u0442\\u0430, \\u043e\\u043f\\u043e\\u043b\\u0456\\u0441\\u043a\\u0443\\u0432\\u0430\\u0447\"}'),
(873,	'{\"en\":\"\\u0417\\u0443\\u0431\\u043d\\u0456 \\u0449\\u0456\\u0442\\u043a\\u0438, \\u0444\\u043b\\u043e\\u0441\\u0438\",\"ru\":\"\\u0417\\u0443\\u0431\\u043d\\u0456 \\u0449\\u0456\\u0442\\u043a\\u0438, \\u0444\\u043b\\u043e\\u0441\\u0438\",\"ua\":\"\\u0417\\u0443\\u0431\\u043d\\u0456 \\u0449\\u0456\\u0442\\u043a\\u0438, \\u0444\\u043b\\u043e\\u0441\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430 > \\u0417\\u0443\\u0431\\u043d\\u0456 \\u0449\\u0456\\u0442\\u043a\\u0438, \\u0444\\u043b\\u043e\\u0441\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430 > \\u0417\\u0443\\u0431\\u043d\\u0456 \\u0449\\u0456\\u0442\\u043a\\u0438, \\u0444\\u043b\\u043e\\u0441\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043e\\u0433\\u043b\\u044f\\u0434 \\u0437\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0436\\u043d\\u0438\\u043d\\u043e\\u044e \\u0440\\u043e\\u0442\\u0430 > \\u0417\\u0443\\u0431\\u043d\\u0456 \\u0449\\u0456\\u0442\\u043a\\u0438, \\u0444\\u043b\\u043e\\u0441\\u0438\"}'),
(874,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438\"}'),
(875,	'{\"en\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0434\\u0437\\u0435\\u0440\\u043a\\u0430\\u043b\\u0430 \\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ru\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0434\\u0437\\u0435\\u0440\\u043a\\u0430\\u043b\\u0430 \\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ua\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0434\\u0437\\u0435\\u0440\\u043a\\u0430\\u043b\\u0430 \\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0434\\u0437\\u0435\\u0440\\u043a\\u0430\\u043b\\u0430 \\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0434\\u0437\\u0435\\u0440\\u043a\\u0430\\u043b\\u0430 \\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0434\\u0437\\u0435\\u0440\\u043a\\u0430\\u043b\\u0430 \\u0456 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\"}'),
(876,	'{\"en\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043a\\u0438\",\"ru\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043a\\u0438\",\"ua\":\"\\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043a\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043a\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u043a\\u0438\"}'),
(877,	'{\"en\":\"\\u0423\\u0424-\\u043b\\u0430\\u043c\\u043f\\u0438 \\u0456 \\u0432\\u0438\\u0442\\u044f\\u0436\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u0443\",\"ru\":\"\\u0423\\u0424-\\u043b\\u0430\\u043c\\u043f\\u0438 \\u0456 \\u0432\\u0438\\u0442\\u044f\\u0436\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u0443\",\"ua\":\"\\u0423\\u0424-\\u043b\\u0430\\u043c\\u043f\\u0438 \\u0456 \\u0432\\u0438\\u0442\\u044f\\u0436\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u0443\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0423\\u0424-\\u043b\\u0430\\u043c\\u043f\\u0438 \\u0456 \\u0432\\u0438\\u0442\\u044f\\u0436\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u0443\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0423\\u0424-\\u043b\\u0430\\u043c\\u043f\\u0438 \\u0456 \\u0432\\u0438\\u0442\\u044f\\u0436\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u0443\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u0423\\u0424-\\u043b\\u0430\\u043c\\u043f\\u0438 \\u0456 \\u0432\\u0438\\u0442\\u044f\\u0436\\u043a\\u0438 \\u0434\\u043b\\u044f \\u043c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u0443\"}'),
(878,	'{\"en\":\"\\u041c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u043d\\u0456, \\u043f\\u0435\\u0434\\u0438\\u043a\\u044e\\u0440\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 \\u0442\\u0430 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ru\":\"\\u041c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u043d\\u0456, \\u043f\\u0435\\u0434\\u0438\\u043a\\u044e\\u0440\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 \\u0442\\u0430 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ua\":\"\\u041c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u043d\\u0456, \\u043f\\u0435\\u0434\\u0438\\u043a\\u044e\\u0440\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 \\u0442\\u0430 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u043d\\u0456, \\u043f\\u0435\\u0434\\u0438\\u043a\\u044e\\u0440\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 \\u0442\\u0430 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u043d\\u0456, \\u043f\\u0435\\u0434\\u0438\\u043a\\u044e\\u0440\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 \\u0442\\u0430 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041c\\u0430\\u043d\\u0456\\u043a\\u044e\\u0440\\u043d\\u0456, \\u043f\\u0435\\u0434\\u0438\\u043a\\u044e\\u0440\\u043d\\u0456 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 \\u0442\\u0430 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0438\"}'),
(879,	'{\"en\":\"\\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438\",\"ru\":\"\\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438\",\"ua\":\"\\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0438 > \\u041d\\u043e\\u0436\\u0438\\u0446\\u0456 \\u0434\\u043b\\u044f \\u0441\\u0442\\u0440\\u0438\\u0436\\u043a\\u0438\"}'),
(880,	'{\"en\":\"\\u0414\\u043b\\u044f \\u0440\\u0443\\u043a\",\"ru\":\"\\u0414\\u043b\\u044f \\u0440\\u0443\\u043a\",\"ua\":\"\\u0414\\u043b\\u044f \\u0440\\u0443\\u043a\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0440\\u0443\\u043a\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0440\\u0443\\u043a\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0440\\u0443\\u043a\"}'),
(881,	'{\"en\":\"\\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0440\\u0443\\u043a\",\"ru\":\"\\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0440\\u0443\\u043a\",\"ua\":\"\\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0440\\u0443\\u043a\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0440\\u0443\\u043a > \\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0440\\u0443\\u043a\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0440\\u0443\\u043a > \\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0440\\u0443\\u043a\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0440\\u0443\\u043a > \\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0440\\u0443\\u043a\"}'),
(882,	'{\"en\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\\u0442\\u0456\\u0432\",\"ru\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\\u0442\\u0456\\u0432\",\"ua\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\\u0442\\u0456\\u0432\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0440\\u0443\\u043a > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\\u0442\\u0456\\u0432\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0440\\u0443\\u043a > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\\u0442\\u0456\\u0432\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0440\\u0443\\u043a > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\\u0442\\u0456\\u0432\"}'),
(883,	'{\"en\":\"\\u0414\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ru\":\"\\u0414\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ua\":\"\\u0414\\u043b\\u044f \\u043d\\u0456\\u0433\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043d\\u0456\\u0433\"}'),
(884,	'{\"en\":\"\\u041a\\u0440\\u0435\\u043c, \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ru\":\"\\u041a\\u0440\\u0435\\u043c, \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ua\":\"\\u041a\\u0440\\u0435\\u043c, \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043d\\u0456\\u0433 > \\u041a\\u0440\\u0435\\u043c, \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043d\\u0456\\u0433 > \\u041a\\u0440\\u0435\\u043c, \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043d\\u0456\\u0433 > \\u041a\\u0440\\u0435\\u043c, \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0456 \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\"}'),
(885,	'{\"en\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ru\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ua\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043d\\u0456\\u0433 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043d\\u0456\\u0433 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u043d\\u0456\\u0433 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u043d\\u0456\\u0433\"}'),
(886,	'{\"en\":\"\\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\",\"ru\":\"\\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\",\"ua\":\"\\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\"}'),
(887,	'{\"en\":\"\\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\",\"ru\":\"\\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\",\"ua\":\"\\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041a\\u0440\\u0435\\u043c \\u0456 \\u043b\\u043e\\u0441\\u044c\\u0439\\u043e\\u043d \\u0434\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430\"}'),
(888,	'{\"en\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0445\\u0443\\u0434\\u043d\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0445\\u0443\\u0434\\u043d\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0445\\u0443\\u0434\\u043d\\u0435\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0445\\u0443\\u0434\\u043d\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0445\\u0443\\u0434\\u043d\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0441\\u0445\\u0443\\u0434\\u043d\\u0435\\u043d\\u043d\\u044f\"}'),
(889,	'{\"en\":\"\\u0410\\u043d\\u0442\\u0438\\u043f\\u0435\\u0440\\u0441\\u043f\\u0456\\u0440\\u0430\\u043d\\u0442\\u0438 \\u0442\\u0430 \\u0434\\u0435\\u0437\\u043e\\u0434\\u043e\\u0440\\u0430\\u043d\\u0442\\u0438\",\"ru\":\"\\u0410\\u043d\\u0442\\u0438\\u043f\\u0435\\u0440\\u0441\\u043f\\u0456\\u0440\\u0430\\u043d\\u0442\\u0438 \\u0442\\u0430 \\u0434\\u0435\\u0437\\u043e\\u0434\\u043e\\u0440\\u0430\\u043d\\u0442\\u0438\",\"ua\":\"\\u0410\\u043d\\u0442\\u0438\\u043f\\u0435\\u0440\\u0441\\u043f\\u0456\\u0440\\u0430\\u043d\\u0442\\u0438 \\u0442\\u0430 \\u0434\\u0435\\u0437\\u043e\\u0434\\u043e\\u0440\\u0430\\u043d\\u0442\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0410\\u043d\\u0442\\u0438\\u043f\\u0435\\u0440\\u0441\\u043f\\u0456\\u0440\\u0430\\u043d\\u0442\\u0438 \\u0442\\u0430 \\u0434\\u0435\\u0437\\u043e\\u0434\\u043e\\u0440\\u0430\\u043d\\u0442\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0410\\u043d\\u0442\\u0438\\u043f\\u0435\\u0440\\u0441\\u043f\\u0456\\u0440\\u0430\\u043d\\u0442\\u0438 \\u0442\\u0430 \\u0434\\u0435\\u0437\\u043e\\u0434\\u043e\\u0440\\u0430\\u043d\\u0442\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0410\\u043d\\u0442\\u0438\\u043f\\u0435\\u0440\\u0441\\u043f\\u0456\\u0440\\u04