(890,	'{\"en\":\"\\u041c\\u0438\\u043b\\u043e, \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\",\"ru\":\"\\u041c\\u0438\\u043b\\u043e, \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\",\"ua\":\"\\u041c\\u0438\\u043b\\u043e, \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041c\\u0438\\u043b\\u043e, \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041c\\u0438\\u043b\\u043e, \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041c\\u0438\\u043b\\u043e, \\u0441\\u043a\\u0440\\u0430\\u0431 \\u0456 \\u0433\\u0435\\u043b\\u044c \\u0434\\u043b\\u044f \\u0434\\u0443\\u0448\\u0443\"}'),
(891,	'{\"en\":\"\\u0421\\u043e\\u043b\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\",\"ru\":\"\\u0421\\u043e\\u043b\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\",\"ua\":\"\\u0421\\u043e\\u043b\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0421\\u043e\\u043b\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0421\\u043e\\u043b\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0421\\u043e\\u043b\\u0456 \\u0442\\u0430 \\u043f\\u0456\\u043d\\u0430 \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d\"}'),
(892,	'{\"en\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0438\",\"ru\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0438\",\"ua\":\"\\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041d\\u0430\\u0431\\u043e\\u0440\\u0438 \\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0438\"}'),
(893,	'{\"en\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u0441\\u043c\\u0430\\u0433\\u0438\",\"ru\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u0441\\u043c\\u0430\\u0433\\u0438\",\"ua\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u0441\\u043c\\u0430\\u0433\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u0441\\u043c\\u0430\\u0433\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u0441\\u043c\\u0430\\u0433\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0437\\u0430\\u0441\\u043c\\u0430\\u0433\\u0438\"}'),
(894,	'{\"en\":\"\\u041f\\u0440\\u043e\\u043a\\u043b\\u0430\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043c\\u043f\\u043e\\u043d\\u0438\",\"ru\":\"\\u041f\\u0440\\u043e\\u043a\\u043b\\u0430\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043c\\u043f\\u043e\\u043d\\u0438\",\"ua\":\"\\u041f\\u0440\\u043e\\u043a\\u043b\\u0430\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043c\\u043f\\u043e\\u043d\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041f\\u0440\\u043e\\u043a\\u043b\\u0430\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043c\\u043f\\u043e\\u043d\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041f\\u0440\\u043e\\u043a\\u043b\\u0430\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043c\\u043f\\u043e\\u043d\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u041f\\u0440\\u043e\\u043a\\u043b\\u0430\\u0434\\u043a\\u0438, \\u0442\\u0430\\u043c\\u043f\\u043e\\u043d\\u0438\"}'),
(895,	'{\"en\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457 \\u0442\\u0430 \\u0434\\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457\",\"ru\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457 \\u0442\\u0430 \\u0434\\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457\",\"ua\":\"\\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457 \\u0442\\u0430 \\u0434\\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457 \\u0442\\u0430 \\u0434\\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457 \\u0442\\u0430 \\u0434\\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u041a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0414\\u043b\\u044f \\u0442\\u0456\\u043b\\u0430 > \\u0417\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457 \\u0442\\u0430 \\u0434\\u0435\\u043f\\u0456\\u043b\\u044f\\u0446\\u0456\\u0457\"}'),
(896,	'{\"en\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ru\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ua\":\"\\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\"}'),
(897,	'{\"en\":\"\\u041a\\u043e\\u043d\\u0442\\u0430\\u043a\\u0442\\u043d\\u0456 \\u043b\\u0456\\u043d\\u0437\\u0438\",\"ru\":\"\\u041a\\u043e\\u043d\\u0442\\u0430\\u043a\\u0442\\u043d\\u0456 \\u043b\\u0456\\u043d\\u0437\\u0438\",\"ua\":\"\\u041a\\u043e\\u043d\\u0442\\u0430\\u043a\\u0442\\u043d\\u0456 \\u043b\\u0456\\u043d\\u0437\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041a\\u043e\\u043d\\u0442\\u0430\\u043a\\u0442\\u043d\\u0456 \\u043b\\u0456\\u043d\\u0437\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041a\\u043e\\u043d\\u0442\\u0430\\u043a\\u0442\\u043d\\u0456 \\u043b\\u0456\\u043d\\u0437\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041a\\u043e\\u043d\\u0442\\u0430\\u043a\\u0442\\u043d\\u0456 \\u043b\\u0456\\u043d\\u0437\\u0438\"}'),
(898,	'{\"en\":\"\\u0420\\u043e\\u0437\\u0447\\u0438\\u043d\\u0438, \\u043a\\u0440\\u0430\\u043f\\u043b\\u0456, \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u0456\\u043d\\u0437\",\"ru\":\"\\u0420\\u043e\\u0437\\u0447\\u0438\\u043d\\u0438, \\u043a\\u0440\\u0430\\u043f\\u043b\\u0456, \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u0456\\u043d\\u0437\",\"ua\":\"\\u0420\\u043e\\u0437\\u0447\\u0438\\u043d\\u0438, \\u043a\\u0440\\u0430\\u043f\\u043b\\u0456, \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u0456\\u043d\\u0437\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0420\\u043e\\u0437\\u0447\\u0438\\u043d\\u0438, \\u043a\\u0440\\u0430\\u043f\\u043b\\u0456, \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u0456\\u043d\\u0437\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0420\\u043e\\u0437\\u0447\\u0438\\u043d\\u0438, \\u043a\\u0440\\u0430\\u043f\\u043b\\u0456, \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u0456\\u043d\\u0437\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0420\\u043e\\u0437\\u0447\\u0438\\u043d\\u0438, \\u043a\\u0440\\u0430\\u043f\\u043b\\u0456, \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043b\\u0456\\u043d\\u0437\"}'),
(899,	'{\"en\":\"\\u041f\\u043b\\u0430\\u0441\\u0442\\u0438\\u0440\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0432\'\\u044f\\u0437\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ru\":\"\\u041f\\u043b\\u0430\\u0441\\u0442\\u0438\\u0440\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0432\'\\u044f\\u0437\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ua\":\"\\u041f\\u043b\\u0430\\u0441\\u0442\\u0438\\u0440\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0432\'\\u044f\\u0437\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041f\\u043b\\u0430\\u0441\\u0442\\u0438\\u0440\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0432\'\\u044f\\u0437\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041f\\u043b\\u0430\\u0441\\u0442\\u0438\\u0440\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0432\'\\u044f\\u0437\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041f\\u043b\\u0430\\u0441\\u0442\\u0438\\u0440\\u0456, \\u043f\\u0435\\u0440\\u0435\\u0432\'\\u044f\\u0437\\u0443\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\"}'),
(900,	'{\"en\":\"\\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438\",\"ru\":\"\\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438\",\"ua\":\"\\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438\"}'),
(901,	'{\"en\":\"\\u0411\\u0435\\u0440\\u0443\\u0448\\u0456\",\"ru\":\"\\u0411\\u0435\\u0440\\u0443\\u0448\\u0456\",\"ua\":\"\\u0411\\u0435\\u0440\\u0443\\u0448\\u0456\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0411\\u0435\\u0440\\u0443\\u0448\\u0456\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0411\\u0435\\u0440\\u0443\\u0448\\u0456\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0411\\u0435\\u0440\\u0443\\u0448\\u0456\"}'),
(902,	'{\"en\":\"\\u0411\\u0456\\u043e\\u043b\\u043e\\u0433\\u0456\\u0447\\u043d\\u043e \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0434\\u043e\\u0431\\u0430\\u0432\\u043a\\u0438 (\\u0411\\u0410\\u0414)\",\"ru\":\"\\u0411\\u0456\\u043e\\u043b\\u043e\\u0433\\u0456\\u0447\\u043d\\u043e \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0434\\u043e\\u0431\\u0430\\u0432\\u043a\\u0438 (\\u0411\\u0410\\u0414)\",\"ua\":\"\\u0411\\u0456\\u043e\\u043b\\u043e\\u0433\\u0456\\u0447\\u043d\\u043e \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0434\\u043e\\u0431\\u0430\\u0432\\u043a\\u0438 (\\u0411\\u0410\\u0414)\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0411\\u0456\\u043e\\u043b\\u043e\\u0433\\u0456\\u0447\\u043d\\u043e \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0434\\u043e\\u0431\\u0430\\u0432\\u043a\\u0438 (\\u0411\\u0410\\u0414)\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0411\\u0456\\u043e\\u043b\\u043e\\u0433\\u0456\\u0447\\u043d\\u043e \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0434\\u043e\\u0431\\u0430\\u0432\\u043a\\u0438 (\\u0411\\u0410\\u0414)\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u043e\\u0432\\u0430\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0411\\u0456\\u043e\\u043b\\u043e\\u0433\\u0456\\u0447\\u043d\\u043e \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456 \\u0434\\u043e\\u0431\\u0430\\u0432\\u043a\\u0438 (\\u0411\\u0410\\u0414)\"}'),
(903,	'{\"en\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ru\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ua\":\"\\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443\"}'),
(904,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0440\\u0456\\u043b\\u043a\\u0438\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0440\\u0456\\u043b\\u043a\\u0438\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0440\\u0456\\u043b\\u043a\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0440\\u0456\\u043b\\u043a\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0440\\u0456\\u043b\\u043a\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0422\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 \\u0434\\u043b\\u044f \\u043a\\u0440\\u0430\\u0441\\u0438 \\u0456 \\u0434\\u043e\\u0433\\u043b\\u044f\\u0434\\u0443 > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0440\\u0456\\u043b\\u043a\\u0438\"}'),
(905,	'{\"en\":\"\\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432\",\"ru\":\"\\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432\",\"ua\":\"\\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432\"}'),
(906,	'{\"en\":\"\\u0412\\u0438\\u0440\\u043e\\u0431\\u0438 \\u0437 \\u0433\\u0443\\u043c\\u0438 \\u0456 \\u043b\\u0430\\u0442\\u0435\\u043a\\u0441\\u0443\",\"ru\":\"\\u0412\\u0438\\u0440\\u043e\\u0431\\u0438 \\u0437 \\u0433\\u0443\\u043c\\u0438 \\u0456 \\u043b\\u0430\\u0442\\u0435\\u043a\\u0441\\u0443\",\"ua\":\"\\u0412\\u0438\\u0440\\u043e\\u0431\\u0438 \\u0437 \\u0433\\u0443\\u043c\\u0438 \\u0456 \\u043b\\u0430\\u0442\\u0435\\u043a\\u0441\\u0443\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u0412\\u0438\\u0440\\u043e\\u0431\\u0438 \\u0437 \\u0433\\u0443\\u043c\\u0438 \\u0456 \\u043b\\u0430\\u0442\\u0435\\u043a\\u0441\\u0443\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u0412\\u0438\\u0440\\u043e\\u0431\\u0438 \\u0437 \\u0433\\u0443\\u043c\\u0438 \\u0456 \\u043b\\u0430\\u0442\\u0435\\u043a\\u0441\\u0443\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u0412\\u0438\\u0440\\u043e\\u0431\\u0438 \\u0437 \\u0433\\u0443\\u043c\\u0438 \\u0456 \\u043b\\u0430\\u0442\\u0435\\u043a\\u0441\\u0443\"}'),
(907,	'{\"en\":\"\\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0438\\u0439 \\u043e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\",\"ru\":\"\\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0438\\u0439 \\u043e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\",\"ua\":\"\\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0438\\u0439 \\u043e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0438\\u0439 \\u043e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0438\\u0439 \\u043e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u041c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0438\\u0439 \\u043e\\u0434\\u044f\\u0433 \\u0442\\u0430 \\u0432\\u0437\\u0443\\u0442\\u0442\\u044f\"}'),
(908,	'{\"en\":\"\\u041c\\u0430\\u0441\\u043a\\u0438 \\u0456 \\u0440\\u0435\\u0441\\u043f\\u0456\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041c\\u0430\\u0441\\u043a\\u0438 \\u0456 \\u0440\\u0435\\u0441\\u043f\\u0456\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041c\\u0430\\u0441\\u043a\\u0438 \\u0456 \\u0440\\u0435\\u0441\\u043f\\u0456\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u041c\\u0430\\u0441\\u043a\\u0438 \\u0456 \\u0440\\u0435\\u0441\\u043f\\u0456\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u041c\\u0430\\u0441\\u043a\\u0438 \\u0456 \\u0440\\u0435\\u0441\\u043f\\u0456\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u041c\\u0430\\u0441\\u043a\\u0438 \\u0456 \\u0440\\u0435\\u0441\\u043f\\u0456\\u0440\\u0430\\u0442\\u043e\\u0440\\u0438\"}'),
(909,	'{\"en\":\"\\u0410\\u043d\\u0442\\u0438\\u0441\\u0435\\u043f\\u0442\\u0438\\u043a\\u0438 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0434\\u0435\\u0437\\u0456\\u043d\\u0444\\u0435\\u043a\\u0446\\u0456\\u0457\",\"ru\":\"\\u0410\\u043d\\u0442\\u0438\\u0441\\u0435\\u043f\\u0442\\u0438\\u043a\\u0438 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0434\\u0435\\u0437\\u0456\\u043d\\u0444\\u0435\\u043a\\u0446\\u0456\\u0457\",\"ua\":\"\\u0410\\u043d\\u0442\\u0438\\u0441\\u0435\\u043f\\u0442\\u0438\\u043a\\u0438 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0434\\u0435\\u0437\\u0456\\u043d\\u0444\\u0435\\u043a\\u0446\\u0456\\u0457\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u0410\\u043d\\u0442\\u0438\\u0441\\u0435\\u043f\\u0442\\u0438\\u043a\\u0438 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0434\\u0435\\u0437\\u0456\\u043d\\u0444\\u0435\\u043a\\u0446\\u0456\\u0457\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u0410\\u043d\\u0442\\u0438\\u0441\\u0435\\u043f\\u0442\\u0438\\u043a\\u0438 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0434\\u0435\\u0437\\u0456\\u043d\\u0444\\u0435\\u043a\\u0446\\u0456\\u0457\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u0410\\u043d\\u0442\\u0438\\u0441\\u0435\\u043f\\u0442\\u0438\\u043a\\u0438 \\u0456 \\u0437\\u0430\\u0441\\u043e\\u0431\\u0438 \\u0434\\u043b\\u044f \\u0434\\u0435\\u0437\\u0456\\u043d\\u0444\\u0435\\u043a\\u0446\\u0456\\u0457\"}'),
(910,	'{\"en\":\"\\u041e\\u0434\\u043d\\u043e\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0430 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0456\\u044f\",\"ru\":\"\\u041e\\u0434\\u043d\\u043e\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0430 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0456\\u044f\",\"ua\":\"\\u041e\\u0434\\u043d\\u043e\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0430 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0456\\u044f\"}',	'{\"en\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u041e\\u0434\\u043d\\u043e\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0430 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0456\\u044f\",\"ru\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u041e\\u0434\\u043d\\u043e\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0430 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0456\\u044f\",\"ua\":\"\\u041a\\u0440\\u0430\\u0441\\u0430 \\u0456 \\u0437\\u0434\\u043e\\u0440\\u043e\\u0432\'\\u044f > \\u0417\\u0430\\u0445\\u0438\\u0441\\u0442 \\u0432\\u0456\\u0434 \\u0432\\u0456\\u0440\\u0443\\u0441\\u0456\\u0432 > \\u041e\\u0434\\u043d\\u043e\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430 \\u043c\\u0435\\u0434\\u0438\\u0447\\u043d\\u0430 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0456\\u044f\"}'),
(911,	'{\"en\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ru\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ua\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\"}',	'{\"en\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ru\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\",\"ua\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438\"}'),
