(962,	'{\"en\":\"\\u0417\\u0430\\u0442\\u0438\\u0440\\u043a\\u0438 (\\u0444\\u0443\\u0433\\u0438) \\u0434\\u043b\\u044f \\u043f\\u043b\\u0438\\u0442\\u043a\\u0438\",\"ru\":\"\\u0417\\u0430\\u0442\\u0438\\u0440\\u043a\\u0438 (\\u0444\\u0443\\u0433\\u0438) \\u0434\\u043b\\u044f \\u043f\\u043b\\u0438\\u0442\\u043a\\u0438\",\"ua\":\"\\u0417\\u0430\\u0442\\u0438\\u0440\\u043a\\u0438 (\\u0444\\u0443\\u0433\\u0438) \\u0434\\u043b\\u044f \\u043f\\u043b\\u0438\\u0442\\u043a\\u0438\"}',	'{\"en\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u041e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0417\\u0430\\u0442\\u0438\\u0440\\u043a\\u0438 (\\u0444\\u0443\\u0433\\u0438) \\u0434\\u043b\\u044f \\u043f\\u043b\\u0438\\u0442\\u043a\\u0438\",\"ru\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u041e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0417\\u0430\\u0442\\u0438\\u0440\\u043a\\u0438 (\\u0444\\u0443\\u0433\\u0438) \\u0434\\u043b\\u044f \\u043f\\u043b\\u0438\\u0442\\u043a\\u0438\",\"ua\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u041e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0417\\u0430\\u0442\\u0438\\u0440\\u043a\\u0438 (\\u0444\\u0443\\u0433\\u0438) \\u0434\\u043b\\u044f \\u043f\\u043b\\u0438\\u0442\\u043a\\u0438\"}'),
(963,	'{\"en\":\"\\u0412\\u0430\\u0433\\u043e\\u043d\\u043a\\u0430 \\u043f\\u043b\\u0430\\u0441\\u0442\\u0438\\u043a\\u043e\\u0432\\u0430\",\"ru\":\"\\u0412\\u0430\\u0433\\u043e\\u043d\\u043a\\u0430 \\u043f\\u043b\\u0430\\u0441\\u0442\\u0438\\u043a\\u043e\\u0432\\u0430\",\"ua\":\"\\u0412\\u0430\\u0433\\u043e\\u043d\\u043a\\u0430 \\u043f\\u043b\\u0430\\u0441\\u0442\\u0438\\u043a\\u043e\\u0432\\u0430\"}',	'{\"en\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u041e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0412\\u0430\\u0433\\u043e\\u043d\\u043a\\u0430 \\u043f\\u043b\\u0430\\u0441\\u0442\\u0438\\u043a\\u043e\\u0432\\u0430\",\"ru\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u041e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0412\\u0430\\u0433\\u043e\\u043d\\u043a\\u0430 \\u043f\\u043b\\u0430\\u0441\\u0442\\u0438\\u043a\\u043e\\u0432\\u0430\",\"ua\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u041e\\u0437\\u0434\\u043e\\u0431\\u043b\\u044e\\u0432\\u0430\\u043b\\u044c\\u043d\\u0456 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0412\\u0430\\u0433\\u043e\\u043d\\u043a\\u0430 \\u043f\\u043b\\u0430\\u0441\\u0442\\u0438\\u043a\\u043e\\u0432\\u0430\"}'),
