(988,	'{\"en\":\"\\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u0432\\u043e\\u0434\\u0438\",\"ru\":\"\\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u0432\\u043e\\u0434\\u0438\",\"ua\":\"\\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u0432\\u043e\\u0434\\u0438\"}',	'{\"en\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u0432\\u043e\\u0434\\u0438\",\"ru\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u0432\\u043e\\u0434\\u0438\",\"ua\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0424\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438-\\u043e\\u0447\\u0438\\u0449\\u0443\\u0432\\u0430\\u0447\\u0456 \\u0432\\u043e\\u0434\\u0438\"}'),
(989,	'{\"en\":\"\\u041c\\u0430\\u0433\\u0456\\u0441\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438, \\u0440\\u0435\\u0434\\u0443\\u043a\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ru\":\"\\u041c\\u0430\\u0433\\u0456\\u0441\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438, \\u0440\\u0435\\u0434\\u0443\\u043a\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ua\":\"\\u041c\\u0430\\u0433\\u0456\\u0441\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438, \\u0440\\u0435\\u0434\\u0443\\u043a\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u0434\\u0438\"}',	'{\"en\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041c\\u0430\\u0433\\u0456\\u0441\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438, \\u0440\\u0435\\u0434\\u0443\\u043a\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ru\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u041c\\u0430\\u0433\\u0456\\u0441\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u0456 \\u0444\\u0456\\u043b\\u044c\\u0442\\u0440\\u0438, \\u0440\\u0435\\u0434\\u0443\\u043a\\u0442\\u043e\\u0440\\u0438 \\u0434\\u043b\\u044f \\u0432\\u043e\\u0434\\u0438\",\"ua\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u