(990,	'{\"en\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0434\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0434\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0434\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0434\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0434\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0434\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431