(991,	'{\"en\":\"\\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d \\u0456 \\u0434\\u0443\\u0448\\u043e\\u0432\\u0438\\u0445 \\u043a\\u0430\\u0431\\u0456\\u043d\",\"ru\":\"\\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d \\u0456 \\u0434\\u0443\\u0448\\u043e\\u0432\\u0438\\u0445 \\u043a\\u0430\\u0431\\u0456\\u043d\",\"ua\":\"\\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d \\u0456 \\u0434\\u0443\\u0448\\u043e\\u0432\\u0438\\u0445 \\u043a\\u0430\\u0431\\u0456\\u043d\"}',	'{\"en\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0434\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f > \\u0414\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u0432\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u043d\\u0430\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0432\\u0430\\u043d\\u043d \\u0456 \\u0434\\u0443\\u0448\\u043e\\u0432\\u0438\\u0445 \\u043a\\u0430\\u0431\\u0456\\u043d\",\"ru\":\"\\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430, \\u0411\\u0443\\u0434\\u043c\\u0430\\u0442\\u0435\\u0440\\u0456\\u0430\\u043b\\u0438 > \\u0421\\u0430\\u043d\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0430 > \\u0410\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438 \\u0442\\u0430 \\u0434\\u043e\\u0434\\u0430\\u0442\\u043a\\u043e\\u043