(1121,	'{\"en\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\",\"ru\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\",\"ua\":\"\\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442\"}'),
(1122,	'{\"en\":\"\\u0413\\u0456\\u0440\\u043e\\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438, \\u0433\\u0456\\u0440\\u043e\\u0431\\u043e\\u0440\\u0434\\u0438\",\"ru\":\"\\u0413\\u0456\\u0440\\u043e\\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438, \\u0433\\u0456\\u0440\\u043e\\u0431\\u043e\\u0440\\u0434\\u0438\",\"ua\":\"\\u0413\\u0456\\u0440\\u043e\\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438, \\u0433\\u0456\\u0440\\u043e\\u0431\\u043e\\u0440\\u0434\\u0438\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442 > \\u0413\\u0456\\u0440\\u043e\\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438, \\u0433\\u0456\\u0440\\u043e\\u0431\\u043e\\u0440\\u0434\\u0438\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0442\\u0440\\u0430\\u043d\\u0441\\u043f\\u043e\\u0440\\u0442 > \\u0413\\u0456\\u0440\\u043e\\u0441\\u043a\\u0443\\u0442\\u0435\\u0440\\u0438, \\u0433\\u0456\\u0440\\u043e\\u0431\\u043e\\u0440\\u0434\\u0438\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0415\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0442\\u0440\\u0430\\u043d\\u0441\\