(1131,	'{\"en\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0442\\u0435\\u043d\\u0456\\u0441 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ru\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0442\\u0435\\u043d\\u0456\\u0441 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ua\":\"\\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0442\\u0435\\u043d\\u0456\\u0441 (\\u0440\\u0456\\u0437\\u043d\\u0435)\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u0438 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0442\\u0435\\u043d\\u0456\\u0441 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u0438 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0442\\u0435\\u043d\\u0456\\u0441 (\\u0440\\u0456\\u0437\\u043d\\u0435)\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0406\\u0433\\u0440\\u0438 > \\u041d\\u0430\\u0441\\u0442\\u0456\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0442\\u0435\\u043d\\u0456\\u0441 (\\u0440\\u0456\\u0437\\u043d\\u0435)\"}'),
