(1143,	'{\"en\":\"\\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\",\"ru\":\"\\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\",\"ua\":\"\\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0417\\u0438\\u043c\\u043e\\u0432\\u0438\\u0439 \\u0441\\u043f\\u043e\\u0440\\u0442 > \\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0417\\u0438\\u043c\\u043e\\u0432\\u0438\\u0439 \\u0441\\u043f\\u043e\\u0440\\u0442 > \\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0417\\u0438\\u043c\\u043e\\u0432\\u0438\\u0439 \\u0441\\u043f\\u043e\\u0440\\u0442 > \\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u0448\\u043e\\u043b\\u043e\\u043c\\u0438\"}'),
(1144,	'{\"en\":\"\\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u043c\\u0430\\u0441\\u043a\\u0438\",\"ru\":\"\\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u043c\\u0430\\u0441\\u043a\\u0438\",\"ua\":\"\\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u043c\\u0430\\u0441\\u043a\\u0438\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0417\\u0438\\u043c\\u043e\\u0432\\u0438\\u0439 \\u0441\\u043f\\u043e\\u0440\\u0442 > \\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u043c\\u0430\\u0441\\u043a\\u0438\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0417\\u0438\\u043c\\u043e\\u0432\\u0438\\u0439 \\u0441\\u043f\\u043e\\u0440\\u0442 > \\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u043c\\u0430\\u0441\\u043a\\u0438\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0417\\u0438\\u043c\\u043e\\u0432\\u0438\\u0439 \\u0441\\u043f\\u043e\\u0440\\u0442 > \\u0413\\u0456\\u0440\\u0441\\u044c\\u043a\\u043e\\u043b\\u0438\\u0436\\u043d\\u0456 \\u043c\\u0430\\u0441\\u043a\\u0438\"}'),
