(1146,	'{\"en\":\"\\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ru\":\"\\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ua\":\"\\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\"}'),
(1147,	'{\"en\":\"\\u0412\\u0435\\u043b\\u043e\\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ru\":\"\\u0412\\u0435\\u043b\\u043e\\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ua\":\"\\u0412\\u0435\\u043b\\u043e\\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438 > \\u0412\\u0435\\u043b\\u043e\\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438 > \\u0412\\u0435\\u043b\\u043e\\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438 > \\u0412\\u0435\\u043b\\u043e\\u0442\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438\"}'),
(1148,	'{\"en\":\"\\u041e\\u0440\\u0431\\u0456\\u0442\\u0440\\u0435\\u043a\\u0438\",\"ru\":\"\\u041e\\u0440\\u0431\\u0456\\u0442\\u0440\\u0435\\u043a\\u0438\",\"ua\":\"\\u041e\\u0440\\u0431\\u0456\\u0442\\u0440\\u0435\\u043a\\u0438\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438 > \\u041e\\u0440\\u0431\\u0456\\u0442\\u0440\\u0435\\u043a\\u0438\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438 > \\u041e\\u0440\\u0431\\u0456\\u0442\\u0440\\u0435\\u043a\\u0438\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438 > \\u041e\\u0440\\u0431\\u0456\\u0442\\u0440\\u0435\\u043a\\u0438\"}'),
(1149,	'{\"en\":\"\\u0411\\u0456\\u0433\\u043e\\u0432\\u0456 \\u0434\\u043e\\u0440\\u0456\\u0436\\u043a\\u0438\",\"ru\":\"\\u0411\\u0456\\u0433\\u043e\\u0432\\u0456 \\u0434\\u043e\\u0440\\u0456\\u0436\\u043a\\u0438\",\"ua\":\"\\u0411\\u0456\\u0433\\u043e\\u0432\\u0456 \\u0434\\u043e\\u0440\\u0456\\u0436\\u043a\\u0438\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438 > \\u0411\\u0456\\u0433\\u043e\\u0432\\u0456 \\u0434\\u043e\\u0440\\u0456\\u0436\\u043a\\u0438\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438 > \\u0411\\u0456\\u0433\\u043e\\u0432\\u0456 \\u0434\\u043e\\u0440\\u0456\\u0436\\u043a\\u0438\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u0422\\u0440\\u0435\\u043d\\u0430\\u0436\\u0435\\u0440\\u0438 > \\u0411\\u0456\\u0433\\u043e\\u0432\\u0456 \\u0434\\u043e\\u0440\\u0456\\u0436\\u043a\\u0438\"}'),
