(1187,	'{\"en\":\"\\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u041f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u041f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u0421\\u043f\\u043e\\u0440\\u0442 > \\u041f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f > \\u041e\\u043a\\u0443\\u043b\\u044f\\u0440\\u0438 \\u0434\\u043b\\u044f \\u043f\\u043b\\u0430\\u0432\\u0430\\u043d\\u043d\\u044f\"}'),
(1188,	'{\"en\":\"\\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f\"}'),
(1189,	'{\"en\":\"\\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u043f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0456 \\u0440\\u0435\\u0432\\u043e\\u043b\\u044c\\u0432\\u0435\\u0440\\u0438\",\"ru\":\"\\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u043f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0456 \\u0440\\u0435\\u0432\\u043e\\u043b\\u044c\\u0432\\u0435\\u0440\\u0438\",\"ua\":\"\\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u043f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0456 \\u0440\\u0435\\u0432\\u043e\\u043b\\u044c\\u0432\\u0435\\u0440\\u0438\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u043f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0456 \\u0440\\u0435\\u0432\\u043e\\u043b\\u044c\\u0432\\u0435\\u0440\\u0438\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u043f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0456 \\u0440\\u0435\\u0432\\u043e\\u043b\\u044c\\u0432\\u0435\\u0440\\u0438\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u043f\\u0456\\u0441\\u0442\\u043e\\u043b\\u0435\\u0442\\u0438 \\u0456 \\u0440\\u0435\\u0432\\u043e\\u043b\\u044c\\u0432\\u0435\\u0440\\u0438\"}'),
(1190,	'{\"en\":\"\\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0433\\u0432\\u0438\\u043d\\u0442\\u0456\\u0432\\u043a\\u0438\",\"ru\":\"\\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0433\\u0432\\u0438\\u043d\\u0442\\u0456\\u0432\\u043a\\u0438\",\"ua\":\"\\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0433\\u0432\\u0438\\u043d\\u0442\\u0456\\u0432\\u043a\\u0438\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0433\\u0432\\u0438\\u043d\\u0442\\u0456\\u0432\\u043a\\u0438\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0433\\u0432\\u0438\\u043d\\u0442\\u0456\\u0432\\u043a\\u0438\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0433\\u0432\\u0438\\u043d\\u0442\\u0456\\u0432\\u043a\\u0438\"}'),
(1191,	'{\"en\":\"\\u0411\\u043e\\u0454\\u043f\\u0440\\u0438\\u043f\\u0430\\u0441\\u0438 \\u0434\\u043e \\u043f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0438\",\"ru\":\"\\u0411\\u043e\\u0454\\u043f\\u0440\\u0438\\u043f\\u0430\\u0441\\u0438 \\u0434\\u043e \\u043f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0438\",\"ua\":\"\\u0411\\u043e\\u0454\\u043f\\u0440\\u0438\\u043f\\u0430\\u0441\\u0438 \\u0434\\u043e \\u043f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0438\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f > \\u0411\\u043e\\u0454\\u043f\\u0440\\u0438\\u043f\\u0430\\u0441\\u0438 \\u0434\\u043e \\u043f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0438\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f > \\u0411\\u043e\\u0454\\u043f\\u0440\\u0438\\u043f\\u0430\\u0441\\u0438 \\u0434\\u043e \\u043f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0438\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f > \\u0411\\u043e\\u0454\\u043f\\u0440\\u0438\\u043f\\u0430\\u0441\\u0438 \\u0434\\u043e \\u043f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0438\"}'),
(1192,	'{\"en\":\"\\u041e\\u043f\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0442\\u0430 \\u043a\\u043e\\u043b\\u0456\\u043c\\u0430\\u0442\\u043e\\u0440\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0446\\u0456\\u043b\\u0438\",\"ru\":\"\\u041e\\u043f\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0442\\u0430 \\u043a\\u043e\\u043b\\u0456\\u043c\\u0430\\u0442\\u043e\\u0440\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0446\\u0456\\u043b\\u0438\",\"ua\":\"\\u041e\\u043f\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0442\\u0430 \\u043a\\u043e\\u043b\\u0456\\u043c\\u0430\\u0442\\u043e\\u0440\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0446\\u0456\\u043b\\u0438\"}',	'{\"en\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f > \\u041e\\u043f\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0442\\u0430 \\u043a\\u043e\\u043b\\u0456\\u043c\\u0430\\u0442\\u043e\\u0440\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0446\\u0456\\u043b\\u0438\",\"ru\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u0434\\u0436\\u0435\\u043d\\u043d\\u044f > \\u041e\\u043f\\u0442\\u0438\\u0447\\u043d\\u0456 \\u0442\\u0430 \\u043a\\u043e\\u043b\\u0456\\u043c\\u0430\\u0442\\u043e\\u0440\\u043d\\u0456 \\u043f\\u0440\\u0438\\u0446\\u0456\\u043b\\u0438\",\"ua\":\"\\u0421\\u043f\\u043e\\u0440\\u0442, \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u0438\\u0439 \\u0432\\u0456\\u0434\\u043f\\u043e\\u0447\\u0438\\u043d\\u043e\\u043a > \\u041f\\u043d\\u0435\\u0432\\u043c\\u0430\\u0442\\u0438\\u043a\\u0430 \\u0442\\u0430 \\u0441\\u043f\\u043e\\u0440\\u044f\\u