u0434\\u043d\\u0430 \\u0441\\u0442\\u0430\\u043d\\u0446\\u0456\\u044f, \\u044f\\u043a\\u0430 \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0443\\u0454 \\u043d\\u0430\\u0434\\u0456\\u0439\\u043d\\u0435 \\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f \\u0434\\u043b\\u044f \\u0440\\u0456\\u0437\\u043d\\u0438\\u0445 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0440\\u043e\\u0457\\u0432 \\u044f\\u043a \\u0432\\u0434\\u043e\\u043c\\u0430, \\u0442\\u0430\\u043a \\u0456 \\u043d\\u0430 \\u0432\\u0438\\u0457\\u0437\\u0434\\u0456. \\u0412\\u043e\\u043d\\u0430 \\u043e\\u0441\\u043d\\u0430\\u0449\\u0435\\u043d\\u0430 \\u0430\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u043e\\u043c LiFePO4 \\u0454\\u043c\\u043d\\u0456\\u0441\\u0442\\u044e 1229 \\u0412\\u0442\\u00b7\\u0433\\u043e\\u0434, \\u0449\\u043e \\u0437\\u0430\\u0431\\u0435\\u0437\\u043f\\u0435\\u0447\\u0443\\u0454 \\u0442\\u0440\\u0438\\u0432\\u0430\\u043b\\u0438\\u0439 \\u0442\\u0435\\u0440\\u043c\\u0456\\u043d \\u0441\\u043b\\u0443\\u0436\\u0431\\u0438 \\u0442\\u0430 \\u0432\\u0438\\u0441\\u043e\\u043a\\u0443 \\u0435\\u0444\\u0435\\u043a\\u0442\\u0438\\u0432\\u043d\\u0456\\u0441\\u0442\\u044c. \\u0421\\u0442\\u0430\\u043d\\u0446\\u0456\\u044f \\u043c\\u0430\\u0454 \\u043f\\u043e\\u0442\\u0443\\u0436\\u043d\\u0456\\u0441\\u0442\\u044c 1500 \\u0412\\u0442 \\u0456 \\u043e\\u0441\\u043d\\u0430\\u0449\\u0435\\u043d\\u0430 \\u0440\\u0456\\u0437\\u043d\\u043e\\u043c\\u0430\\u043d\\u0456\\u0442\\u043d\\u0438\\u043c\\u0438 \\u043f\\u043e\\u0440\\u0442\\u0430\\u043c\\u0438, \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u044e\\u0447\\u0438 \\u0434\\u0432\\u0456 \\u0440\\u043e\\u0437\\u0435\\u0442\\u043a\\u0438 \\u0437\\u043c\\u0456\\u043d\\u043d\\u043e\\u0433\\u043e \\u0441\\u0442\\u0440\\u0443\\u043c\\u0443, \\u0447\\u043e\\u0442\\u0438\\u0440\\u0438 \\u043f\\u043e\\u0440\\u0442\\u0438 USB-A, \\u0434\\u0432\\u0430 \\u043f\\u043e\\u0440\\u0442\\u0438 USB-C \\u0442\\u0430 \\u0430\\u0432\\u0442\\u043e