(121,	'froala_with_languages',	'Текст всплывающего блока Обмен и возврат (в карточке товара)',	'obmin-ta-povernennya',	'',	'catalog_product',	'{\"ua\":\"\",\"ru\":\"\"}',	'',	0,	'{\"ua\":\"\",\"ru\":\"\"}',	'{\"ua\":\"<p>\\u0412\\u0456\\u0434\\u043f\\u043e\\u0432\\u0456\\u0434\\u043d\\u043e \\u0434\\u043e \\u0417\\u0430\\u043a\\u043e\\u043d\\u0443 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438 \\\"\\u041f\\u0440\\u043e \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 \\u043f\\u0440\\u0430\\u0432 \\u0441\\u043f\\u043e\\u0436\\u0438\\u0432\\u0430\\u0447\\u0456\\u0432\\\" \\u0432\\u0438 \\u043c\\u043e\\u0436\\u0435\\u0442\\u0435 \\u043f\\u0440\\u043e\\u0442\\u044f\\u0433\\u043e\\u043c 14 \\u0434\\u043d\\u0456\\u0432 \\u0437 \\u043c\\u043e\\u043c\\u0435\\u043d\\u0442\\u0443 \\u043f\\u043e\\u043a\\u0443\\u043f\\u043a\\u0438 \\u043f\\u043e\\u0432\\u0435\\u0440\\u043d\\u0443\\u0442\\u0438 \\u0442\\u043e\\u0432\\u0430\\u0440\\u0438, \\u0437\\u0430 \\u0443\\u043c\\u043e\\u0432\\u0438 \\u0432\\u0438\\u043a\\u043e\\u043d\\u0430\\u043d\\u043d\\u044f \\u0432\\u0441\\u0456\\u0445 \\u043d\\u043e\\u0440\\u043c \\u043f\\u0435\\u0440\\u0435\\u0434\\u0431\\u0430\\u0447\\u0435\\u043d\\u0438\\u0445 \\u0417\\u0430\\u043a\\u043e\\u043d\\u043e\\u043c.<\\/p><h3>\\u0423\\u043c\\u043e\\u0432\\u0438 \\u043e\\u0431\\u043c\\u0456\\u043d\\u0443\\/\\u043f\\u043e\\u0432\\u0435\\u0440\\u043d\\u0435\\u043d\\u043d\\u044f \\u0442\\u043e\\u0432\\u0430\\u0440\\u0443 \\u043d\\u0430\\u043b\\u0435\\u0436\\u043d\\u043e\\u0433\\u043e \\u044f\\u043a\\u043e\\u0441\\u0442\\u0456<\\/h3><p>\\u0421\\u0442\\u0430\\u0442\\u0442\\u044f 9. \\u0417\\u0433\\u0456\\u0434\\u043d\\u043e \\u0417\\u0430\\u043a\\u043e\\u043d\\u0443 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438 \\\"\\u041f\\u0440\\u043e \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442 \\u043f\\u0440\\u0430\\u0432 \\u0441\\u043f\\u043e\\u0436\\u0438\\u0432\\u0430\\u0447\\u0456\\u0432\\\":<\\/p><p>\\u0421\\u043f\\u043e\\u0436\\u0438\\u0432\\u0430\\u0447 \\u043c\\u0430\\u0454 \\u043f\\u0440\\u0430\\u0432\\u043e \\u043e\\u0431\\u043c\\u0456\\u043d\\u044f\\u0442\\u0438 \\u043d\\u0435\\u043f\\u0440\\u043e\\u0434\\u043e\\u0432\\u043e\\u043b\\u044c\\u0447\\u0438\\u0439 \\u0442\\u043e\\u0432\\u0430\\u0440 \\u043d\\u0430\\u043b\\u0435\\u0436\\u043d\\u043e\\u0457 \\u044f\\u043a\\u043e\\u0441\\u0442\\u0456 \\u043d\\u0430 \\u0430\\u043d\\u0430\\u043b\\u043e\\u0433\\u0456\\u0447\\u043d\\u0438\\u0439 \\u0443 \\u043f\\u0440\\u043e\\u0434\\u0430\\u0432\\u0446\\u044f, \\u0443 \\u044f\\u043a\\u043e\\u0433\\u043e \\u0432\\u0456\\u043d \\u0431\\u0443\\u0432 \\u043f\\u0440\\u0438\\u0434\\u0431\\u0430\\u043d\\u0438\\u0439, \\u044f\\u043a\\u0449\\u043e \\u0442\\u043e\\u0432\\u0430\\u0440 \\u043d\\u0435 \\u0437\\u0430\\u0434\\u043e\\u0432\\u043e\\u043b\\u044c\\u043d\\u0438\\u0432 \\u0439\\u043e\\u0433\\u043e \\u0437\\u0430 \\u0444\\u043e\\u0440\\u043c\\u043e\\u044e, \\u0433\\u0430\\u0431\\u0430\\u0440\\u0438\\u0442\\u0430\\u043c\\u0438, \\u0444\\u0430\\u0441\\u043e\\u043d\\u043e\\u043c, \\u043a\\u043e\\u043b\\u044c\\u043e\\u0440\\u043e\\u043c, \\u0440\\u043e\\u0437\\u043c\\u0456\\u0440\\u043e\\u043c \\u0430\\u0431\\u043e \\u0437 \\u0456\\u043d\\u0448\\u0438\\u0445 \\u043f\\u0440\\u0438\\u0447\\u0438\\u043d \\u043d\\u0435 \\u043c\\u043e\\u0436\\u0435 \\u0431\\u0443\\u0442\\u0438 \\u043d\\u0438\\u043c \\u0432\\u0438\\u043a\\u043e\\u0440\\u0438\\u0441\\u0442\\u0430\\u043d\\u0438\\u0439 \\u0437\\u0430 \\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u043d\\u044f\\u043c. \\u0421\\u043f\\u043e\\u0436\\u0438\\u0432\\u0430\\u0447 \\u043c\\u0430\\u0454 \\u043f\\u0440\\u0430\\u0432\\u043e \\u043d\\u0430 \\u043e\\u0431\\u043c\\u0456\\u043d \\u0442\\u043e\\u0432\\u0430\\u0440\\u0443 \\u043d\\u0430\\u043b\\u0435\\u0436\\u043d\\u043e\\u0457 \\u044f\\u043a\\u043e\\u0441\\u0442\\u0456 \\u043f\\u0440\\u043e\\u0442\\u044f\\u0433\\u043e\\u043c \\u0447\\u043e\\u0442\\u0438\\u0440\\u043d\\u0430\\u0434\\u0446\\u044f\\u0442\\u0438 \\u0434\\u043d\\u0456\\u0432, \\u043d\\u0435 \\u0440\\u0430\\u0445\\u0443\\u044e\\u0447\\u0438 \\u0434\\u043d\\u044f \\u043a\\u0443\\u043f\\u0456\\u0432\\u043b\\u0456.<\\/p><p>\\u041e\\u0431\\u043c\\u0456\\u043d \\u0442\\u043e\\u0432\\u0430\\u0440\\u0443 \\u043d\\u0430\\u043b\\u0435\\u0436\\u043d\\u043e\\u0457 \\u044f\\u043a\\u043e\\u0441\\u0442\\u0456 \\u043f\\u0440\\u043e\\u0432\\u0430\\u0434\\u0438\\u0442\\u044c\\u0441\\u044f:<\\/p><ul><li>\\u044f\\u043a\\u0449\\u043e \\u0432\\u0456\\u043d \\u043d\\u0435 \\u0432\\u0438\\u043a\\u043e\\u0440\\u0438\\u0441\\u0442\\u043e\\u0432\\u0443\\u0432\\u0430\\u0432\\u0441\\u044f;<\\/li><li>\\u044f\\u043a\\u0449\\u043e \\u0437\\u0431\\u0435\\u0440\\u0435\\u0436\\u0435\\u043d\\u043e \\u0439\\u043e\\u0433\\u043e \\u0442\\u043e\\u0432\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0432\\u0438\\u0433\\u043b\\u044f\\u0434;<\\/li><li>\\u0441\\u043f\\u043e\\u0436\\u0438\\u0432\\u0447\\u0456 \\u0432\\u043b\\u0430\\u0441\\u0442\\u0438\\u0432\\u043e\\u0441\\u0442\\u0456, \\u043f\\u043b\\u043e\\u043c\\u0431\\u0438, \\u044f\\u0440\\u043b\\u0438\\u043a\\u0438;<\\/li><li>\\u0440\\u043e\\u0437\\u0440\\u0430\\u0445\\u0443\\u043d\\u043a\\u043e\\u0432\\u0438\\u0439 \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442, \\u0432\\u0438\\u0434\\u0430\\u043d\\u0438\\u0439 \\u0441\\u043f\\u043e\\u0436\\u0438\\u0432\\u0430\\u0447\\u0435\\u0432\\u0456 \\u0440\\u0430\\u0437\\u043e\\u043c \\u0437 \\u043f\\u0440\\u043e\\u0434\\u0430\\u043d\\u0438\\u043c \\u0442\\u043e\\u0432\\u0430\\u0440\\u043e\\u043c.<\\/li><\\/ul><h3>\\u0420\\u043e\\u0437\'\\u044f\\u0441\\u043d\\u0435\\u043d\\u043d\\u044f:<\\/h3><p>\\u0422\\u043e\\u0432\\u0430\\u0440\\u043d\\u0438\\u0439 \\u0432\\u0438\\u0433\\u043b\\u044f\\u0434: \\u041d\\u043e\\u0432\\u0438\\u0439 \\u0442\\u043e\\u0432\\u0430\\u0440 \\u0440\\u0435\\u0430\\u043b\\u0456\\u0437\\u0443\\u0454\\u0442\\u044c\\u0441\\u044f \\u0437 \\u0437\\u0430\\u0432\\u043e\\u0434\\u0441\\u044c\\u043a\\u0438\\u043c\\u0438 \\u0437\\u0430\\u0445\\u0438\\u0441\\u043d\\u0438\\u043c\\u0438 \\u043f\\u043b\\u0456\\u0432\\u043a\\u0430\\u043c\\u0438, \\u0446\\u0435 \\u0454 \\u043e\\u0434\\u043d\\u0438\\u043c \\u0456\\u0437 \\u0447\\u0438\\u043d\\u043d\\u0438\\u043a\\u0456\\u0432 \\u0432\\u0438\\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u043d\\u044f \\u0442\\u043e\\u0432\\u0430\\u0440\\u043d\\u043e\\u0433\\u043e \\u0432\\u0438\\u0433\\u043b\\u044f\\u0434\\u0443. \\u0420\\u043e\\u0437\\u043a\\u0440\\u0438\\u0442\\u0430 \\u0437\\u0430\\u0440\\u044f\\u0434\\u043a\\u0430, \\u0433\\u0430\\u0440\\u043d\\u0456\\u0442\\u0443\\u0440\\u0430, \\u0431\\u0443\\u0434\\u044c-\\u044f\\u043a\\u0456 \\u043f\\u0440\\u043e\\u0432\\u043e\\u0434\\u043a\\u0438 \\u0456 \\u0431\\u0430\\u0442\\u0430\\u0440\\u0435\\u044f \\u0437\\u0430\\u043a\\u0440\\u0438\\u0442\\u0456 \\u0437\\u0430\\u0445\\u0438\\u0441\\u043d\\u0438\\u043c\\u0438 \\u043f\\u043b\\u0456\\u0432\\u043a\\u0430\\u043c\\u0438. \\u041f\\u043e\\u043a\\u0443\\u043f\\u0435\\u0446\\u044c \\u043f\\u043e\\u0432\\u0438\\u043d\\u0435\\u043d \\u043f\\u0430\\u043c\'\\u044f\\u0442\\u0430\\u0442\\u0438, \\u0449\\u043e \\u043f\\u043e\\u0448\\u043a\\u043e\\u0434\\u0436\\u0443\\u0432\\u0430\\u0442\\u0438 \\u0446\\u0456 \\u0435\\u043b\\u0435\\u043c\\u0435\\u043d\\u0442\\u0438 \\u0443\\u043f\\u0430\\u043a\\u043e\\u0432\\u043a\\u0438 \\u043d\\u0435 \\u0440\\u0435\\u043a\\u043e\\u043c\\u0435\\u043d\\u0434\\u0443\\u0454\\u0442\\u044c\\u0441\\u044f! \\u0422\\u0430\\u043a\\u043e\\u0436 \\u043f\\u043e\\u0432\\u0438\\u043d\\u043d\\u0456 \\u0431\\u0443\\u0442\\u0438 \\u0432\\u0456\\u0434\\u0441\\u0443\\u0442\\u043d\\u0456\\u043c\\u0438 \\u043f\\u043e\\u0442\\u0435\\u0440\\u0442\\u043e\\u0441\\u0442\\u0456 \\u0456 \\u043f\\u043e\\u0434\\u0440\\u044f\\u043f\\u0438\\u043d\\u0438 \\u043d\\u0430 \\u0432\\u0438\\u0440\\u043e\\u0431\\u0456.<\\/p><p>\\u041d\\u0435 \\u0432\\u0438\\u043a\\u043e\\u0440\\u0438\\u0441\\u0442\\u043e\\u0432\\u0443\\u0454\\u0442\\u044c\\u0441\\u044f: \\u0412\\u0441\\u044f \\u0435\\u043b\\u0435\\u043a\\u0442\\u044